INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('asaas-al-taveel-vol-01', 'Islamic', 'Asas al-Taweel -- Volume 1: Adam', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
INSERT INTO unit_detail (slug, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('asaas-al-taveel-vol-01', NULL, NULL, 'esoteric', '<p>This is a work of Ismaili <em>tawil</em> — the drawing-out of a scripture''s inner sense — and it takes the shape of a doctrinal treatise, not a story and not a running verse-by-verse commentary. It first sets down what such interpretation is and why it matters, then lays out the framework of the testimony and its four limits, and only afterward turns that framework onto the opening of sacred history: Adam, the tree, the pact with Iblis, the splitting of humankind into two parties, and the line of transmission that runs down to Noah. The argument moves from method to demonstration.</p>', NULL, 'asaas-al-taveel-vol-01/cover.png', 'asaas-al-taveel-vol-01/book.pdf', '2026-08-14T21:49:35Z', 'a4a2752eb0aa5e7830bf350b75e9cd00add996f8');
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('asaas-al-taveel-vol-01', 'introduction to the book', 1, 'Introduction to the Book', '<p>This is a work of Ismaili<span class="ar-inline" dir="rtl" lang="ar">تَأْوِيل</span> — the drawing-out of a scripture''s inner (<span class="ar-inline" dir="rtl" lang="ar">نَار</span>) sense — and it takes the shape of a doctrinal treatise, not a story and not a running verse-by-verse commentary. It first sets down what such interpretation is and why it matters, then lays out the framework of the testimony and its four limits, and only afterward turns that framework onto the opening of sacred history: Adam, the tree, the pact with Iblis, the splitting of humankind into two parties, and the line of transmission that runs down to Noah. The argument moves from method to demonstration.</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('asaas-al-taveel-vol-01', 'the call to inner meaning', 2, '1. The Call to Inner Meaning', '<p>In the name of God, the Most Gracious, the Most Merciful. Praise belongs to Him who bestows every grace, and may His blessing rest on Muhammad, Prophet of mercy, and on the <span class="ar-inline" dir="rtl" lang="ar">وَصِي</span> appointed as executor for the community, and on the pure Imams of his goodly line.</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('asaas-al-taveel-vol-01', 'the four limits of the testimony', 3, '2. The Four Limits of the Testimony', '<p>Turn with me, then, to the testimony itself, and look closely at how it is built. It divides into two halves — one that denies, and one that affirms. <span class="ar-inline" dir="rtl" lang="ar">لَا إِلَهَ</span> — &quot;there is no god&quot; — is the negation. <em>Illa Allah</em> — &quot;but Allah&quot; — is the affirmation. Each half is made of two words, and the words do not lie side by side as equals. The first leans on the second; the second lifts above the first. Even the small grammatical break that separates them does work: it marks the affirmation as standing higher than the negation that precedes it.</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('asaas-al-taveel-vol-01', 'adam, the tree, and the iblis pact', 4, '3. Adam, the Tree, and the Iblis Pact', '<p>I have already opened, in the book whose pillars I undertook to simplify, the chapters on faith and Islam, and I named there what faith and Islam mean. Now I want to open a different door — the door of <span class="ar-inline" dir="rtl" lang="ar">الْوِلَايَة</span>, the door of authority and friendship with God — and to recite it for the Messengers and for the first of those whom God placed in command after them, those whose obedience He bound to His own obedience. He said:</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('asaas-al-taveel-vol-01', 'two parties and the line to noah', 5, '4. Two Parties and the Line to Noah', '<p>He made for Himself a party out of His own creation, and He described the other party — the party of Satan — so that no one could mistake which side he stood on. Listen to how He names them:</p>
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('asaas-al-taveel-vol-01', 1, 'What Ismaili Interpretation Is', 'The editor''s introduction to Asas al-Ta''wil — Arif Tamir''s 1960 Beirut framing of why this 10th-century Fatimid treatise on inner interpretation was kept in private custody for a thousand years, what the Ismailis mean by ta''wil (as distinct from tafsir), why the Speaker bears revelation and the Imam- Foundation bears its inner meaning, and how al-Nu''man''s two books — Da''a''im al-Islam and this one — together form the body and soul of the Fatimid intellectual project. Sets up the six Speaker-Prophet chapters that follow: Adam, Noah, Ibrahim, Moses, Jesus, Muhammad. The seventh chapter, on the Awaited Imam, is deliberately unwritten.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('asaas-al-taveel-vol-01', 2, 'The Call to Inner Meaning', 'Al-Nu''man''s own opening of Asas al-Ta''wil. He explains why he wrote a second book after his apparent-law volume Da''a''im al-Islam, why inner interpretation has to be taught by stages — milk before solid food, suckling for two years, symbols before subtleties — and why the testimony "There is no god but Allah," from the very first day the Prophet spoke it, already contained the whole sacred law, against the common opinion that says the easy creed came first and the heavy obligations later. Sets up the structural claim that the next chapter will unfold: that every created thing is paired, outward and inward, body and soul — and that the Creator is described by none of the pairs.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('asaas-al-taveel-vol-01', 3, 'The Four Limits of the Shahada', 'Al-Nu''man opens the testimony itself and shows what is inside it. The shahada has four words; those four words stand for four limits, two above and two below. Above are the Pen and the Preserved Tablet — named in the prophetic hadith that says the first thing God created was the Pen. Below are the Speaker, the prophet who articulates the sacred law in his time, and the Silent One, the Imam-Foundation who is master of its interpretation. To recognize all four is to complete the shahada. The philosophers affirmed the upper two and called them intellect and soul, but denied the lower two and so left the testimony broken. The chapter then maps the seven Speaker-Prophets across history — Adam, Noah, Ibrahim, Moses, Jesus, Muhammad, and the awaited al-Qa''im — and the seven Imams in each cycle, the twelve successors arranged as proofs in every age, and the seven-plus-twelve nineteen that the Qur''an names. It closes on the second testimony to the Messenger as the branches of the first, and on al-Sadiq''s verdict that faith encompasses Islam but Islam does not encompass faith.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('asaas-al-taveel-vol-01', 4, 'Adam, the Tree, and the Pact of Iblis', 'Al-Nu''man opens his interpretation of the prophetic cycles at the origin of the lower hadd of Imamate itself — Adam, peace be upon him. The Qur''anic scene of the angels'' objection, the formation of Adam from clay, the long pause before the spirit, the teaching of the names, Iblis''s refusal to prostrate, the creation of Eve, the garden, the forbidden tree, the pact of respite, the fall, the repentance — every element is read on its inner side. The hadd that Iblis vacated is filled by Eve as Adam''s twelve-rank hujja. The garden is the rank of supportive knowledge, al-ta''yid. The tree is not wheat, fig, or grape, but a likeness for the Master of the Resurrection — the disclosure entrusted to him alone, seized prematurely. Adam''s stripping is the loss of the garment of piety, which is the word. His repentance restores him to the rank of caliph and Imam, and the Imamate begins from him as the architecture of the four limits requires.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('asaas-al-taveel-vol-01', 5, 'The Two Parties and the Line to Noah', 'Al-Nu''man closes the first prophetic cycle. He develops the two- parties doctrine at length, threading together the Qur''an''s own naming of Hizb Allah against the party of Satan. He refuses the popular literalism that froze the forbidden tree into wheat, fig, or grape and read human fingernails as its residue. He refuses, by name, the inherited Jewish-source tale of Adam and Eve hiding naked among the trees while God walked there asking "Where are you?" — calling out Ka''b al-Ahbar and Abdullah ibn Salam as the channels through which the material entered the tradition. He rehabilitates Adam to the rank of caliph and Imam. He gives the chain of five upper and five lower limits in the Prophet''s own voice. He walks the lineage from Adam through Seth, Idris/Enoch, and the seven Imams of the first cycle down to Lamech, who completes the cycle and hands the matter to Noah. Then he opens the chapter on Noah, Hud, and Salih, and the listener hears Noah''s people refuse him in the same shape Iblis had refused God — "you are nothing but a human being like us." The architecture''s claim on history begins to walk.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'blurb', NULL, 'Asas al-Taweel -- Volume 1: Adam', 0, NULL, 'This is a work of Ismaili tawil — the drawing-out of a scripture''s inner sense — and it takes the shape of a doctrinal treatise, not a story and not a running verse-by-verse commentary. It first sets down what such interpretation is and why it matters, then lays out the framework of the testimony and its four limits, and only afterward turns that framework onto the opening of sacred history: Adam, the tree, the pact with Iblis, the splitting of humankind into two parties, and the line of transmission that runs down to Noah. The argument moves from method to demonstration.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam', 'this is a work of ismaili tawil the drawing out of a scriptures inner sense and it takes the shape of a doctrinal treatise not a story and not a running verse by verse commentary it first sets down what such interpretation is and why it matters then lays out the framework of the testimony and its four limits and only afterward turns that framework onto the opening of sacred history adam the tree the pact with iblis the splitting of humankind into two parties and the line of transmission that runs down to noah the argument moves from method to demonstration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'introduction to the book', 'Introduction to the Book', 0, NULL, 'This is a work of Ismailiتَأْوِيل — the drawing-out of a scripture''s inner (نَار) sense — and it takes the shape of a doctrinal treatise, not a story and not a running verse-by-verse commentary. It first sets down what such interpretation is and why it matters, then lays out the framework of the testimony and its four limits, and only afterward turns that framework onto the opening of sacred history: Adam, the tree, the pact with Iblis, the splitting of humankind into two parties, and the line of transmission that runs down to Noah. The argument moves from method to demonstration.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam introduction to the book', 'this is a work of ismailiتاويل the drawing out of a scriptures inner نار sense and it takes the shape of a doctrinal treatise not a story and not a running verse by verse commentary it first sets down what such interpretation is and why it matters then lays out the framework of the testimony and its four limits and only afterward turns that framework onto the opening of sacred history adam the tree the pact with iblis the splitting of humankind into two parties and the line of transmission that runs down to noah the argument moves from method to demonstration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'introduction to the book', 'Introduction to the Book', 1, NULL, 'The figures divide along an axis the book builds early. Certain prophets — Adam, Noah — are speakers, bringers of an outward revealed law; beside each stands a foundation, an asas, who holds the hidden meaning beneath that law. Keep this pairing of the outer and the inner in view, for it is the engine of all that follows.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam introduction to the book', 'the figures divide along an axis the book builds early certain prophets adam noah are speakers bringers of an outward revealed law beside each stands a foundation an asas who holds the hidden meaning beneath that law keep this pairing of the outer and the inner in view for it is the engine of all that follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'introduction to the book', 'Introduction to the Book', 2, NULL, 'The book comes down under the name of the Ismaili دَاعِي al-Numan ibn Hayyun al-Tamimi al-Maghribi, judge of the Fatimid dynasty, who died in 363 of the Hijra. One caution about names: several words here are titles and proper names at once. "al-Mahdi (اَلْمَهْدِيّ)," "al-Qaim (الْقَائِم)," and "al-Mansur (الْمَنْصُور)" name an awaited or functional role in one place and a particular historical Fatimid ruler in another. Let the context, not the word alone, tell you which is meant.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam introduction to the book', 'the book comes down under the name of the ismaili داعي al numan ibn hayyun al tamimi al maghribi judge of the fatimid dynasty who died in 363 of the hijra one caution about names several words here are titles and proper names at once al mahdi المهدي al qaim القايم and al mansur المنصور name an awaited or functional role in one place and a particular historical fatimid ruler in another let the context not the word alone tell you which is meant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 0, NULL, 'In the name of God, the Most Gracious, the Most Merciful. Praise belongs to Him who bestows every grace, and may His blessing rest on Muhammad, Prophet of mercy, and on the وَصِي appointed as executor for the community, and on the pure Imams of his goodly line.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'in the name of god the most gracious the most merciful praise belongs to him who bestows every grace and may his blessing rest on muhammad prophet of mercy and on the وصي appointed as executor for the community and on the pure imams of his goodly line', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 1, NULL, 'Now to the matter at hand. With God''s support, and in gratitude for His help, His bounty, and His kindness, we have already put into the world one book for those who answer the call of truth — those who take hold of the rope of the Creator, who grip the trustworthy handhold, who keep to the straightest road (الطَّرِيق). That book set out the outward knowledge (الْعِلْم) of the sacred law, and we named it Daaim al-Islam (دَعَائِمُ الْإِسْلَام), the Pillars of Islam. In it we drew the limits of belief and showed the distinction between إِيمَان and islam (إِسْلَام) — between faith as an inward conviction and submission as an outward act. We laid out the obligation of وَلَايَة, the loyalty owed to the rightful guides; we set down the proofs by which the Imams are known; we gathered the requirements of duty, the chapters of what is lawful and what is forbidden, and the questions and rulings that arise — so that those who answered the call would know the outward shape of their religion, believe in it, act by it, and neither contradict it nor abandon it. That is the first frontier of education, the lowest rung in the ladder of knowledge and understanding.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'now to the matter at hand with gods support and in gratitude for his help his bounty and his kindness we have already put into the world one book for those who answer the call of truth those who take hold of the rope of the creator who grip the trustworthy handhold who keep to the straightest road الطريق that book set out the outward knowledge العلم of the sacred law and we named it daaim al islam دعايم الاسلام the pillars of islam in it we drew the limits of belief and showed the distinction between ايمان and islam اسلام between faith as an inward conviction and submission as an outward act we laid out the obligation of ولايه the loyalty owed to the rightful guides we set down the proofs by which the imams are known we gathered the requirements of duty the chapters of what is lawful and what is forbidden and the questions and rulings that arise so that those who answered the call would know the outward shape of their religion believe in it act by it and neither contradict it nor abandon it that is the first frontier of education the lowest rung in the ladder of knowledge and understanding', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 2, NULL, 'The one in whom the spirit of faith and wisdom is to be written must begin from precisely this point. He must pass from the realm of darkness (الظَّلَام) into the realm of light (النُّور). This is the first stage for the one newly born into faith: the stage of nurture at birth, the moment when the spirit of life (الْحَيَاة) is breathed into him. Consider what happens when an infant comes out of the womb into the light of the world. The outward form is repaired at once. The cord that was once the link between what was and what was not yet of him is cut. His limbs are adjusted, his skin anointed, his body swaddled with what tightens and strengthens it — so that his frame does not slacken, his joints do not weaken, his constitution does not warp, and no other ruin overtakes him while he is still soft.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the one in whom the spirit of faith and wisdom is to be written must begin from precisely this point he must pass from the realm of darkness الظلام into the realm of light النور this is the first stage for the one newly born into faith the stage of nurture at birth the moment when the spirit of life الحياه is breathed into him consider what happens when an infant comes out of the womb into the light of the world the outward form is repaired at once the cord that was once the link between what was and what was not yet of him is cut his limbs are adjusted his skin anointed his body swaddled with what tightens and strengthens it so that his frame does not slacken his joints do not weaken his constitution does not warp and no other ruin overtakes him while he is still soft', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 3, NULL, 'It is the same with the one who fails to repair the outward of his religion and set it on its feet. He stands on the edge of breaking it and ruining it. So we put into the hands of those who had answered our call what they needed in order to mend themselves and stand straight. We read the book aloud to them. We placed it in the hands of those who wished to copy it. We refused it to no one who wished to recite it whole. Each took from it according to his measure. Some — though they were few — were truly nourished by it, according to the Almighty''s word:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'it is the same with the one who fails to repair the outward of his religion and set it on its feet he stands on the edge of breaking it and ruining it so we put into the hands of those who had answered our call what they needed in order to mend themselves and stand straight we read the book aloud to them we placed it in the hands of those who wished to copy it we refused it to no one who wished to recite it whole each took from it according to his measure some though they were few were truly nourished by it according to the almightys word', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 4, NULL, 'إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَقَلِيلٌ مَّا هُمْ"Except those who believed and did righteous deeds — and how few they are."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'الا الذين امنوا وعملوا الصالحات وقليل ما هم except those who believed and did righteous deeds and how few they are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 5, NULL, 'And:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 6, NULL, 'فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ"But most of them turned away, and they do not hear."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'فاعرض اكثرهم فهم لا يسمعون but most of them turned away and they do not hear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 7, NULL, 'And of most of them He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and of most of them he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 8, NULL, 'وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ"But most people do not know."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'ولكن اكثر الناس لا يعلمون but most people do not know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 9, NULL, 'He also said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'he also said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 10, NULL, 'وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ"How many of mankind — even if you were eager — will not believe."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'وما اكثر الناس ولو حرصت بمومنين how many of mankind even if you were eager will not believe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 11, NULL, 'And:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 12, NULL, 'مِنْهُمُ الْمُؤْمِنُونَ وَأَكْثَرُهُمُ الْفَاسِقُونَ"Among them are the believers, but most of them are transgressors."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'منهم المومنون واكثرهم الفاسقون among them are the believers but most of them are transgressors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 13, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 14, NULL, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ ۖ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ"Among them are those who lie in wait, ignorant of the light."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'ومنهم من يستمع اليك وجعلنا علي قلوبهم اكنه ان يفقهوه among them are those who lie in wait ignorant of the light', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 15, NULL, 'These were the ones who said: this is the outward — we know it already, and what we see of it is useful to us. They turned from the book in disgust. They said it was the speech of the kind of people God has reported in His book as having lied to His friends, the Messengers — those of whom He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'these were the ones who said this is the outward we know it already and what we see of it is useful to us they turned from the book in disgust they said it was the speech of the kind of people god has reported in his book as having lied to his friends the messengers those of whom he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 16, NULL, 'Sayingسُبْحَانَهُ وَتَعَالَىٰ"Glorified is He, and exalted."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'sayingسبحانه وتعالي glorified is he and exalted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 17, NULL, 'And those who disbelieved said: this is only the man whom others have helped along with injustice and falsehood. They said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and those who disbelieved said this is only the man whom others have helped along with injustice and falsehood they said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 18, NULL, 'وَقَالُوٓا۟ أَسَطِيرُ ٱلْأَوَّلِينَ ٱكْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَةًۭ وَأَصِيلًۭا"They said: fables of the ancients which he has written down; they are dictated to him morning and evening."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'وقالوا اسطير الاولين اكتتبها فهي تملي عليه بكره واصيلا they said fables of the ancients which he has written down they are dictated to him morning and evening', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 19, NULL, 'This is one of the ways men deny the limits of religion. They twisted what was meant for those who came before and for others besides — the evil things the worst of preachers thought of those who turned the people away from God''s friends — and they departed from what the friends had thought concerning them. They disobeyed the command. They altered the order that had been laid out for them. They overstepped the limits. They blocked others from doing what was their duty.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'this is one of the ways men deny the limits of religion they twisted what was meant for those who came before and for others besides the evil things the worst of preachers thought of those who turned the people away from gods friends and they departed from what the friends had thought concerning them they disobeyed the command they altered the order that had been laid out for them they overstepped the limits they blocked others from doing what was their duty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 20, NULL, 'ضَلُّوا مِن قَبْلُ وَأَضَلُّوا كَثِيرًا وَضَلُّوا عَن سَوَاءِ السَّبِيلِ"They went astray before, and led many astray, and strayed from the right way."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'ضلوا من قبل واضلوا كثيرا وضلوا عن سواء السبيل they went astray before and led many astray and strayed from the right way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 21, NULL, 'Had they obeyed the command of their guardians and walked the path the community had laid out before them, they themselves would have been guided, and no one after them would have had anything to object to. God will yet set the foolish one right, in whichever case He sees fit. He will restore whatever any man has changed of His religion. He will repair what those who disobeyed Him have corrupted — by His power, His might, His provision, and His mercy, and through the success He grants to whoever holds firm to what we have laid out.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'had they obeyed the command of their guardians and walked the path the community had laid out before them they themselves would have been guided and no one after them would have had anything to object to god will yet set the foolish one right in whichever case he sees fit he will restore whatever any man has changed of his religion he will repair what those who disobeyed him have corrupted by his power his might his provision and his mercy and through the success he grants to whoever holds firm to what we have laid out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 22, NULL, 'The measure of the outward, and the portion each man received of it, did not move us to neglect them, few as they were among the many. We resolved instead to raise them to the next stage in the limits given to the responding initiate, the مُسْتَجِيب — to the stage of ramz and ishara, symbol and sign, which is the gentlest and most accessible of the higher degrees. A symbol stands in for what cannot yet be spoken plainly; a sign points toward what the listener is being made ready to see.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the measure of the outward and the portion each man received of it did not move us to neglect them few as they were among the many we resolved instead to raise them to the next stage in the limits given to the responding initiate the مستجيب to the stage of ramz and ishara symbol and sign which is the gentlest and most accessible of the higher degrees a symbol stands in for what cannot yet be spoken plainly a sign points toward what the listener is being made ready to see', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 23, NULL, 'This is the exact counterpart of the raising of children, of nourishing their bodies. After their outward form has been put right at birth, they are begun on milk — because their constitution is still too delicate for solid food, because they cannot yet digest it, because their bodies must first grow strong enough to bear it. They are eased onto firmer things in stages. It is the same with symbols and signs (آيَات). They impregnate the imagination of the listener. What is symbolized stirs him; what wisdom points to draws him; he becomes eager to hear and ready to accept. But if the same content were dropped on him whole and at once, with no preparation, falling upon him before his powers of comprehension could rise to meet it, it would harm him — as solid food harms a child who is fed it too soon. The Almighty Himself has fixed this measure when He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'this is the exact counterpart of the raising of children of nourishing their bodies after their outward form has been put right at birth they are begun on milk because their constitution is still too delicate for solid food because they cannot yet digest it because their bodies must first grow strong enough to bear it they are eased onto firmer things in stages it is the same with symbols and signs ايات they impregnate the imagination of the listener what is symbolized stirs him what wisdom points to draws him he becomes eager to hear and ready to accept but if the same content were dropped on him whole and at once with no preparation falling upon him before his powers of comprehension could rise to meet it it would harm him as solid food harms a child who is fed it too soon the almighty himself has fixed this measure when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 24, NULL, 'وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلَادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ ۖ لِمَنْ أَرَادَ أَن يُتِمَّ الرَّضَاعَةَ"And mothers shall suckle their children two full years, for those who wish to complete the suckling."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'والوالدات يرضعن اولادهن حولين كاملين لمن اراد ان يتم الرضاعه and mothers shall suckle their children two full years for those who wish to complete the suckling', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 25, NULL, 'After Daaim al-Islam, then, we composed for these same people another book, which we called Hudud al-Marifa (حُدُود الْمَعْرِفَة), the Limits of Knowledge. In it we set down the limits that prove inner (نَار) interpretation, تَأْوِيل, against the one who denies it, and that establish the inner sense, الْبَاطِن, against the one who rejects it, and we showed the manner in which its degrees are climbed. We laid out the symbols and the signs of the inner and the interpretation that benefit men of intellect — those whose road is acceptance, longing, withdrawal from worldly attachments, and the discipline of restraint.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'after daaim al islam then we composed for these same people another book which we called hudud al marifa حدود المعرفه the limits of knowledge in it we set down the limits that prove inner نار interpretation تاويل against the one who denies it and that establish the inner sense الباطن against the one who rejects it and we showed the manner in which its degrees are climbed we laid out the symbols and the signs of the inner and the interpretation that benefit men of intellect those whose road is acceptance longing withdrawal from worldly attachments and the discipline of restraint', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 26, NULL, 'When we had reached a certain measure in that work, others who wanted to attain what they had earned obliged us to compose a further book — one that would unfold for them a degree of inner interpretation and subtlety lying beyond the degree of symbol. Whoever hears any of it that seems to contradict the proper limits as we have set them out, and does not act on it accordingly — referring it on his own to something other than what he has heard, or interpreting it without the prior explanation already given — his way must be the way of those we have just described: those who hand themselves over to those who came before, who follow in their path, who stand in their footsteps, and who let themselves be clothed in the religion of their judgment.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'when we had reached a certain measure in that work others who wanted to attain what they had earned obliged us to compose a further book one that would unfold for them a degree of inner interpretation and subtlety lying beyond the degree of symbol whoever hears any of it that seems to contradict the proper limits as we have set them out and does not act on it accordingly referring it on his own to something other than what he has heard or interpreting it without the prior explanation already given his way must be the way of those we have just described those who hand themselves over to those who came before who follow in their path who stand in their footsteps and who let themselves be clothed in the religion of their judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 27, NULL, 'لِيُمَحِّصَ اللَّهُ الَّذِينَ آمَنُوا وَيَمْحَقَ الْكَافِرِينَ"That God may test those who believe and destroy the disbelievers."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'ليمحص الله الذين امنوا ويمحق الكافرين that god may test those who believe and destroy the disbelievers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 28, NULL, 'So the Almighty said, and He is the most truthful of those who speak. If only they had understood the speech of the truthful one — Jafar al-Sadiq (جَعْفَرُ الصَّادِق), the trustee — when it came to them by the mouth of one of his preachers, his duat (دَاعِي الدُّعَاة), whom he had brought into the matter. A man once said to him: "O son of the Messenger of God, before this we heard from you something else — a different aspect than this one." And he — meaning Jafar al-Sadiq — said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'so the almighty said and he is the most truthful of those who speak if only they had understood the speech of the truthful one jafar al sadiq جعفر الصادق the trustee when it came to them by the mouth of one of his preachers his duat داعي الدعاه whom he had brought into the matter a man once said to him o son of the messenger of god before this we heard from you something else a different aspect than this one and he meaning jafar al sadiq said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 29, NULL, 'Sayingإِنِّي لَأَتَكَلَّمُ بِالْكَلِمَةِ الْوَاحِدَةِ لَهَا سَبْعَةُ وُجُوهٍ"I speak a single word, and it has seven faces."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'sayingاني لاتكلم بالكلمه الواحده لها سبعه وجوه i speak a single word and it has seven faces', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 30, NULL, 'The man, astonished, said: "Seven, O son of the Messenger of God?" He said: "Yes — and seventy. And if we wished to add more, we would add."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the man astonished said seven o son of the messenger of god he said yes and seventy and if we wished to add more we would add', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 31, NULL, 'This knowledge has been put on display in proportion to the limits set for it, so that the one who has heard it and benefited from it may come to know it page by page, in its degrees. The present book, which we now set forth in its foundational form — being the first of its limits — we have called Asas al-Tawil (أُسَاسُ التَّأْوِيلِ), the Basis of Interpretation. By it we mean to explain what we had established in Daaim al-Islam, so that this book may serve as the foundation of the inner, just as the earlier book served as the foundation of the outward. From God we seek help. There is no power and no strength except in God the Almighty.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'this knowledge has been put on display in proportion to the limits set for it so that the one who has heard it and benefited from it may come to know it page by page in its degrees the present book which we now set forth in its foundational form being the first of its limits we have called asas al tawil اساس التاويل the basis of interpretation by it we mean to explain what we had established in daaim al islam so that this book may serve as the foundation of the inner just as the earlier book served as the foundation of the outward from god we seek help there is no power and no strength except in god the almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 32, NULL, 'What follows is the discourse on the interpretation of interpretation, and on the inner meaning of what is reported in hadith and revealed in scripture.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'what follows is the discourse on the interpretation of interpretation and on the inner meaning of what is reported in hadith and revealed in scripture', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 33, NULL, 'In Hudud al-Marifa, the book just named, we wrote at length to establish the science of تَأْوِيل and the الْبَاطِن, and to answer those who deny them from the Book, from the practice of the Prophet, and from the words of the Imams and the community. We said enough there, briefly as we said it. But that does not free us from publishing this present book on the side of the inner, so that it may stand as our proof in the hands of those who recite it. So we say — and from God comes success.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'in hudud al marifa the book just named we wrote at length to establish the science of تاويل and the الباطن and to answer those who deny them from the book from the practice of the prophet and from the words of the imams and the community we said enough there briefly as we said it but that does not free us from publishing this present book on the side of the inner so that it may stand as our proof in the hands of those who recite it so we say and from god comes success', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 34, NULL, 'Every intelligible thing must have an outward and an inward. Its outward is what the senses can lay hold of. Its inward is what it contains — the knowledge that lives within it, and the meaning the outer form embraces. The two are spouse and partner to each other; neither is whole without the other. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'every intelligible thing must have an outward and an inward its outward is what the senses can lay hold of its inward is what it contains the knowledge that lives within it and the meaning the outer form embraces the two are spouse and partner to each other neither is whole without the other the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 35, NULL, 'وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظَاهِرَةً وَبَاطِنَةً"And He has lavished upon you His blessings, outward and inward."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'واسبغ عليكم نعمه ظاهره وباطنه and he has lavished upon you his blessings outward and inward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 36, NULL, 'By this He told His servants that He will question them about His blessings, and He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'by this he told his servants that he will question them about his blessings and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 37, NULL, 'ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ"Then on that Day you will be asked about the bliss."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'ثم لتسالن يوميذ عن النعيم then on that day you will be asked about the bliss', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 38, NULL, 'Whoever does not know what the inner blessing is — though he knows he is answerable for it, and is supposed to be ready with his answer when he is asked — how will he answer? And the Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'whoever does not know what the inner blessing is though he knows he is answerable for it and is supposed to be ready with his answer when he is asked how will he answer and the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 39, NULL, 'وَذَرُوا ظَاهِرَ الْإِثْمِ وَبَاطِنَهُ"And forsake the outward and the inward of sin."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'وذروا ظاهر الاثم وباطنه and forsake the outward and the inward of sin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 40, NULL, 'The man who does not know the secret of sin, even as he is warned against it, stands in danger of falling into it precisely because he does not know it. Then He mentioned in His book, saying:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the man who does not know the secret of sin even as he is warned against it stands in danger of falling into it precisely because he does not know it then he mentioned in his book saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 41, NULL, 'هُوَ الَّذِي أَنزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُّحْكَمَاتٌ هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ مُتَشَابِهَاتٌ"It is He who has sent down upon you the Book; in it are verses precise in meaning — they are the foundation of the Book — and others ambiguous."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'هو الذي انزل عليك الكتاب منه ايات محكمات هن ام الكتاب واخر متشابهات it is he who has sent down upon you the book in it are verses precise in meaning they are the foundation of the book and others ambiguous', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 42, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 43, NULL, 'وَمَا يَعْلَمُ تَأْوِيلَهُ إِلَّا اللَّهُ وَالرَّاسِخُونَ فِي الْعِلْمِ"And none knows its interpretation except God and those firmly rooted in knowledge."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'وما يعلم تاويله الا الله والراسخون في العلم and none knows its interpretation except god and those firmly rooted in knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 44, NULL, 'In Hudud al-Marifa we laid out the position of those who admit interpretation but are ignorant of its true face; the position of those who deny it altogether and turn from it; and the proof against both. He also said, concerning the arrival of interpretation in its time:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'in hudud al marifa we laid out the position of those who admit interpretation but are ignorant of its true face the position of those who deny it altogether and turn from it and the proof against both he also said concerning the arrival of interpretation in its time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 45, NULL, 'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُ ۚ يَوْمَ يَأْتِي تَأْوِيلُهُ يَقُولُ الَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَاءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ"Do they wait for anything but its interpretation? On the Day when its interpretation comes, those who had forgotten it before will say: indeed, the messengers of our Lord brought the truth."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'هل ينظرون الا تاويله يوم ياتي تاويله يقول الذين نسوه من قبل قد جاءت رسل ربنا بالحق do they wait for anything but its interpretation on the day when its interpretation comes those who had forgotten it before will say indeed the messengers of our lord brought the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 46, NULL, 'The Messenger of God, peace and blessings upon him, said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the messenger of god peace and blessings upon him said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 47, NULL, 'Sayingمَا نَزَلَ عَلَيَّ مِنَ الْقُرْآنِ آيَةٌ إِلَّا وَلَهَا ظَهْرٌ وَبَطْنٌ"Not a single verse of the Quran has come down to me without an outer and an inner."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'sayingما نزل علي من القران ايه الا ولها ظهر وبطن not a single verse of the quran has come down to me without an outer and an inner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 48, NULL, 'In Hudud al-Marifa we showed the consensus of the community on the soundness of this report, and the corruption of any reading that twists it away from its meaning. We showed also what those who reject interpretation are nevertheless forced to admit without realizing it — because there are passages they cannot make sense of without granting an inner meaning, and they can find no way around it. Take the word water. By their own teaching, the Almighty meant by it in one place knowledge, and in another place death (الْمَوْت) and disbelief (الْكُفْر), and in another life in the sense of faith, and light in the sense of guidance, and darkness in the sense of error. The blind (الْعَمَى), the deaf (الصُّمّ), and the dumb (الْبُكْم) in their reading mean something other than the outward sense of those words; the "sheep of women" — and many other figures of the same kind — they explain at length in just this way. Yet when they hear things that must be granted in order to keep the absolute oneness of God and to purify Him from any likeness to His creation, suddenly they deny the very move they made elsewhere. They liken Him instead. They set up their idol and describe Him by qualities that God in His sanctity is exalted above, qualities from which His blessed name is far removed. And this after they have heard what the Almighty says in His Book about the parables He strikes for His servants:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'in hudud al marifa we showed the consensus of the community on the soundness of this report and the corruption of any reading that twists it away from its meaning we showed also what those who reject interpretation are nevertheless forced to admit without realizing it because there are passages they cannot make sense of without granting an inner meaning and they can find no way around it take the word water by their own teaching the almighty meant by it in one place knowledge and in another place death الموت and disbelief الكفر and in another life in the sense of faith and light in the sense of guidance and darkness in the sense of error the blind العمي the deaf الصم and the dumb البكم in their reading mean something other than the outward sense of those words the sheep of women and many other figures of the same kind they explain at length in just this way yet when they hear things that must be granted in order to keep the absolute oneness of god and to purify him from any likeness to his creation suddenly they deny the very move they made elsewhere they liken him instead they set up their idol and describe him by qualities that god in his sanctity is exalted above qualities from which his blessed name is far removed and this after they have heard what the almighty says in his book about the parables he strikes for his servants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 49, NULL, 'وَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ ۖ وَمَا يَعْقِلُهَا إِلَّا الْعَالِمُونَ"Such are the parables We set forth for mankind, but none understand them except those endowed with knowledge."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'وتلك الامثال نضربها للناس وما يعقلها الا العالمون such are the parables we set forth for mankind but none understand them except those endowed with knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 50, NULL, 'And He says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 51, NULL, 'Sayingإِنَّ اللَّهَ لَا يَسْتَحْيِي أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا ۚ فَأَمَّا الَّذِينَ آمَنُوا فَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا الَّذِينَ كَفَرُوا فَيَقُولُونَ مَاذَا أَرَادَ اللَّهُ بِهَٰذَا مَثَلًا ۘ يُضِلُّ بِهِ كَثِيرًا وَيَهْدِي بِهِ كَثِيرًا ۚ وَمَا يُضِلُّ بِهِ إِلَّا الْفَاسِقِينَ"Indeed, God is not ashamed to set forth the parable of a mosquito or anything above it. As for those who believe, they know it is the truth from their Lord; but as for those who disbelieve, they say, What did God intend by this parable? By it He misleads many and by it He guides many — and He misleads none but the defiantly disobedient."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'sayingان الله لا يستحيي ان يضرب مثلا ما بعوضه فما فوقها فاما الذين امنوا فيعلمون انه الحق من ربهم واما الذين كفروا فيقولون ماذا اراد الله بهذا مثلا يضل به كثيرا ويهدي به كثيرا وما يضل به الا الفاسقين indeed god is not ashamed to set forth the parable of a mosquito or anything above it as for those who believe they know it is the truth from their lord but as for those who disbelieve they say what did god intend by this parable by it he misleads many and by it he guides many and he misleads none but the defiantly disobedient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 52, NULL, 'And He says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 53, NULL, 'وَكُلًّا ضَرَبْنَا لَهُ الْأَمْثَالَ ۖ وَكُلًّا تَبَّرْنَا تَتْبِيرًا"And for each We set forth parables, and each We utterly destroyed."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'وكلا ضربنا له الامثال وكلا تبرنا تتبيرا and for each we set forth parables and each we utterly destroyed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 54, NULL, 'And He says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 55, NULL, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَٰذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ"And We have certainly set forth for mankind in this Quran every kind of parable."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'ولقد ضربنا للناس في هذا القران من كل مثل and we have certainly set forth for mankind in this quran every kind of parable', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 56, NULL, 'The Almighty also told us that the narratives of the prophets themselves carry interpretation. He said in the story of Yusuf, peace be upon him:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the almighty also told us that the narratives of the prophets themselves carry interpretation he said in the story of yusuf peace be upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 57, NULL, 'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ الْأَحَادِيثِ"And thus your Lord will choose you and teach you the interpretation of narratives."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'وكذلك يجتبيك ربك ويعلمك من تاويل الاحاديث and thus your lord will choose you and teach you the interpretation of narratives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 58, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 59, NULL, 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِن تَأْوِيلِ الْأَحَادِيثِ"And thus We established Yusuf in the land, that We might teach him the interpretation of narratives."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'وكذلك مكنا ليوسف في الارض ولنعلمه من تاويل الاحاديث and thus we established yusuf in the land that we might teach him the interpretation of narratives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 60, NULL, 'In many verses of His Book He speaks of parables, of subtleties, of interpretation. The Arabs in whose tongue the Quran was revealed knew this style well; it was in their idiom that He addressed them. Among the wonders and marvels of the Quran''s composition is precisely this: that He brings forth a single utterance which carries one meaning in its outward form and another in its inner. He made the outward form a miracle of His Messenger, and the inner form a miracle of the Imams of his Household. The inner exists only with them. No one but Muhammad, the Messenger of God, can match the outward of the Book — and he is their grandfather. No one but the Imams of his line can match its inner.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'in many verses of his book he speaks of parables of subtleties of interpretation the arabs in whose tongue the quran was revealed knew this style well it was in their idiom that he addressed them among the wonders and marvels of the qurans composition is precisely this that he brings forth a single utterance which carries one meaning in its outward form and another in its inner he made the outward form a miracle of his messenger and the inner form a miracle of the imams of his household the inner exists only with them no one but muhammad the messenger of god can match the outward of the book and he is their grandfather no one but the imams of his line can match its inner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 61, NULL, 'It is a knowledge they hold among themselves. They speak to each man according to the measure he can grasp. They give every member of the family his proper share, and they withhold from the one who must be withheld from, and they entrust the matter to those who are worthy to receive it — as the Bestower said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'it is a knowledge they hold among themselves they speak to each man according to the measure he can grasp they give every member of the family his proper share and they withhold from the one who must be withheld from and they entrust the matter to those who are worthy to receive it as the bestower said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 62, NULL, 'هَٰذَا عَطَاؤُنَا فَامْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ"This is Our gift; so bestow or withhold without reckoning."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'هذا عطاونا فامنن او امسك بغير حساب this is our gift so bestow or withhold without reckoning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 63, NULL, 'Now, with God''s help and support, we begin to put down what we promised — the interpretation of what we set out concisely in Daaim al-Islam — and we present its essence in what follows.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'now with gods help and support we begin to put down what we promised the interpretation of what we set out concisely in daaim al islam and we present its essence in what follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 64, NULL, 'This is the boundary at which we begin, in the language of the one whose hearing and whose measure of understanding you already know. God the Mighty and Sublime said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'this is the boundary at which we begin in the language of the one whose hearing and whose measure of understanding you already know god the mighty and sublime said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 65, NULL, 'وَمَا أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِ لِيُبَيِّنَ لَهُمْ"And We did not send any Messenger except in the tongue of his people, so that he might make matters clear to them."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'وما ارسلنا من رسول الا بلسان قومه ليبين لهم and we did not send any messenger except in the tongue of his people so that he might make matters clear to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 66, NULL, 'If the common people were addressed in the specialized speech of the philosophers, they would understand even less than they do. By "addressing the audience," then, we mean addressing them at the level of their understanding. We have not taken them out through the exits the people of logic and philosophy use, as some preachers have done. Upon God we rely. He is our Lord. He is the One in whose care we are kept.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'if the common people were addressed in the specialized speech of the philosophers they would understand even less than they do by addressing the audience then we mean addressing them at the level of their understanding we have not taken them out through the exits the people of logic and philosophy use as some preachers have done upon god we rely he is our lord he is the one in whose care we are kept', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 67, NULL, 'So we come to faith.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'so we come to faith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 68, NULL, 'In Daaim al-Islam we set out the chapter on faith and followed it with a chapter on the difference between faith and Islam. Here we have gathered the inner interpretation of both into a single chapter, since at the root they share one origin — and this is where we begin.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'in daaim al islam we set out the chapter on faith and followed it with a chapter on the difference between faith and islam here we have gathered the inner interpretation of both into a single chapter since at the root they share one origin and this is where we begin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 69, NULL, 'Each of the foremost Messengers, those of firm resolve, instituted two foundations for his law: an outward foundation, and an inward continuation of it. Together these two form the boundaries of his sacred law.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'each of the foremost messengers those of firm resolve instituted two foundations for his law an outward foundation and an inward continuation of it together these two form the boundaries of his sacred law', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 70, NULL, 'So Noah, peace be upon him, set up the ark. He called those who believed in him to come aboard. Whoever did not come aboard drowned and perished. Ibrahim, peace be upon him, raised up the Kaba and proclaimed the pilgrimage to mankind, calling them to circle it and perform its rites. Musa, peace be upon him, took up the staff and cast it at the one who gave him the lie, and the staff overpowered the magician at his trade. Isa, peace be upon him, set up the cross, and said to those who trusted him: "Whoever wishes to follow me, let him take up a cross with him." The foundation of Muhammad, peace be upon him, was the testimony that there is no god but God. He called the people to it, and they believed in it. He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'so noah peace be upon him set up the ark he called those who believed in him to come aboard whoever did not come aboard drowned and perished ibrahim peace be upon him raised up the kaba and proclaimed the pilgrimage to mankind calling them to circle it and perform its rites musa peace be upon him took up the staff and cast it at the one who gave him the lie and the staff overpowered the magician at his trade isa peace be upon him set up the cross and said to those who trusted him whoever wishes to follow me let him take up a cross with him the foundation of muhammad peace be upon him was the testimony that there is no god but god he called the people to it and they believed in it he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 71, NULL, 'Sayingأُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَٰهَ إِلَّا اللَّهُ ۖ فَإِذَا قَالُوهَا عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا ۖ وَحِسَابُهُمْ عَلَى اللَّهِ"I have been commanded to fight the people until they say with me: there is no god but God. If they say it, they protect from me their blood and their wealth, except by its rightful claim, and their reckoning is with God."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'sayingامرت ان اقاتل الناس حتي يقولوا لا اله الا الله فاذا قالوها عصموا مني دماءهم واموالهم الا بحقها وحسابهم علي الله i have been commanded to fight the people until they say with me there is no god but god if they say it they protect from me their blood and their wealth except by its rightful claim and their reckoning is with god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 72, NULL, '"There is no god but God" — and he has entered the Garden.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'there is no god but god and he has entered the garden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 73, NULL, 'The outward of these foundations differs from one Messenger to another, each one being something other than the rest. But the inward of all of them is the same. Each foundation holds within it the full set of limits of its bearer''s sacred law, and the whole of what God sent him with to be worshipped by. Otherwise the one sent would never have called people to that foundation, since it would not have contained, all at once, everything by which God is to be worshipped.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the outward of these foundations differs from one messenger to another each one being something other than the rest but the inward of all of them is the same each foundation holds within it the full set of limits of its bearers sacred law and the whole of what god sent him with to be worshipped by otherwise the one sent would never have called people to that foundation since it would not have contained all at once everything by which god is to be worshipped', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 74, NULL, 'The general public of this community claimed that the Messenger of God at the beginning of Islam called people only to bear witness that there is no god but God, because that was easier for them. Once they answered, he obliged them to the easier of the duties, and progressed by stages up to jihad — in which souls and wealth are spent — and, as some say, the last thing imposed was the الْوِلَايَة, the loyalty to the rightful guide.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the general public of this community claimed that the messenger of god at the beginning of islam called people only to bear witness that there is no god but god because that was easier for them once they answered he obliged them to the easier of the duties and progressed by stages up to jihad in which souls and wealth are spent and as some say the last thing imposed was the الولايه the loyalty to the rightful guide', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 75, NULL, 'The wise reject this account, because it amounts to a kind of deception. Where the matter is one of summoning men to a pledge, you do not invite them to swear, nor establish your claim to anything, except by setting before them the whole of what is required. The one called to give his hand does not pledge his hand unless the sum of what he is bound to is present in the call. The summoner then unfolds it, expounds it, explains its meanings. It is like one man calling another to the religion of Islam: the man pledges to it, since "religion" is a general statement under which the whole obligation rests. Only afterward does the caller make clear what was contained in the word. The Messenger of God, peace be upon him, when he called for the sincere saying of there is no god but God, made the Garden binding upon whoever spoke it sincerely. He was asked what sincerity in this is, and he said: "Belief in it, and knowledge of its limits."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the wise reject this account because it amounts to a kind of deception where the matter is one of summoning men to a pledge you do not invite them to swear nor establish your claim to anything except by setting before them the whole of what is required the one called to give his hand does not pledge his hand unless the sum of what he is bound to is present in the call the summoner then unfolds it expounds it explains its meanings it is like one man calling another to the religion of islam the man pledges to it since religion is a general statement under which the whole obligation rests only afterward does the caller make clear what was contained in the word the messenger of god peace be upon him when he called for the sincere saying of there is no god but god made the garden binding upon whoever spoke it sincerely he was asked what sincerity in this is and he said belief in it and knowledge of its limits', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 76, NULL, 'It has its conditions. He said: "The saying there is no god but God will continue to ward off the Lord''s wrath from this community, so long as they do not draw down from their religion. When one of them does so, his words will be thrown back at him, and it will be said to him: You have lied; you are not among the truthful."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'it has its conditions he said the saying there is no god but god will continue to ward off the lords wrath from this community so long as they do not draw down from their religion when one of them does so his words will be thrown back at him and it will be said to him you have lied you are not among the truthful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 77, NULL, 'Al-Sadiq, peace be upon him — and we have already drawn from him in Daaim al-Islam — said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'al sadiq peace be upon him and we have already drawn from him in daaim al islam said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 78, NULL, 'Sayingالْإِيمَانُ قَوْلٌ بِاللِّسَانِ وَتَصْدِيقٌ بِالْجَنَانِ وَعَمَلٌ بِالْأَرْكَانِ"Faith is a saying with the tongue, an affirmation in the heart, and an action with the limbs."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'sayingالايمان قول باللسان وتصديق بالجنان وعمل بالاركان faith is a saying with the tongue an affirmation in the heart and an action with the limbs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 79, NULL, 'And he said: "Faith is wholly action, and speech is one part of that action." He went on to describe how faith is parcelled out among the parts of a man — each part of him entrusted with an action that counts as faith, distinct from what is entrusted to the others — and he spoke of all this in a long discourse which is set down in full in Daaim al-Islam. All of it makes one thing necessary: that the testimony embrace the whole of what the sacred law requires. It is established about the Messenger of God, peace and blessings upon him, that when he stood up against the polytheists, he invited them to it. If they answered him and bore witness, he brought them under the rule of Islam and ceased fighting them, and their wealth was made safe except for what Islam claims from it. If they refused, he called them to pay the جِزْيَة from their own hand while in submission. If they refused even that, he fought them. He held the outward sacred law to be inseparable from the rule of Islam, the rule by which a man becomes inviolate in his life and his property — except for what is its right. The جِزْيَة takes the place of the testimony of there is no god but God and of the acknowledgment of the Prophet; likewise the believer received under a covenant must acknowledge it. This is what God the Mighty and Sublime said in the story of Ibrahim, peace be upon him, when his Lord said to him:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'and he said faith is wholly action and speech is one part of that action he went on to describe how faith is parcelled out among the parts of a man each part of him entrusted with an action that counts as faith distinct from what is entrusted to the others and he spoke of all this in a long discourse which is set down in full in daaim al islam all of it makes one thing necessary that the testimony embrace the whole of what the sacred law requires it is established about the messenger of god peace and blessings upon him that when he stood up against the polytheists he invited them to it if they answered him and bore witness he brought them under the rule of islam and ceased fighting them and their wealth was made safe except for what islam claims from it if they refused he called them to pay the جزيه from their own hand while in submission if they refused even that he fought them he held the outward sacred law to be inseparable from the rule of islam the rule by which a man becomes inviolate in his life and his property except for what is its right the جزيه takes the place of the testimony of there is no god but god and of the acknowledgment of the prophet likewise the believer received under a covenant must acknowledge it this is what god the mighty and sublime said in the story of ibrahim peace be upon him when his lord said to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 80, NULL, 'أَسْلِمْ ۖ قَالَ أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ"Submit. He said: I have submitted to the Lord of the Worlds."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'اسلم قال اسلمت لرب العالمين submit he said i have submitted to the lord of the worlds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 81, NULL, '— meaning the One who brought him up in wisdom. And he said: "Death is the lord of the two distresses." Ibrahim laid this charge upon his sons, and Yaqub did the same:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'meaning the one who brought him up in wisdom and he said death is the lord of the two distresses ibrahim laid this charge upon his sons and yaqub did the same', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 82, NULL, 'يَا بَنِيَّ إِنَّ اللَّهَ اصْطَفَىٰ لَكُمُ الدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ"O my sons, God has chosen for you the religion, so do not die except as Muslims — and I am a Muslim."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'يا بني ان الله اصطفي لكم الدين فلا تموتن الا وانتم مسلمون o my sons god has chosen for you the religion so do not die except as muslims and i am a muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 83, NULL, 'Islam is the testimony to God by oneness, and to the Messenger by the message. Whoever bears witness to it is bound to do so in truth and sincerity. If he does not, his account is with God. As the Messenger of God, peace be upon him, said: "His testimony has not lost him anything with God — if God does not save him by it, He still rewards him for it." For it is established in the law that the man who testifies to something he is not fit to testify to, who does not stand on its truths, who does not know the one for whom or against whom he gives evidence — his testimony is not accepted and is overturned in its time. How then could a testimony be accepted in the greatest of all matters when the man has put off the work of becoming fit to give it? In this great testimony, whose weight the one who carries it himself attests to, and whose danger is great, knowing its reality and bearing witness to it both outwardly and inwardly, believing in it and discharging its conditions and obligations, is binding on the one who testifies. Only then is the testimony accepted from him, and only then is his reward not turned away. When he is ignorant of any part of it, or denies any part of it, his testimony is incomplete and will not be accepted.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'islam is the testimony to god by oneness and to the messenger by the message whoever bears witness to it is bound to do so in truth and sincerity if he does not his account is with god as the messenger of god peace be upon him said his testimony has not lost him anything with god if god does not save him by it he still rewards him for it for it is established in the law that the man who testifies to something he is not fit to testify to who does not stand on its truths who does not know the one for whom or against whom he gives evidence his testimony is not accepted and is overturned in its time how then could a testimony be accepted in the greatest of all matters when the man has put off the work of becoming fit to give it in this great testimony whose weight the one who carries it himself attests to and whose danger is great knowing its reality and bearing witness to it both outwardly and inwardly believing in it and discharging its conditions and obligations is binding on the one who testifies only then is the testimony accepted from him and only then is his reward not turned away when he is ignorant of any part of it or denies any part of it his testimony is incomplete and will not be accepted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 84, NULL, 'The man who stands in the secret of the wisdom God has entrusted to His friends — having made it a miracle for them — sees that the testimony there is no god but God contained, all at once, the affirmation of God''s oneness, the acknowledgment of His Messenger, the recognition of the Imam of His religion and his limits, the duty of obedience to them, the وَلَايَة owed to them, and the acceptance of their command. It contained everything by which God is worshipped. That is why it became the foundation of the sacred law, and that is why the Prophet, peace and blessings upon him, called the people to it and made the Garden binding upon whoever testifies to it sincerely. He showed that its sincerity is belief in it, knowledge of its limits, and the performance of its rights — and that the letters of the testimony are what give it utterance, while what is signified by it is what is contained within it, since it is the expression of what is spoken aloud. That is why al-Sadiq (اَلصَّادِق), peace be upon him, said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the man who stands in the secret of the wisdom god has entrusted to his friends having made it a miracle for them sees that the testimony there is no god but god contained all at once the affirmation of gods oneness the acknowledgment of his messenger the recognition of the imam of his religion and his limits the duty of obedience to them the ولايه owed to them and the acceptance of their command it contained everything by which god is worshipped that is why it became the foundation of the sacred law and that is why the prophet peace and blessings upon him called the people to it and made the garden binding upon whoever testifies to it sincerely he showed that its sincerity is belief in it knowledge of its limits and the performance of its rights and that the letters of the testimony are what give it utterance while what is signified by it is what is contained within it since it is the expression of what is spoken aloud that is why al sadiq الصادق peace be upon him said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 85, NULL, 'Sayingإِنَّ اللَّهَ تَعَالَىٰ لَمَّا خَلَقَ الْحُرُوفَ أَوَّلًا، عَرَّفَ بِالْحُرُوفِ الْأَسْمَاءَ، وَبِالْأَسْمَاءِ عَرَّفَ الْعِبَادَ"When God first created the letters, He made the names known by the letters, and by the names He made the people known."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'sayingان الله تعالي لما خلق الحروف اولا عرف بالحروف الاسماء وبالاسماء عرف العباد when god first created the letters he made the names known by the letters and by the names he made the people known', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 86, NULL, 'So empty your hearts of created things in order to hear wisdom. Accept it. Govern it as it has the right to be governed. Then its lights will dawn on you, and it will unveil its realities and its secrets to you. For this is the testimony that there is no god but God — the testimony that is binding.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'so empty your hearts of created things in order to hear wisdom accept it govern it as it has the right to be governed then its lights will dawn on you and it will unveil its realities and its secrets to you for this is the testimony that there is no god but god the testimony that is binding', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 87, NULL, 'In its outward sense, this means that God the Almighty is the One and only God, with no partner. He stands alone in divinity, and He is one in a way none of His creatures is one. The name "one" can fall upon a creature, and at the outward level this is true. But if you turn from that outward sense to the inward secondary sense, you find that the creature is paired. It needs whatever it has been set beside or compared with. A human being and the other animals can each be called one in number, yet each stands as a composite. So too if you consider man as a body and a soul: the body is the outer, the soul the inner — the same pattern we set out above.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'in its outward sense this means that god the almighty is the one and only god with no partner he stands alone in divinity and he is one in a way none of his creatures is one the name one can fall upon a creature and at the outward level this is true but if you turn from that outward sense to the inward secondary sense you find that the creature is paired it needs whatever it has been set beside or compared with a human being and the other animals can each be called one in number yet each stands as a composite so too if you consider man as a body and a soul the body is the outer the soul the inner the same pattern we set out above', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 88, NULL, 'In the same way, nothing in the world is without two essences, nor without two qualities — hot and humid, or hot and dry, or cold and humid, or cold and dry. Nothing is without two conditions — either witnessed or absent. Nothing is without two forms — either small or large. Nothing is without two kinds — animal or human, fine or dense, heavy or light. The pairs of contrast and opposition are too many to list. The Almighty made all these qualities plain among the conditions of His creation, and yet He Himself cannot be described by any of them. He is not non-existent; rather, He exists. He is established as the Sign, and the signs are what He created. He is clear of every one of them. Nothing resembles Him. Nothing is like Him.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'in the same way nothing in the world is without two essences nor without two qualities hot and humid or hot and dry or cold and humid or cold and dry nothing is without two conditions either witnessed or absent nothing is without two forms either small or large nothing is without two kinds animal or human fine or dense heavy or light the pairs of contrast and opposition are too many to list the almighty made all these qualities plain among the conditions of his creation and yet he himself cannot be described by any of them he is not non existent rather he exists he is established as the sign and the signs are what he created he is clear of every one of them nothing resembles him nothing is like him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 89, NULL, 'The Almighty said: but of it there is one whose interpretation will yet come — a verse whose meaning will only become clear in its own appointed time. The general public take this kind of speech as a metaphor by which God addressed the Arabs in their own tongue, since a man who says "he is not like me" or "he is not like so-and-so who does such-and-such" is invoking only the name and nothing more. They treat it as pure analogy, and they note that the Arabs themselves have many proverbs of this kind. And God has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'the almighty said but of it there is one whose interpretation will yet come a verse whose meaning will only become clear in its own appointed time the general public take this kind of speech as a metaphor by which god addressed the arabs in their own tongue since a man who says he is not like me or he is not like so and so who does such and such is invoking only the name and nothing more they treat it as pure analogy and they note that the arabs themselves have many proverbs of this kind and god has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 90, NULL, 'Sayingيَا ابْنَ آدَمَ أَطِعْنِي أَجْعَلْكَ مَثَلِي، تَحْيَا وَلَا تَمُوتُ، وَتَعِزُّ وَلَا تَذِلُّ، وَتَغْنَى وَلَا تَفْتَقِرُ"O son of Adam, obey Me, and I will make you like Myself — living without dying, mighty without being humbled, rich without being impoverished."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'sayingيا ابن ادم اطعني اجعلك مثلي تحيا ولا تموت وتعز ولا تذل وتغني ولا تفتقر o son of adam obey me and i will make you like myself living without dying mighty without being humbled rich without being impoverished', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the call to inner meaning', '1. The Call to Inner Meaning', 91, NULL, 'All of this has an explanation whose recollection will come, God willing, in its proper place. Were we to take it up here in full, our exposition of the shahada would be cut short before it has fairly begun. So we turn now to it.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 1 the call to inner meaning', 'all of this has an explanation whose recollection will come god willing in its proper place were we to take it up here in full our exposition of the shahada would be cut short before it has fairly begun so we turn now to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 0, NULL, 'Turn with me, then, to the testimony itself, and look closely at how it is built. It divides into two halves — one that denies, and one that affirms. لَا إِلَهَ — "there is no god" — is the negation. Illa Allah — "but Allah" — is the affirmation. Each half is made of two words, and the words do not lie side by side as equals. The first leans on the second; the second lifts above the first. Even the small grammatical break that separates them does work: it marks the affirmation as standing higher than the negation that precedes it.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'turn with me then to the testimony itself and look closely at how it is built it divides into two halves one that denies and one that affirms لا اله there is no god is the negation illa allah but allah is the affirmation each half is made of two words and the words do not lie side by side as equals the first leans on the second the second lifts above the first even the small grammatical break that separates them does work it marks the affirmation as standing higher than the negation that precedes it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 1, NULL, 'Picture the sentence as a vertical thing, not a horizontal one. The negation is the lower limit. The affirmation is the upper limit. The first word of the affirmation — Allah — is the highest boundary the testimony can reach; the word joined to it just beneath, the إِلَّا, is the next boundary down. Then, descending further, the second word of the negation marks the lower boundaries, and the word joined to that one, beneath it again, completes the lower side. Four words. Four limits. A small ladder placed in the mouth of every believer.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'picture the sentence as a vertical thing not a horizontal one the negation is the lower limit the affirmation is the upper limit the first word of the affirmation allah is the highest boundary the testimony can reach the word joined to it just beneath the الا is the next boundary down then descending further the second word of the negation marks the lower boundaries and the word joined to that one beneath it again completes the lower side four words four limits a small ladder placed in the mouth of every believer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 2, NULL, 'The pair of words that meet at the limit of affirmation, and the pair that meet at the limit of negation, function as two and no more. If they were treated as one indissoluble compound, the joined pair would become loftier than anything else and more crowded with meaning than language can carry — they would be God Himself, which is impossible. So the words must hold their places: paired, leaning, but distinct.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the pair of words that meet at the limit of affirmation and the pair that meet at the limit of negation function as two and no more if they were treated as one indissoluble compound the joined pair would become loftier than anything else and more crowded with meaning than language can carry they would be god himself which is impossible so the words must hold their places paired leaning but distinct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 3, NULL, 'And by Allah, this points to the noblest of all upper and lower boundaries, even though each is joined to the others and dependent on them, and even though each carries fewer letters than the rest, and even though the final word gathers in just three letters — alif, lam, and the disjunctive break — three letters that, between them, summarize every letter the testimony uses. This is the sentence of the saying within the limits of the testimony, and I will set it out for those who listen, by the grace of Allah upon me and upon you.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'and by allah this points to the noblest of all upper and lower boundaries even though each is joined to the others and dependent on them and even though each carries fewer letters than the rest and even though the final word gathers in just three letters alif lam and the disjunctive break three letters that between them summarize every letter the testimony uses this is the sentence of the saying within the limits of the testimony and i will set it out for those who listen by the grace of allah upon me and upon you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 4, NULL, 'I begin from a report transmitted from the Messenger of Allah, peace and blessings be upon him, carried by both the elect and the general public:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'i begin from a report transmitted from the messenger of allah peace and blessings be upon him carried by both the elect and the general public', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 5, NULL, 'Sayingأَوَّلُ مَا خَلَقَ اللَّهُ الْقَلَمَ، ثُمَّ أَجْرَى نَهَرًا أَحْلَى مِنَ الْعَسَلِ، وَأَبْيَضَ مِنَ اللَّبَنِ، وَأَلْيَنَ مِنَ الزُّبْدِ، ثُمَّ خَلَقَ اللَّوْحَ الْمَحْفُوظَ الَّذِي ذَكَرَهُ اللَّهُ تَعَالَى فِي كِتَابِهِ الْعَزِيزِ"The first thing Allah Almighty created was the Pen. Then He set running a river sweeter than honey, whiter than milk, and softer than butter. Then He created the Preserved Tablet, which Allah Almighty mentioned in His mighty Book."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingاول ما خلق الله القلم ثم اجري نهرا احلي من العسل وابيض من اللبن والين من الزبد ثم خلق اللوح المحفوظ الذي ذكره الله تعالي في كتابه العزيز the first thing allah almighty created was the pen then he set running a river sweeter than honey whiter than milk and softer than butter then he created the preserved tablet which allah almighty mentioned in his mighty book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 6, NULL, 'The general public carried this report toward what they already knew. Pens, they said, are made of reed, and tablets are made of wood — they have seen as much with their own eyes. They never turned to consider that these are names, titles, and proverbs that need to be uncovered, unveiled, and explained. This is from the interpretation of the hadith that Allah, the Almighty, has placed in our care.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the general public carried this report toward what they already knew pens they said are made of reed and tablets are made of wood they have seen as much with their own eyes they never turned to consider that these are names titles and proverbs that need to be uncovered unveiled and explained this is from the interpretation of the hadith that allah the almighty has placed in our care', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 7, NULL, 'The Pen is the highest limit Allah has set for His servants — a limit they may not transgress. He has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the pen is the highest limit allah has set for his servants a limit they may not transgress he has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 8, NULL, 'وَمَن يَتَعَدَّ حُدُودَ اللَّهِ فَقَدْ ظَلَمَ نَفْسَهُ"Whoever transgresses the limits of Allah has wronged his own soul."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'ومن يتعد حدود الله فقد ظلم نفسه whoever transgresses the limits of allah has wronged his own soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 9, NULL, 'The Almighty stands above all the boundaries. He has erected them for His creation beneath Himself, so that His servants might reach the knowledge (الْعِلْم) of Him by stepping along them, and so that creation might be led to command and prohibition. The Pen is the bearer of the knowledge it received from Allah, glorified and exalted, and that knowledge it fixed in the Tablet. The Tablet then drew the limits of God beneath itself — meaning that, sitting below the Pen, the Tablet took its knowledge from the Pen, and so it became, in relation to it, both from it and for it.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the almighty stands above all the boundaries he has erected them for his creation beneath himself so that his servants might reach the knowledge العلم of him by stepping along them and so that creation might be led to command and prohibition the pen is the bearer of the knowledge it received from allah glorified and exalted and that knowledge it fixed in the tablet the tablet then drew the limits of god beneath itself meaning that sitting below the pen the tablet took its knowledge from the pen and so it became in relation to it both from it and for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 10, NULL, 'These are the two upper boundaries I have named. As for the river that Allah Almighty made to flow for the Pen, He has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'these are the two upper boundaries i have named as for the river that allah almighty made to flow for the pen he has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 11, NULL, 'Sayingوَأَن لَّوِ ٱسْتَقَامُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَاهُم مَّاءً غَدَقًا"And if they had remained on the right way, We would have given them water in abundance."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingوان لو استقاموا علي الطريقه لاسقيناهم ماء غدقا and if they had remained on the right way we would have given them water in abundance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 12, NULL, 'The way is the prophet who speaks in his time, and the imam in his time after him. The water is abundant knowledge. And He said — and He is the most truthful of all who speak:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the way is the prophet who speaks in his time and the imam in his time after him the water is abundant knowledge and he said and he is the most truthful of all who speak', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 13, NULL, 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَائِقَ وَمَا كُنَّا عَنِ ٱلْخَلْقِ غَافِلِينَ"And We have created above you seven ways, and We are not heedless of creation."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'ولقد خلقنا فوقكم سبع طرايق وما كنا عن الخلق غافلين and we have created above you seven ways and we are not heedless of creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 14, NULL, 'I will return to this in full, in its proper place.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'i will return to this in full in its proper place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 15, NULL, 'What the general public confirmed about the interpretation of the esoteric is what they had evidence of in their own eyes: that water comes from the sky onto the righteous land and onto the immoral alike. They read the verse on its surface — that the way dispenses water, meaning literal water — and they noted that Allah has said, of creatures generally, that if they had stood upright before their guardian (وَلِيّ) they would have been given the most abundant knowledge. So far so good. But the Almighty''s words, "that We may try them therein," mean: that We may test them, see what they say, and teach them about it. Then He continued:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'what the general public confirmed about the interpretation of the esoteric is what they had evidence of in their own eyes that water comes from the sky onto the righteous land and onto the immoral alike they read the verse on its surface that the way dispenses water meaning literal water and they noted that allah has said of creatures generally that if they had stood upright before their guardian ولي they would have been given the most abundant knowledge so far so good but the almightys words that we may try them therein mean that we may test them see what they say and teach them about it then he continued', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 16, NULL, 'وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِ يَسْلُكْهُ عَذَابًا صَعَدًا"And whoever turns away from the remembrance of his Lord, He will lead him into an ever-increasing torment."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'ومن يعرض عن ذكر ربه يسلكه عذابا صعدا and whoever turns away from the remembrance of his lord he will lead him into an ever increasing torment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 17, NULL, 'Notice what He says: whoever turned away from his guardian, the punishment of God became his — and He called him a remembrance, that is, a person of remembrance, so that the thing was named after the one who carries it. This naming-after is well known among the Arabs. They will call a thing by what is suited to it and to its owner. They call الْمَزَادَة, the water-skin, a رَاوِيَة, a "narrator," even though in their tongue the رَاوِيَة is properly the camel that carries the water — so they named the skin after the camel that bears it. Their language is full of such transferences. And Allah Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'notice what he says whoever turned away from his guardian the punishment of god became his and he called him a remembrance that is a person of remembrance so that the thing was named after the one who carries it this naming after is well known among the arabs they will call a thing by what is suited to it and to its owner they call المزاده the water skin a راويه a narrator even though in their tongue the راويه is properly the camel that carries the water so they named the skin after the camel that bears it their language is full of such transferences and allah almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 18, NULL, 'Sayingقَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًا ۝ رَّسُولًا"Indeed, Allah has sent down to you a Reminder — a Messenger."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingقد انزل الله اليكم ذكرا رسولا indeed allah has sent down to you a reminder a messenger', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 19, NULL, 'He called the Messenger a Reminder (ذِكْر) because the Messenger is the bearer of the remembrance.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'he called the messenger a reminder ذكر because the messenger is the bearer of the remembrance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 20, NULL, 'Then Allah Almighty established, in correspondence with these two upper spiritual limits, two lower physical limits — and these are the اَلنَّاطِق, the Speaker, and the اَلصَّامِت, the Silent One. The Speaker is the messenger who comes with a message and articulates a law; the Speakers are seven — Adam, Noah, Abraham, Moses, Jesus, Muhammad, and al-Qaim, the awaited. The Silent One is the Speaker''s successor after him, from whom the Imams come down in succession; he is the one entrusted with the affairs of the esoteric mission during the Speaker''s own lifetime. The foundational Silent Ones among us are likewise seven — Seth, Shem, Isaac, Aaron, Simeon, Ali, and the Mahdi.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'then allah almighty established in correspondence with these two upper spiritual limits two lower physical limits and these are the الناطق the speaker and the الصامت the silent one the speaker is the messenger who comes with a message and articulates a law the speakers are seven adam noah abraham moses jesus muhammad and al qaim the awaited the silent one is the speakers successor after him from whom the imams come down in succession he is the one entrusted with the affairs of the esoteric mission during the speakers own lifetime the foundational silent ones among us are likewise seven seth shem isaac aaron simeon ali and the mahdi', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 21, NULL, 'The Speaker is the master of the sacred law, and the Silent One is the foundation of that sacred law within the Speaker''s era and the master of its interpretation. The Messenger utters the manifest; the foundation is silent regarding that manifest — that is, from the manifest he conducts the believers toward the subtle, the inner (نَار) meaning that the Prophet himself has already affirmed. The arrangement mirrors the one above: as the Pen is to the knowledge it lays in the Tablet, and as the Tablet sits beneath the Pen, so the Silent One sits beneath the Tablet.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the speaker is the master of the sacred law and the silent one is the foundation of that sacred law within the speakers era and the master of its interpretation the messenger utters the manifest the foundation is silent regarding that manifest that is from the manifest he conducts the believers toward the subtle the inner نار meaning that the prophet himself has already affirmed the arrangement mirrors the one above as the pen is to the knowledge it lays in the tablet and as the tablet sits beneath the pen so the silent one sits beneath the tablet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 22, NULL, 'When the house that God Almighty has established holds these two lower boundaries as a place of transformation, and the bodies in that house are mortal, then by the wisdom of God the house cannot be left empty of an argument — a اَلْحُجَّة, a living proof. So Allah Almighty established a foundation after the Speaker to take his place in the apparent matter and in the other duties the Speaker had been performing, and He instructed that foundation to appoint a اَلْحُجَّة for himself, to entrust the اَلْحُجَّة with the knowledge of interpretation, and to install it with him just as that knowledge had been installed with the Speaker before. Then, after that اَلْحُجَّة, He established another اَلْحُجَّة before him, and ordered him likewise to take a اَلْحُجَّة for himself — according to the pattern that the Sunnah of Allah Almighty has established. He has said in His mighty Book:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'when the house that god almighty has established holds these two lower boundaries as a place of transformation and the bodies in that house are mortal then by the wisdom of god the house cannot be left empty of an argument a الحجه a living proof so allah almighty established a foundation after the speaker to take his place in the apparent matter and in the other duties the speaker had been performing and he instructed that foundation to appoint a الحجه for himself to entrust the الحجه with the knowledge of interpretation and to install it with him just as that knowledge had been installed with the speaker before then after that الحجه he established another الحجه before him and ordered him likewise to take a الحجه for himself according to the pattern that the sunnah of allah almighty has established he has said in his mighty book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 23, NULL, 'وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا"And you will not find any change in the Sunnah of Allah."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'ولن تجد لسنه الله تبديلا and you will not find any change in the sunnah of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 24, NULL, 'So this continues, until the role of that one Speaker has turned over seven Imams.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'so this continues until the role of that one speaker has turned over seven imams', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 25, NULL, 'The Speakers themselves, as I said, are seven: Adam, Noah, Abraham, Moses, Jesus, Muhammad, and al-Qaim of the Age — may God''s blessings be upon them. Six of them are designated by a covenant. The seventh is Adam, who is not, and of him He said in His mighty Book:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the speakers themselves as i said are seven adam noah abraham moses jesus muhammad and al qaim of the age may gods blessings be upon them six of them are designated by a covenant the seventh is adam who is not and of him he said in his mighty book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 26, NULL, 'وَلَقَدْ عَهِدْنَا إِلَىٰ آدَمَ مِن قَبْلُ فَنَسِيَ وَلَمْ نَجِدْ لَهُۥ عَزْمًا"And We had already taken a promise from Adam before, but he forgot, and We found in him no firm determination."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'ولقد عهدنا الي ادم من قبل فنسي ولم نجد له عزما and we had already taken a promise from adam before but he forgot and we found in him no firm determination', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 27, NULL, 'He is telling us that Adam, peace be upon him, has no firm determination. Every Speaker — whether messenger or imam — has twelve successors in his time. I will mention the twelve and the seven in due course, God willing.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'he is telling us that adam peace be upon him has no firm determination every speaker whether messenger or imam has twelve successors in his time i will mention the twelve and the seven in due course god willing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 28, NULL, 'The four words of the testimony, then, stand as the likeness of these four limits. Whoever recognizes them, accepts them, and bears witness to them has completed the limits of the testimony. The testimony gathers them, and gathers its boundaries together. As for those who affirmed the Creator Almighty by their own claim — from among the philosophers, the logicians, and others — and yet denied the messengers, what did they do? They affirmed the two upper boundaries, but they named them by other than these two names. Instead of "Pen" and "Tablet" they called them "the Intellect" and "the Soul." But they did not know the two lower boundaries, the Speaker and the Silent One. For them the testimony was never established, because they acknowledged a part and denied the rest.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the four words of the testimony then stand as the likeness of these four limits whoever recognizes them accepts them and bears witness to them has completed the limits of the testimony the testimony gathers them and gathers its boundaries together as for those who affirmed the creator almighty by their own claim from among the philosophers the logicians and others and yet denied the messengers what did they do they affirmed the two upper boundaries but they named them by other than these two names instead of pen and tablet they called them the intellect and the soul but they did not know the two lower boundaries the speaker and the silent one for them the testimony was never established because they acknowledged a part and denied the rest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 29, NULL, 'And as for those I shall call the outwardists — those of the "people of refuge" who hold fast to the testimony and to the outward marks of Islam, who acknowledge the Tablet, the Pen, and the Speaker among the prophets — they did not have proper knowledge of these matters either. They professed something other than what is true, and so they did not complete the testimony. From them this incomplete testimony is accepted only to this extent: that their blood is spared and their wealth is made inviolable. They are also prevented from being counted among the jizya-payers — for the Prophet established that for them, by the command of Allah Almighty, when they became Muslim.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'and as for those i shall call the outwardists those of the people of refuge who hold fast to the testimony and to the outward marks of islam who acknowledge the tablet the pen and the speaker among the prophets they did not have proper knowledge of these matters either they professed something other than what is true and so they did not complete the testimony from them this incomplete testimony is accepted only to this extent that their blood is spared and their wealth is made inviolable they are also prevented from being counted among the jizya payers for the prophet established that for them by the command of allah almighty when they became muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 30, NULL, 'This last point asks for a word about Islam and إِيمَان, since the two are not the same. Islam is a word drawn from salam — reconciliation, surrender — the casting of one''s hands into obedience. إِيمَان, faith, is a limit that follows after Islam: it is the knowledge of the limits of the testimony, the belief in them, and the rendering of their due. And this is sincerity. The Messenger of Allah, peace and blessings upon him, said of one who is sincere to the testimony that Paradise has been promised to him; and he told us that the testimony is returned upon whoever is not sincere to it; and that one''s religion is diminished by however much one''s sincerity falls short. So the testimony is the root of the religion — indeed the whole religion is in it — and the call to it is as I have described.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'this last point asks for a word about islam and ايمان since the two are not the same islam is a word drawn from salam reconciliation surrender the casting of ones hands into obedience ايمان faith is a limit that follows after islam it is the knowledge of the limits of the testimony the belief in them and the rendering of their due and this is sincerity the messenger of allah peace and blessings upon him said of one who is sincere to the testimony that paradise has been promised to him and he told us that the testimony is returned upon whoever is not sincere to it and that ones religion is diminished by however much ones sincerity falls short so the testimony is the root of the religion indeed the whole religion is in it and the call to it is as i have described', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 31, NULL, 'Now look with me at the count of its letters, and at what it signifies and bears witness to. La ilaha illa Allah contains seven syllabic strokes — and this is a proof and a likeness for the seven Speakers, and for the seven Imams in the role of every Speaker. These I have already named for you, and they are the signs (آيَات) of Allah that He has mentioned in His Book and in His speech. He has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'now look with me at the count of its letters and at what it signifies and bears witness to la ilaha illa allah contains seven syllabic strokes and this is a proof and a likeness for the seven speakers and for the seven imams in the role of every speaker these i have already named for you and they are the signs ايات of allah that he has mentioned in his book and in his speech he has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 32, NULL, 'Sayingوَجَعَلْنَا ٱبْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةً"And We made the son of Mary and his mother a sign."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingوجعلنا ابن مريم وامه ءايه and we made the son of mary and his mother a sign', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 33, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 34, NULL, 'إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ"Indeed, the Messiah, son of Mary, is the Messenger of Allah and His Word, which He bestowed upon Mary."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'انما المسيح عيسي ابن مريم رسول الله وكلمته القاها الي مريم indeed the messiah son of mary is the messenger of allah and his word which he bestowed upon mary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 35, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 36, NULL, 'إِذْ قَالَتِ ٱلْمَلَـٰٓئِكَةُ يَـٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ"When the angels said, O Mary, indeed Allah gives you good tidings of a Word from Him whose name will be the Messiah, Isa, son of Maryam."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'اذ قالت المليكه يمريم ان الله يبشرك بكلمه منه اسمه المسيح عيسي ابن مريم when the angels said o mary indeed allah gives you good tidings of a word from him whose name will be the messiah isa son of maryam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 37, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 38, NULL, 'Sayingسَنُرِيهِمْ ءَايَـٰتِنَا فِى ٱلْـَٔافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ"We will show them Our signs in the horizons and within themselves until it becomes clear to them that it is the truth."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingسنريهم ءايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق we will show them our signs in the horizons and within themselves until it becomes clear to them that it is the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 39, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 40, NULL, 'Sayingوَفِى ٱلْأَرْضِ ءَايَـٰتٌ لِّلْمُوقِنِينَ ۝ وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ"And in the earth are signs for the certain in faith, and in your own selves — do you not then see?"', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingوفي الارض ءايت للموقنين وفي انفسكم افلا تبصرون and in the earth are signs for the certain in faith and in your own selves do you not then see', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 41, NULL, 'These signs are like those of the testimony, but their likenesses are drawn from heaven and earth. From the side of religion, the heaven is the likeness of the master of the age — whether he is a Speaker or an Imam — and the earth is the likeness of his اَلْحُجَّة. For water descends from the heaven onto the earth, and from that earth trees and plants sprout, grow, and flourish; and just so, knowledge descends from the Speaker to the Silent One, and from that knowledge the believers sprout and live.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'these signs are like those of the testimony but their likenesses are drawn from heaven and earth from the side of religion the heaven is the likeness of the master of the age whether he is a speaker or an imam and the earth is the likeness of his الحجه for water descends from the heaven onto the earth and from that earth trees and plants sprout grow and flourish and just so knowledge descends from the speaker to the silent one and from that knowledge the believers sprout and live', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 42, NULL, 'The likeness of the believers, in these similes of trees and plants, is that they live by the knowledge that comes to them from the اَلْحُجَّة. And like the Speaker too is the sun: in both heavens, the spiritual and the physical, the sun is the likeness of the Speaker who illuminates the world — for the Speaker illuminates the world with his knowledge. This is why a report has been transmitted from the Messenger of Allah, peace and blessings be upon him, in which he said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the likeness of the believers in these similes of trees and plants is that they live by the knowledge that comes to them from the الحجه and like the speaker too is the sun in both heavens the spiritual and the physical the sun is the likeness of the speaker who illuminates the world for the speaker illuminates the world with his knowledge this is why a report has been transmitted from the messenger of allah peace and blessings be upon him in which he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 43, NULL, 'Sayingتَطْلُعُ مِن مَغْرِبِهَا عَلَىٰ رَأْسِ ٱلثَّلَاثِمِائَةِ"It will rise from its west at the head of the three hundred."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingتطلع من مغربها علي راس الثلاثمايه it will rise from its west at the head of the three hundred', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 44, NULL, 'That was the appearance of the Mahdi. May God bless him with his illuminating light (النُّور). The moon is the likeness of the اَلْحُجَّة, because the moon draws its light from the sun; and just so, the knowledge of the اَلْحُجَّة is derived from the knowledge of the Imam. The likeness of the Speaker in the body is the heart, which is the prince among the bodily limbs; and the اَلْحُجَّة is like the brain, which is the seat of the mind. Each of them is one within the body — and just so, the Speaker is one in the world. Like the Speaker too is the tongue, for through it speech is made. The اَلْحُجَّة is like the two eyes through which sight is made, like the ears through which hearing is made, and like the two hands through which both restraint and action are accomplished.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'that was the appearance of the mahdi may god bless him with his illuminating light النور the moon is the likeness of the الحجه because the moon draws its light from the sun and just so the knowledge of the الحجه is derived from the knowledge of the imam the likeness of the speaker in the body is the heart which is the prince among the bodily limbs and the الحجه is like the brain which is the seat of the mind each of them is one within the body and just so the speaker is one in the world like the speaker too is the tongue for through it speech is made the الحجه is like the two eyes through which sight is made like the ears through which hearing is made and like the two hands through which both restraint and action are accomplished', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 45, NULL, 'From the earth, the likeness is the west and the east. The east is like the Speaker, for from it the light comes. The west is like the اَلْحُجَّة that receives that light and is the place where it comes to rest. The seven heavens are like the seven Speakers, and the seven earths are like the seven الْحُجَج. So too the seven planetary stars — the اَلْمُدَبِّرَات — which Allah Almighty mentioned in His Book when He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'from the earth the likeness is the west and the east the east is like the speaker for from it the light comes the west is like the الحجه that receives that light and is the place where it comes to rest the seven heavens are like the seven speakers and the seven earths are like the seven الحجج so too the seven planetary stars the المدبرات which allah almighty mentioned in his book when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 46, NULL, 'فَٱلْمُدَبِّرَٰتِ أَمْرًا"And those who arrange the affair."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'فالمدبرت امرا and those who arrange the affair', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 47, NULL, 'These are likenesses of the same arrangement. So too the seven climes of the earth. And so too the human being himself, who was created out of seven things. The Almighty has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'these are likenesses of the same arrangement so too the seven climes of the earth and so too the human being himself who was created out of seven things the almighty has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 48, NULL, 'Sayingوَلَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ مِن سُلَـٰلَةٍ مِّن طِينٍ ۝ ثُمَّ جَعَلْنَـٰهُ نُطْفَةً فِى قَرَارٍ مَّكِينٍ ۝ ثُمَّ خَلَقْنَا ٱلنُّطْفَةَ عَلَقَةً فَخَلَقْنَا ٱلْعَلَقَةَ مُضْغَةً فَخَلَقْنَا ٱلْمُضْغَةَ عِظَـٰمًا فَكَسَوْنَا ٱلْعِظَـٰمَ لَحْمًا ثُمَّ أَنشَأْنَـٰهُ خَلْقًا ءَاخَرَ ۚ فَتَبَارَكَ ٱللَّهُ أَحْسَنُ ٱلْخَـٰلِقِينَ"And certainly We created the human being from an extract of clay; then We placed him as a sperm-drop in a firm lodging; then We made the sperm-drop into a clinging clot; then We made the clot into a lump of flesh; then We made out of the lump bones; then We clothed the bones with flesh; then We brought him forth as another creation. So blessed is Allah, the best of creators."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingولقد خلقنا الانسن من سلله من طين ثم جعلنه نطفه في قرار مكين ثم خلقنا النطفه علقه فخلقنا العلقه مضغه فخلقنا المضغه عظما فكسونا العظم لحما ثم انشانه خلقا ءاخر فتبارك الله احسن الخلقين and certainly we created the human being from an extract of clay then we placed him as a sperm drop in a firm lodging then we made the sperm drop into a clinging clot then we made the clot into a lump of flesh then we made out of the lump bones then we clothed the bones with flesh then we brought him forth as another creation so blessed is allah the best of creators', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 49, NULL, 'The parts of the human being are seven: hair, skin, flesh, blood, bones, veins, and brain. His height is seven cubits and his breadth is seven also — that is, the span between the tips of his two hands when he extends them. He prostrates upon seven parts: the face, the two hands, the two knees, and the two feet. In his forehead are seven openings: the two eyes, the two ears, the two nostrils, and the mouth. These are some of the witnesses to the signs of Allah, His limits, and their likenesses and inner meanings in the greater and the smaller worlds. Many further proofs of this same kind have been given at length, and I have set them down in Dhikr al-Muqaddimat, my Mention of the Preparations. There is more there beyond what is here, even though that work too I have abridged.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the parts of the human being are seven hair skin flesh blood bones veins and brain his height is seven cubits and his breadth is seven also that is the span between the tips of his two hands when he extends them he prostrates upon seven parts the face the two hands the two knees and the two feet in his forehead are seven openings the two eyes the two ears the two nostrils and the mouth these are some of the witnesses to the signs of allah his limits and their likenesses and inner meanings in the greater and the smaller worlds many further proofs of this same kind have been given at length and i have set them down in dhikr al muqaddimat my mention of the preparations there is more there beyond what is here even though that work too i have abridged', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 50, NULL, 'These are the limits that Allah Almighty has commanded be safeguarded, and by which the believers are marked with faith — for they enacted them and preserved them, and by that He made Paradise obligatory for them. He has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'these are the limits that allah almighty has commanded be safeguarded and by which the believers are marked with faith for they enacted them and preserved them and by that he made paradise obligatory for them he has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 51, NULL, 'Sayingإِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ ۚ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ ۖ وَعْدًا عَلَيْهِ حَقًّا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ ۚ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ ۚ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ"Indeed, Allah has purchased from the believers their souls and their wealth, in exchange for Paradise being theirs. They fight in the way of Allah, so they slay and are slain — a true promise upon Him in the Torah, the Gospel, and the Quran. And who is more faithful to his covenant than Allah? So rejoice in your transaction which you have contracted, and that is indeed the great success."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingان الله اشتري من المومنين انفسهم وامولهم بان لهم الجنه يقتلون في سبيل الله فيقتلون ويقتلون وعدا عليه حقا في التوراه والانجيل والقرءان ومن اوفي بعهده من الله فاستبشروا ببيعكم الذي بايعتم به وذلك هو الفوز العظيم indeed allah has purchased from the believers their souls and their wealth in exchange for paradise being theirs they fight in the way of allah so they slay and are slain a true promise upon him in the torah the gospel and the quran and who is more faithful to his covenant than allah so rejoice in your transaction which you have contracted and that is indeed the great success', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 52, NULL, 'Then He described, by their attributes, the believers to whom this was enjoined:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'then he described by their attributes the believers to whom this was enjoined', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 53, NULL, 'ٱلتَّـٰٓئِبُونَ ٱلْعَـٰبِدُونَ ٱلْحَـٰمِدُونَ ٱلسَّـٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّـٰجِدُونَ ٱلْـَٔامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَـٰفِظُونَ لِحُدُودِ ٱللَّهِ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ"Those who repent, who worship, who praise, who fast — or who travel — who bow down, who prostrate themselves, who enjoin the good and forbid the wrong, and who keep the limits of Allah — and give glad tidings to the believers."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'التيبون العبدون الحمدون السيحون الركعون السجدون الامرون بالمعروف والناهون عن المنكر والحفظون لحدود الله وبشر المومنين those who repent who worship who praise who fast or who travel who bow down who prostrate themselves who enjoin the good and forbid the wrong and who keep the limits of allah and give glad tidings to the believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 54, NULL, 'These are some of the signs of the seven I have mentioned. As for the twelve successors: they are اَسْبَاب — instruments, causes — for every Speaker in every age. Four of them stand above, closest to the Speaker, and each of those four has two beneath him, one on the right and one on the left, making twelve in all. The four are like the bird of Abraham in his story, of whom the Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'these are some of the signs of the seven i have mentioned as for the twelve successors they are اسباب instruments causes for every speaker in every age four of them stand above closest to the speaker and each of those four has two beneath him one on the right and one on the left making twelve in all the four are like the bird of abraham in his story of whom the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 55, NULL, 'قَالَ فَخُذْ أَرْبَعَةً مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ"He said: Then take four birds and incline them toward yourself."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'قال فخذ اربعه من الطير فصرهن اليك he said then take four birds and incline them toward yourself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 56, NULL, 'They are among the twelve حُدُود, and they are like the four sacred months — these four are, in our knowledge, the consultative council of every Imam, the الْحَرَم of his ministry, four in number, one of whom holds the presidency and is called "the الْبَاب"; they are also called الْاَبْدَال, "those who have changed," because they were re-created after their first creation, refined after refinement, as the Ikhwan al-Safa have said. The Almighty''s own word holds them out for the eye:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'they are among the twelve حدود and they are like the four sacred months these four are in our knowledge the consultative council of every imam the الحرم of his ministry four in number one of whom holds the presidency and is called the الباب they are also called الابدال those who have changed because they were re created after their first creation refined after refinement as the ikhwan al safa have said the almightys own word holds them out for the eye', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 57, NULL, 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًا فِى كِتَـٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ ۚ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ"The number of months with Allah is twelve months in the Book of Allah from the day He created the heavens and the earth, of which four are sacred. So do not wrong yourselves with them."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'ان عده الشهور عند الله اثنا عشر شهرا في كتب الله يوم خلق السموت والارض منها اربعه حرم ذلك الدين القيم فلا تظلموا فيهن انفسكم the number of months with allah is twelve months in the book of allah from the day he created the heavens and the earth of which four are sacred so do not wrong yourselves with them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 58, NULL, 'Their likeness is found also in the testimony, whose letters number twelve. Twelve letters that, taken together, form la ilaha illa Allah — and those twelve letters correspond to the names of the twelve jazair that make up the globe, and to the names of the twelve missionaries called the "missionaries of the jazair," who are charged with the propagation and organization of the mission. Their likeness is in the twelve constellations of the heavens; their likeness is in the twelve jazair of the earth, each of them an island; and their likeness is in the twelve spiritual ones, the angels and the messengers, who are the first wings, for it is through them that the command in the message of the Companion is directed. Their wings are the preachers, for each of them is sent to one of the jazair, where there is a حَدّ corresponding to him. As the Almighty has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'their likeness is found also in the testimony whose letters number twelve twelve letters that taken together form la ilaha illa allah and those twelve letters correspond to the names of the twelve jazair that make up the globe and to the names of the twelve missionaries called the missionaries of the jazair who are charged with the propagation and organization of the mission their likeness is in the twelve constellations of the heavens their likeness is in the twelve jazair of the earth each of them an island and their likeness is in the twelve spiritual ones the angels and the messengers who are the first wings for it is through them that the command in the message of the companion is directed their wings are the preachers for each of them is sent to one of the jazair where there is a حد corresponding to him as the almighty has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 59, NULL, 'Sayingٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَـٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍ مَّثْنَىٰ وَثُلَـٰثَ وَرُبَـٰعَ ۚ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ ۝ مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلَا مُمْسِكَ لَهَا ۖ وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ"Praise be to Allah, who made the angels messengers having wings — two, three, and four. He increases in creation what He wills. Indeed, Allah is able to do all things. Whatever mercy Allah opens to mankind, none can withhold; and whatever He withholds, none can release after Him. He is the Mighty, the Wise."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingالحمد لله فاطر السموت والارض جاعل المليكه رسلا اولي اجنحه مثني وثلث وربع يزيد في الخلق ما يشاء ان الله علي كل شيء قدير ما يفتح الله للناس من رحمه فلا ممسك لها وما يمسك فلا مرسل له من بعده وهو العزيز الحكيم praise be to allah who made the angels messengers having wings two three and four he increases in creation what he wills indeed allah is able to do all things whatever mercy allah opens to mankind none can withhold and whatever he withholds none can release after him he is the mighty the wise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 60, NULL, 'Understand, then, that the twelve حُدُود in the lower world correspond to the angels in the upper world. The Almighty has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'understand then that the twelve حدود in the lower world correspond to the angels in the upper world the almighty has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 61, NULL, 'وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ"And of all things We created pairs."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'ومن كل شيء خلقنا زوجين and of all things we created pairs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 62, NULL, 'The seven and the twelve, taken together, total nineteen. These are the ones to whom Allah has entrusted His affair. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the seven and the twelve taken together total nineteen these are the ones to whom allah has entrusted his affair the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 63, NULL, 'عَلَيْهَا تِسْعَةَ عَشَرَ"Over it are nineteen."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'عليها تسعه عشر over it are nineteen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 64, NULL, 'The testimony has gathered them all together. Whoever knows them, believes in their الْوِلَايَة, and acts upon what he has taken from them, is a believer among the people of Paradise, accepted in his testimony. Whoever is unable to do any of that, or who falls short of it, but bears witness with his tongue alone, is a Muslim whose testimony is not accepted, and his judgment rests with Allah. For this reason it is mentioned in the book Daaim al-Islam, from the saying of al-Sadiq, may the blessings of Allah be upon him:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'the testimony has gathered them all together whoever knows them believes in their الولايه and acts upon what he has taken from them is a believer among the people of paradise accepted in his testimony whoever is unable to do any of that or who falls short of it but bears witness with his tongue alone is a muslim whose testimony is not accepted and his judgment rests with allah for this reason it is mentioned in the book daaim al islam from the saying of al sadiq may the blessings of allah be upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 65, NULL, 'Sayingٱلْإِيمَانُ يُشَارِكُ ٱلْإِسْلَامَ وَلَا يُشَارِكُهُ ٱلْإِسْلَامُ، وَقَدْ يَكُونُ ٱلرَّجُلُ مُسْلِمًا وَلَا يَكُونُ مُؤْمِنًا، وَلَا يَكُونُ مُؤْمِنًا حَتَّى يَكُونَ مُسْلِمًا"Faith encompasses Islam, but Islam does not encompass faith. A man may be a Muslim without being a believer, but he is not a believer until he is also a Muslim."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingالايمان يشارك الاسلام ولا يشاركه الاسلام وقد يكون الرجل مسلما ولا يكون مومنا ولا يكون مومنا حتي يكون مسلما faith encompasses islam but islam does not encompass faith a man may be a muslim without being a believer but he is not a believer until he is also a muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 66, NULL, 'This is the testimony whose حُدُود I have laid out for you with respect to the foundations — the اَلْاُصُول. Connected to it is the second testimony, which pertains to the branches — the اَلْفُرُوع: مُحَمَّدٌ رَسُولُ اللَّهِ, "Muhammad is the Messenger of Allah," peace be upon him. It is three words, representing the three subordinate spiritual حُدُود — the upper spiritual ones — namely Israfil, Mikail, and Jibrail. They correspond to three earthly corporeal حُدُود, which stand in extension of the Speaker and the Foundation: the Imam, the اَلْحُجَّة, and the أَلْحَق, the one who follows. Together these six divisions correspond to the six pronunciations of the first determination that I have already mentioned. Together they make twelve letters, like the twelve الْحُجَج already named. So the testimony to Allah Almighty is the highest degree — the اَلْاُصُول; and the testimony to the Messenger, peace be upon him, is the lowest degree — the اَلْفُرُوع. The upper and the lower حُدُود are contained within the letters of the testimony together.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'this is the testimony whose حدود i have laid out for you with respect to the foundations the الاصول connected to it is the second testimony which pertains to the branches the الفروع محمد رسول الله muhammad is the messenger of allah peace be upon him it is three words representing the three subordinate spiritual حدود the upper spiritual ones namely israfil mikail and jibrail they correspond to three earthly corporeal حدود which stand in extension of the speaker and the foundation the imam the الحجه and the الحق the one who follows together these six divisions correspond to the six pronunciations of the first determination that i have already mentioned together they make twelve letters like the twelve الحجج already named so the testimony to allah almighty is the highest degree the الاصول and the testimony to the messenger peace be upon him is the lowest degree the الفروع the upper and the lower حدود are contained within the letters of the testimony together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 67, NULL, 'So the outward of the testimony is a statement with the tongue. Its inner meaning is statement together with knowledge. And its substance is action. Its outward form is Islam, and at its core is faith. On this al-Sadiq, may the blessings of Allah be upon him, said — as I have set down in Daaim al-Islam, when he was asked whether faith is speech or action:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'so the outward of the testimony is a statement with the tongue its inner meaning is statement together with knowledge and its substance is action its outward form is islam and at its core is faith on this al sadiq may the blessings of allah be upon him said as i have set down in daaim al islam when he was asked whether faith is speech or action', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 68, NULL, 'Sayingٱلْإِيمَانُ كُلُّهُ عَمَلٌ، وَٱلْقَوْلُ بَعْضُ ذَٰلِكَ ٱلْعَمَلِ"Faith is all action, and speech is only a part of it."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'sayingالايمان كله عمل والقول بعض ذلك العمل faith is all action and speech is only a part of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 69, NULL, 'So preserve, O believers, the testimony to which you have been called. Be sincere in it. I have shown you the sincerity due to it — the sincerity for which Allah Almighty has appointed reward in His saying:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'so preserve o believers the testimony to which you have been called be sincere in it i have shown you the sincerity due to it the sincerity for which allah almighty has appointed reward in his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 70, NULL, 'وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟"And the witnesses do not refuse when they are called."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'ولا ياب الشهداء اذا ما دعوا and the witnesses do not refuse when they are called', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 71, NULL, 'Whatever you have been called to, be faithful to it in word and in deed. Fulfill His promise to you, as He has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'whatever you have been called to be faithful to it in word and in deed fulfill his promise to you as he has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 72, NULL, 'وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ"And fulfill My covenant and I will fulfill your covenant."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'واوفوا بعهدي اوف بعهدكم and fulfill my covenant and i will fulfill your covenant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 73, NULL, 'Allah has promised you, on the tongue of His Messenger, Paradise if you are sincere in your testimony. Know this. Then believe and do not doubt. Act, and do not stray. Do not grow complacent, do not grow discouraged. You will then receive what Allah has promised you of Paradise, outward and inward, as He has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'allah has promised you on the tongue of his messenger paradise if you are sincere in your testimony know this then believe and do not doubt act and do not stray do not grow complacent do not grow discouraged you will then receive what allah has promised you of paradise outward and inward as he has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 74, NULL, 'وَلِمَنْ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ"And for him who fears the standing before his Lord, there are two gardens."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'ولمن خاف مقام ربه جنتان and for him who fears the standing before his lord there are two gardens', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 75, NULL, 'It is wise to know that you will not leave its gardens, and you will receive with them their fruits and their spouses. You will enter the Garden of Eternity in the abode of permanence in the hereafter, and you will gain therein the reward of Allah, which He promised you. And you will be safe from His punishment, with which He warned you should you disobey what He has commanded and commit what He has forbidden — should you neglect what He has enjoined upon you and to which He has called you to be sincere, by the testimony in which He gathered together all that with which you worship Him.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'it is wise to know that you will not leave its gardens and you will receive with them their fruits and their spouses you will enter the garden of eternity in the abode of permanence in the hereafter and you will gain therein the reward of allah which he promised you and you will be safe from his punishment with which he warned you should you disobey what he has commanded and commit what he has forbidden should you neglect what he has enjoined upon you and to which he has called you to be sincere by the testimony in which he gathered together all that with which you worship him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 76, NULL, 'What I have placed in this chapter — the chapter on faith — should suffice as an explanation of the testimony and what it indicates of the حُدُود. I shall mention them all again, each in its likeness, in the chapters of this book that follow. When I come to the obligatory prayers, you will see that this same testimony has descended upon them, and that it has encompassed the totality of that with which you worship Allah. That is why the call of the Prophet, peace be upon him, was directed to it, and why he took upon you the covenant that you would testify with sincerity after him. You have borne witness to it with your tongue; you bear witness to it in your hearts as a testimony of belief; and you act upon it as a ruling next to a deed.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'what i have placed in this chapter the chapter on faith should suffice as an explanation of the testimony and what it indicates of the حدود i shall mention them all again each in its likeness in the chapters of this book that follow when i come to the obligatory prayers you will see that this same testimony has descended upon them and that it has encompassed the totality of that with which you worship allah that is why the call of the prophet peace be upon him was directed to it and why he took upon you the covenant that you would testify with sincerity after him you have borne witness to it with your tongue you bear witness to it in your hearts as a testimony of belief and you act upon it as a ruling next to a deed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'the four limits of the testimony', '2. The Four Limits of the Testimony', 77, NULL, 'Take notice, then, that you have been appointed to be encompassed by the حُدُود set out for you, and by the proofs shown to you, upon the right path by which you have been saved. May Allah aid you in that, and guide you to it. May the blessings of Allah be upon the Prophet Muhammad, and upon the righteous of his descendants who succeed one another until the Day of Judgment. And praise be to Allah, Lord of the Worlds.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 2 the four limits of the testimony', 'take notice then that you have been appointed to be encompassed by the حدود set out for you and by the proofs shown to you upon the right path by which you have been saved may allah aid you in that and guide you to it may the blessings of allah be upon the prophet muhammad and upon the righteous of his descendants who succeed one another until the day of judgment and praise be to allah lord of the worlds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 0, NULL, 'I have already opened, in the book whose pillars I undertook to simplify, the chapters on faith and Islam, and I named there what faith and Islam mean. Now I want to open a different door — the door of الْوِلَايَة, the door of authority and friendship with God — and to recite it for the Messengers and for the first of those whom God placed in command after them, those whose obedience He bound to His own obedience. He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'i have already opened in the book whose pillars i undertook to simplify the chapters on faith and islam and i named there what faith and islam mean now i want to open a different door the door of الولايه the door of authority and friendship with god and to recite it for the messengers and for the first of those whom god placed in command after them those whose obedience he bound to his own obedience he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 1, NULL, 'أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنكُمْ"Obey God, and obey the Messenger, and those in authority among you."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'اطيعوا الله واطيعوا الرسول واولي الامر منكم obey god and obey the messenger and those in authority among you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 2, NULL, 'He gathered them in this one duty — to be obeyed — and though their ranks rise and fall by degrees, the order issuing from their station is, in the matter of knowledge (الْعِلْم), a single thing. The pronouncement is one.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'he gathered them in this one duty to be obeyed and though their ranks rise and fall by degrees the order issuing from their station is in the matter of knowledge العلم a single thing the pronouncement is one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 3, NULL, 'They are seven: Adam, Noah, Abraham, Moses, Jesus, Muhammad, and the seventh of them, the الْقَائِم of the Age — the One Who Stands at the End. After each of these, in his lifetime, comes the Asas, the Foundation, whom God established to carry the inner (نَار) meaning of the message. The Asas rises after the اَلنَّاطِق and inherits his place when he passes, becoming an Imam, and appoints for himself a اَلْحُجَّة, a Proof, who will stand where he stood. So the cycle keeps turning, اَلْحُجَّة into Imam into اَلْحُجَّة, until that Natiqs age is finished, and then another اَلنَّاطِق arises with a new sharia and the cycle begins again. The reason is simple, and severe: the earth is never empty of a وَلِيّ of God, of His Proof standing upon it — not even for the time it takes an eye to close and open. Al-Sadiq (peace be upon him) was once asked, when the question came up of "the second" in a certain saying, what that second was. He answered, "In another minute that remains from the same past" — so that both might be fully credited, the one who has gone and the one who remains. There is always one after one. There is never two at once. The unity of the Almighty is mirrored in the unity of His Proof.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'they are seven adam noah abraham moses jesus muhammad and the seventh of them the القايم of the age the one who stands at the end after each of these in his lifetime comes the asas the foundation whom god established to carry the inner نار meaning of the message the asas rises after the الناطق and inherits his place when he passes becoming an imam and appoints for himself a الحجه a proof who will stand where he stood so the cycle keeps turning الحجه into imam into الحجه until that natiqs age is finished and then another الناطق arises with a new sharia and the cycle begins again the reason is simple and severe the earth is never empty of a ولي of god of his proof standing upon it not even for the time it takes an eye to close and open al sadiq peace be upon him was once asked when the question came up of the second in a certain saying what that second was he answered in another minute that remains from the same past so that both might be fully credited the one who has gone and the one who remains there is always one after one there is never two at once the unity of the almighty is mirrored in the unity of his proof', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 4, NULL, 'He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 5, NULL, 'لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا"Were there in them gods other than God, both [the heavens and the earth] would have been corrupted."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'لو كان فيهما الهه الا الله لفسدتا were there in them gods other than god both the heavens and the earth would have been corrupted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 6, NULL, 'The companion of the age — whether prophet, messenger, or imam — is called the اَلنَّاطِق, the Speaking One, because he is the one who pronounces what is outward and carries it into act. His اَلْحُجَّة is called the اَلصَّامِت, the Silent One, because he holds his peace concerning the outward. This is why God has named twelve pure ones in His Book, when He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the companion of the age whether prophet messenger or imam is called the الناطق the speaking one because he is the one who pronounces what is outward and carries it into act his الحجه is called the الصامت the silent one because he holds his peace concerning the outward this is why god has named twelve pure ones in his book when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 7, NULL, 'وَبَعَثْنَا مِنْهُمُ اثْنَيْ عَشَرَ نَقِيبًا"And We sent forth from among them twelve chiefs."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'وبعثنا منهم اثني عشر نقيبا and we sent forth from among them twelve chiefs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 8, NULL, 'We have already recounted their testimonies and the testimonies of the other scholars of the greater world, and the lesser scholars who stand to them as smaller mirrors stand to larger ones. Beyond what we have said, let me say this: the Imam and the اَلْحُجَّة succeed one another as day succeeds night, and what is like them follows the same pattern. The day is like the Imam — the outer made manifest — and the night is like the اَلْحُجَّة, the silence and concealment of the inner. Of these two God Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'we have already recounted their testimonies and the testimonies of the other scholars of the greater world and the lesser scholars who stand to them as smaller mirrors stand to larger ones beyond what we have said let me say this the imam and the الحجه succeed one another as day succeeds night and what is like them follows the same pattern the day is like the imam the outer made manifest and the night is like the الحجه the silence and concealment of the inner of these two god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 9, NULL, 'Sayingوَجَعَلْنَا اللَّيْلَ وَالنَّهَارَ آيَتَيْنِ"And We made the night and the day two signs."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'sayingوجعلنا الليل والنهار ايتين and we made the night and the day two signs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 10, NULL, 'The signs (آيَات) of God in the inner meaning are His proofs set against His creation. They are the inner ones whose obedience is made binding — the obedience that is bound to His own.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the signs ايات of god in the inner meaning are his proofs set against his creation they are the inner ones whose obedience is made binding the obedience that is bound to his own', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 11, NULL, 'The name of the Imam falls upon the اَلنَّاطِق, and the name of the اَلنَّاطِق falls upon the Imam. God said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the name of the imam falls upon the الناطق and the name of the الناطق falls upon the imam god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 12, NULL, 'Sayingوَإِذِ ابْتَلَىٰ إِبْرَاهِيمَ رَبُّهُ بِكَلِمَاتٍ فَأَتَمَّهُنَّ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا ۖ قَالَ وَمِن ذُرِّيَّتِي ۖ قَالَ لَا يَنَالُ عَهْدِي الظَّالِمِينَ"And when his Lord tested Abraham with certain words and he fulfilled them, He said, I will make you an Imam for the people. He said, And from my descendants? He said, My covenant does not reach the wrongdoers."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'sayingواذ ابتلي ابراهيم ربه بكلمات فاتمهن قال اني جاعلك للناس اماما قال ومن ذريتي قال لا ينال عهدي الظالمين and when his lord tested abraham with certain words and he fulfilled them he said i will make you an imam for the people he said and from my descendants he said my covenant does not reach the wrongdoers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 13, NULL, 'The Imam is called اَلنَّاطِق because he speaks what the prophet of his turn used to speak — the outward sharia with which that prophet was sent. He is called Imam because the servants follow his example, and the imam in prayer is so named because he stands in front of those who pray behind him; the congregation imitates him because he is at their head. He is also called al-rais, the leader, because he goes before them, in front of their hands, while they trail behind. But there is also an imam of misguidance — an imam who must not be followed, an imam who pulls his people downward. God said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the imam is called الناطق because he speaks what the prophet of his turn used to speak the outward sharia with which that prophet was sent he is called imam because the servants follow his example and the imam in prayer is so named because he stands in front of those who pray behind him the congregation imitates him because he is at their head he is also called al rais the leader because he goes before them in front of their hands while they trail behind but there is also an imam of misguidance an imam who must not be followed an imam who pulls his people downward god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 14, NULL, 'وَجَعَلْنَاهُمْ أَئِمَّةً يَدْعُونَ إِلَى النَّارِ"And We made them leaders inviting to the Fire."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'وجعلناهم ايمه يدعون الي النار and we made them leaders inviting to the fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 15, NULL, 'The name of prophecy was given only to those connected to the upper substance with no intermediary between, no حَدّ — no limit, no rank — placed below them and the source. The Imamate (الْاِمَامَة) is one حَدّ below prophecy, one degree under it; yet the obedience owed to the Imam is equal in obligation to the obedience owed to the prophet, and it is likewise paired with the obedience owed to God.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the name of prophecy was given only to those connected to the upper substance with no intermediary between no حد no limit no rank placed below them and the source the imamate الامامه is one حد below prophecy one degree under it yet the obedience owed to the imam is equal in obligation to the obedience owed to the prophet and it is likewise paired with the obedience owed to god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 16, NULL, 'Now we must mention the origin of the Imamate in the lower حَدّ, which is Adam (peace be upon him). After that I will arrange what follows and recite it to you piece by piece, as much as a man can bear of this limit of speech that we are saying. And by God we seek help.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'now we must mention the origin of the imamate in the lower حد which is adam peace be upon him after that i will arrange what follows and recite it to you piece by piece as much as a man can bear of this limit of speech that we are saying and by god we seek help', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 17, NULL, 'God says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'god says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 18, NULL, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي جَاعِلٌ فِي الْأَرْضِ خَلِيفَةً ۖ قَالُوا أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ الدِّمَاءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّي أَعْلَمُ مَا لَا تَعْلَمُونَ"And when your Lord said to the angels, I am placing upon the earth a successor, they said, Will You place upon it one who will corrupt it and shed blood, while we glorify You with praise and sanctify You? He said, Indeed, I know what you do not know."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'واذ قال ربك للملايكه اني جاعل في الارض خليفه قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون and when your lord said to the angels i am placing upon the earth a successor they said will you place upon it one who will corrupt it and shed blood while we glorify you with praise and sanctify you he said indeed i know what you do not know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 19, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 20, NULL, 'Sayingإِنِّي خَالِقٌ بَشَرًا مِّن طِينٍ ۖ فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ"I am creating a human being from clay. So when I have shaped him and breathed into him of My spirit, fall down before him in prostration."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'sayingاني خالق بشرا من طين فاذا سويته ونفخت فيه من روحي فقعوا له ساجدين i am creating a human being from clay so when i have shaped him and breathed into him of my spirit fall down before him in prostration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 21, NULL, 'The first thing that has to be said about these words is about the origin of the knowledge of God''s friends. Speech and saying, when they are attributed to God, refer to what happens within those who hear — they do not name what you observe in the speech of those who speak: sounds that arise out of bodies, that pass through cavities, broken into syllables by the playthings of tongues and teeth and lips; nor are they like the voices that come from the friction of created things against one another. God is far above being likened to anything He has made — exalted infinitely above all of it. The language itself permits us to call something "speech" or "saying" without any audible sound or known pronunciation behind it. The Arabs say: "the money is gone," "the wall has fallen," "the man has been struck," "the world has preached to its people and addressed them with its sermons," "time has reproached so-and-so." So God addresses His creation in a way only God knows. A man may see, in his dream, what he has never seen with his open eyes; he hears speech without a speaker, and a voice arrives in him without a throat to issue it. And God Almighty has the power to do what He says without it being done in the manner you suppose — by His sheer ability, He commands what He wills, and there is no partner with Him. He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the first thing that has to be said about these words is about the origin of the knowledge of gods friends speech and saying when they are attributed to god refer to what happens within those who hear they do not name what you observe in the speech of those who speak sounds that arise out of bodies that pass through cavities broken into syllables by the playthings of tongues and teeth and lips nor are they like the voices that come from the friction of created things against one another god is far above being likened to anything he has made exalted infinitely above all of it the language itself permits us to call something speech or saying without any audible sound or known pronunciation behind it the arabs say the money is gone the wall has fallen the man has been struck the world has preached to its people and addressed them with its sermons time has reproached so and so so god addresses his creation in a way only god knows a man may see in his dream what he has never seen with his open eyes he hears speech without a speaker and a voice arrives in him without a throat to issue it and god almighty has the power to do what he says without it being done in the manner you suppose by his sheer ability he commands what he wills and there is no partner with him he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 22, NULL, 'إِنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَن نَّقُولَ لَهُ كُن فَيَكُونُ"Our word to a thing, when We will it, is only that We say to it, Be, and it is."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'انما قولنا لشيء اذا اردناه ان نقول له كن فيكون our word to a thing when we will it is only that we say to it be and it is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 23, NULL, 'He says "Be," and the thing becomes — as creation itself says "be" in being summoned. Speech, in this sense, is something performed; one of these performances is moving, the first kind, and one is still — and so on, beyond what I can name here.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'he says be and the thing becomes as creation itself says be in being summoned speech in this sense is something performed one of these performances is moving the first kind and one is still and so on beyond what i can name here', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 24, NULL, 'There are many parables of this in the mystery of God''s dealings with His angelic guardians, those to whom God spoke what He spoke concerning the affair of Adam — not all the angels, but a particular company among them. When God willed to create Adam (and this was the second creation, the creation of knowledge, after the first creation of clay — as the Almighty said, "Then We brought him forth as another creation," and as He said, "And He will form you in the wombs of your mothers, creation after creation"), and when He willed to appoint Adam as Imam, He set apart from among the angels twelve kings to stand him up as their leader. From him they would receive, and they would carry his report to the people of the earth. When He knew He would create Adam from clay — and clay, in the inner reading, stands for the outward, the dense bodily knowledge — He created those angels in the creation of the gentle and subtle, the spiritual knowledge.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'there are many parables of this in the mystery of gods dealings with his angelic guardians those to whom god spoke what he spoke concerning the affair of adam not all the angels but a particular company among them when god willed to create adam and this was the second creation the creation of knowledge after the first creation of clay as the almighty said then we brought him forth as another creation and as he said and he will form you in the wombs of your mothers creation after creation and when he willed to appoint adam as imam he set apart from among the angels twelve kings to stand him up as their leader from him they would receive and they would carry his report to the people of the earth when he knew he would create adam from clay and clay in the inner reading stands for the outward the dense bodily knowledge he created those angels in the creation of the gentle and subtle the spiritual knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 25, NULL, 'They had already been taught a certain principle: that gentle knowledge does not cling to matter, and that dense knowledge comes only through being taught. They had been taught that gentle spiritual knowledge is not joined to deeds; it is a science without work or assignment, the inverse of apparent knowledge, which is married to action. The Commander of the Believers said it plainly, of the Quran:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'they had already been taught a certain principle that gentle knowledge does not cling to matter and that dense knowledge comes only through being taught they had been taught that gentle spiritual knowledge is not joined to deeds it is a science without work or assignment the inverse of apparent knowledge which is married to action the commander of the believers said it plainly of the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 26, NULL, 'Sayingالظَّاهِرُ عِلْمٌ ظَاهِرٌ وَالْبَاطِنُ عِلْمٌ بَاطِنٌ"The outward is a knowledge that is apparent, and the inward is a knowledge that is hidden."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'sayingالظاهر علم ظاهر والباطن علم باطن the outward is a knowledge that is apparent and the inward is a knowledge that is hidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 27, NULL, 'The angels, then, were not put to the test of deeds. They already carried the knowledge that the one charged with deeds must be brought low and kept short. So they said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the angels then were not put to the test of deeds they already carried the knowledge that the one charged with deeds must be brought low and kept short so they said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 28, NULL, 'أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ الدِّمَاءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ"Will You place upon it one who will corrupt it and shed blood, while we glorify You with praise and sanctify You?"', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك will you place upon it one who will corrupt it and shed blood while we glorify you with praise and sanctify you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 29, NULL, 'قَالَ إِنِّي أَعْلَمُ مَا لَا تَعْلَمُونَHe said, "Indeed, I know what you do not know."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'قال اني اعلم ما لا تعلمونhe said indeed i know what you do not know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 30, NULL, 'What the Almighty meant was that Adam would be granted everything the angels had been granted, and warned against the same dangers, so that he might not fall short, slip, or come to ruin. Iblis was among them. He saw himself as better than Adam; he laid claim to Adam''s rank for himself, refused to be his follower, and swelled with arrogance against the command of his Lord. He wanted God to see in the angels — in himself — an incapacity that would lift him above what was coming. So God created Adam, as He said, from clay: He began with the apparent knowledge, the الظَّاهِر, in keeping with the unalterable custom He set for His servants — begin with the outward, end with the inward. Adam remained in this state a long time, knowing nothing other than what he had been taught — only the outward, only the الظَّاهِر.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'what the almighty meant was that adam would be granted everything the angels had been granted and warned against the same dangers so that he might not fall short slip or come to ruin iblis was among them he saw himself as better than adam he laid claim to adams rank for himself refused to be his follower and swelled with arrogance against the command of his lord he wanted god to see in the angels in himself an incapacity that would lift him above what was coming so god created adam as he said from clay he began with the apparent knowledge the الظاهر in keeping with the unalterable custom he set for his servants begin with the outward end with the inward adam remained in this state a long time knowing nothing other than what he had been taught only the outward only the الظاهر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 31, NULL, 'This is what the hadith refers to when it says that, when God formed Adam''s image from clay, he lay a lifeless body for a long stretch before the spirit was breathed into him — meaning, before he received the inner, spiritual knowledge, the الْبَاطِن. In that interval, Iblis would come to him and speak to him of knowledge Adam did not have. He probed him, found only the apparent knowledge in him — knowledge Adam took delight in, because it was all he had — and Iblis reported back to the angels that Adam was hollow: empty of any inner content. This was before the angels, and Iblis among them, had been ordered to obey him. The Almighty had said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'this is what the hadith refers to when it says that when god formed adams image from clay he lay a lifeless body for a long stretch before the spirit was breathed into him meaning before he received the inner spiritual knowledge the الباطن in that interval iblis would come to him and speak to him of knowledge adam did not have he probed him found only the apparent knowledge in him knowledge adam took delight in because it was all he had and iblis reported back to the angels that adam was hollow empty of any inner content this was before the angels and iblis among them had been ordered to obey him the almighty had said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 32, NULL, 'فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ"When I have shaped him and breathed into him of My spirit, fall down before him in prostration."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'فاذا سويته ونفخت فيه من روحي فقعوا له ساجدين when i have shaped him and breathed into him of my spirit fall down before him in prostration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 33, NULL, 'That is, submit to him in obedience once I have given him the spiritual knowledge. At that moment, the devil among them turned against him — out of the old enmity he had been nursing, the envy that had taken hold of him, the arrogance he felt over Adam. He had seen himself as better; he had taken pleasure in observing Adam''s lag in inner knowledge — and now the news arrived that Adam was no longer behind, and Iblis was filled with regret on the one hand and stubborn pride on the other.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'that is submit to him in obedience once i have given him the spiritual knowledge at that moment the devil among them turned against him out of the old enmity he had been nursing the envy that had taken hold of him the arrogance he felt over adam he had seen himself as better he had taken pleasure in observing adams lag in inner knowledge and now the news arrived that adam was no longer behind and iblis was filled with regret on the one hand and stubborn pride on the other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 34, NULL, 'When God willed to bring Iblis low, He extended Adam''s reach. He taught him the inner knowledge. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'when god willed to bring iblis low he extended adams reach he taught him the inner knowledge the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 35, NULL, 'وَعَلَّمَ آدَمَ الْأَسْمَاءَ كُلَّهَا"And He taught Adam the names — all of them."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'وعلم ادم الاسماء كلها and he taught adam the names all of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 36, NULL, 'The names of every thing human beings need to know, because every thing has a name. He taught him this; then He summoned the angels, those whom He had permitted to call upon Adam, and He began questioning them about what Adam had been taught. They had nothing to answer. They said exactly what God reported of them:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the names of every thing human beings need to know because every thing has a name he taught him this then he summoned the angels those whom he had permitted to call upon adam and he began questioning them about what adam had been taught they had nothing to answer they said exactly what god reported of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 37, NULL, 'سُبْحَانَكَ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا ۖ إِنَّكَ أَنتَ الْعَلِيمُ الْحَكِيمُ"Glory be to You! We have no knowledge except what You have taught us. Indeed, You are the All-Knowing, the All-Wise."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'سبحانك لا علم لنا الا ما علمتنا انك انت العليم الحكيم glory be to you we have no knowledge except what you have taught us indeed you are the all knowing the all wise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 38, NULL, 'He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 39, NULL, 'Sayingيَا آدَمُ أَنبِئْهُم بِأَسْمَائِهِمْ"O Adam, inform them of their names."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'sayingيا ادم انبيهم باسمايهم o adam inform them of their names', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 40, NULL, 'And when Adam had informed them of their names, He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'and when adam had informed them of their names he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 41, NULL, 'أَلَمْ أَقُل لَّكُمْ إِنِّي أَعْلَمُ غَيْبَ السَّمَاوَاتِ وَالْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ"Did I not tell you that I know the unseen of the heavens and the earth, and I know what you reveal and what you have been concealing?"', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'الم اقل لكم اني اعلم غيب السماوات والارض واعلم ما تبدون وما كنتم تكتمون did i not tell you that i know the unseen of the heavens and the earth and i know what you reveal and what you have been concealing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 42, NULL, 'Al-Sadiq (peace be upon him) said: "One day I argued with my father, and he set out to walk around the House. I walked with him one night, and then he leaned toward the stone and stood praying there until I had finished and sat down — while he was still standing in prayer. A man came and sat beside him, and he too was praying. I looked at him: a man of perfect build, large-boned, dark in color and in hair, two thick white garments on him. When my father saw him sitting beside him, he cut his prayer short, turned and greeted him, and said, Do you have any need? He said, I have come to ask you about the beginning of the creation of this House. My father said, Yes. When God created Adam — and he went on and recounted the whole story, and the command given to the angels, and what they said to Him, and what He said to them:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'al sadiq peace be upon him said one day i argued with my father and he set out to walk around the house i walked with him one night and then he leaned toward the stone and stood praying there until i had finished and sat down while he was still standing in prayer a man came and sat beside him and he too was praying i looked at him a man of perfect build large boned dark in color and in hair two thick white garments on him when my father saw him sitting beside him he cut his prayer short turned and greeted him and said do you have any need he said i have come to ask you about the beginning of the creation of this house my father said yes when god created adam and he went on and recounted the whole story and the command given to the angels and what they said to him and what he said to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 43, NULL, 'وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَAnd I know what you reveal and what you have been concealing.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'واعلم ما تبدون وما كنتم تكتمونand i know what you reveal and what you have been concealing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 44, NULL, '"The man asked, But what did they reveal, and what did they conceal? My father said: What they revealed was what they said —', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the man asked but what did they reveal and what did they conceal my father said what they revealed was what they said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 45, NULL, 'أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ الدِّمَاءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ"Will You place upon it one who will corrupt it and shed blood, while we glorify You with praise and sanctify You?"', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك will you place upon it one who will corrupt it and shed blood while we glorify you with praise and sanctify you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 46, NULL, '— and what they concealed was what they said within themselves: we did not think that God would create any creation more honorable in His sight than we are. Then He commanded them to prostrate to Adam, and when He said it, they understood that they had fallen into disobedience. They took refuge at the Throne, and they circled it for a week, seeking their Lord''s pleasure. He said to them: Descend to the earth and build a House at which to seek refuge — to which the sinner from the children of Adam may come, and they will circumambulate it as you have circled the Throne, and I will be pleased with them as I was pleased with you. So they built this House. Then God raised it up at the time of the flood, so that even now, from the fourth heaven, the angels make pilgrimage to it until the Day of Resurrection. Ibrahim al-Khalil (الْخَلِيل) rebuilt the House upon its old foundations." The hadith goes on at length; I have taken from it only what is needed.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'and what they concealed was what they said within themselves we did not think that god would create any creation more honorable in his sight than we are then he commanded them to prostrate to adam and when he said it they understood that they had fallen into disobedience they took refuge at the throne and they circled it for a week seeking their lords pleasure he said to them descend to the earth and build a house at which to seek refuge to which the sinner from the children of adam may come and they will circumambulate it as you have circled the throne and i will be pleased with them as i was pleased with you so they built this house then god raised it up at the time of the flood so that even now from the fourth heaven the angels make pilgrimage to it until the day of resurrection ibrahim al khalil الخليل rebuilt the house upon its old foundations the hadith goes on at length i have taken from it only what is needed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 47, NULL, 'Then God Almighty commanded the angels to prostrate to Adam — that is, He commanded them to obey him, to call upon him, and to accept him — as the Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'then god almighty commanded the angels to prostrate to adam that is he commanded them to obey him to call upon him and to accept him as the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 48, NULL, 'أَلَمْ تَرَ أَنَّ اللَّهَ يَسْجُدُ لَهُ مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ وَالشَّمْسُ وَالْقَمَرُ وَالنُّجُومُ وَالْجِبَالُ وَالشَّجَرُ وَالدَّوَابُّ وَكَثِيرٌ مِّنَ النَّاسِ ۖ وَكَثِيرٌ حَقَّ عَلَيْهِ الْعَذَابُ"Do you not see that to God prostrates whoever is in the heavens and whoever is on the earth — and the sun, the moon, the stars, the mountains, the trees, the animals, and many of mankind — and many are deserving of punishment?"', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'الم تر ان الله يسجد له من في السماوات ومن في الارض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس وكثير حق عليه العذاب do you not see that to god prostrates whoever is in the heavens and whoever is on the earth and the sun the moon the stars the mountains the trees the animals and many of mankind and many are deserving of punishment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 49, NULL, 'So they prostrated, as God said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'so they prostrated as god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 50, NULL, 'إِلَّا إِبْلِيسَ اسْتَكْبَرَ وَكَانَ مِنَ الْكَافِرِينَ"Except Iblis: he was arrogant and became one of the disbelievers."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'الا ابليس استكبر وكان من الكافرين except iblis he was arrogant and became one of the disbelievers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 51, NULL, 'It was only after this that he was called Shaytan. The masters of the language hold that shaytan (اَلشَّيْطَان) follows the pattern of words meaning ruined or perished: it is said shata fulan when a man perishes, and so Iblis was called Shaytan once he was destroyed by the limit at which he became Shaytan. It is also said that shaytan names the man who is cut off and has no proof; and it is said ibn abi sad and iblis of the one dejected and brought low. All these conditions were gathered in him. God spoke — and He is the most truthful of those who speak:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'it was only after this that he was called shaytan the masters of the language hold that shaytan الشيطان follows the pattern of words meaning ruined or perished it is said shata fulan when a man perishes and so iblis was called shaytan once he was destroyed by the limit at which he became shaytan it is also said that shaytan names the man who is cut off and has no proof and it is said ibn abi sad and iblis of the one dejected and brought low all these conditions were gathered in him god spoke and he is the most truthful of those who speak', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 52, NULL, 'بَلِ السَّاعَةُ مَوْعِدُهُمْ وَالسَّاعَةُ أَدْهَىٰ وَأَمَرُّ"But the Hour is their appointed time, and the Hour shall be more calamitous and more bitter."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'بل الساعه موعدهم والساعه ادهي وامر but the hour is their appointed time and the hour shall be more calamitous and more bitter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 53, NULL, 'The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 54, NULL, 'مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ ۖ قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ"What prevented you from prostrating when I commanded you?" He said, "I am better than him. You created me from fire, and You created him from clay."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'ما منعك الا تسجد اذ امرتك قال انا خير منه خلقتني من نار وخلقته من طين what prevented you from prostrating when i commanded you he said i am better than him you created me from fire and you created him from clay', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 55, NULL, 'What he meant was: You raised me up in knowledge by spiritual cultivation, and granted me the brilliant supportive knowledge, the التَّأْيِيد, that carries no dense bodily mass with it, and You created Adam with a thick, heavy, corporeal knowledge fitted to a physical body — so how should I prostrate to one whom I am better than? In this way he exposed what he had been hiding, and openly declared his disobedience. God was angered with him, and He cursed him — that is, expelled him — saying:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'what he meant was you raised me up in knowledge by spiritual cultivation and granted me the brilliant supportive knowledge the التاييد that carries no dense bodily mass with it and you created adam with a thick heavy corporeal knowledge fitted to a physical body so how should i prostrate to one whom i am better than in this way he exposed what he had been hiding and openly declared his disobedience god was angered with him and he cursed him that is expelled him saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 56, NULL, 'Sayingفَاخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ ۖ وَإِنَّ عَلَيْكَ لَعْنَتِي إِلَىٰ يَوْمِ الدِّينِ"Get out of it — you are accursed, and indeed upon you is My curse until the Day of Recompense."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'sayingفاخرج منها فانك رجيم وان عليك لعنتي الي يوم الدين get out of it you are accursed and indeed upon you is my curse until the day of recompense', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 57, NULL, 'So He brought him out of the bounds of التَّأْيِيد, the supportive knowledge, cut him off from it, expelled him from it, and cursed him. Curse (اللَّعْن), in the language, is exactly that: expulsion.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'so he brought him out of the bounds of التاييد the supportive knowledge cut him off from it expelled him from it and cursed him curse اللعن in the language is exactly that expulsion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 58, NULL, 'God then created Eve — Hawwa — from Adam, because He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'god then created eve hawwa from adam because he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 59, NULL, 'وَخَلَقَ مِنْهَا زَوْجَهَا"And from it He created its mate."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'وخلق منها زوجها and from it he created its mate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 60, NULL, 'The creation here is the creation of التَّأْيِيد, of support, not a creation of body. God Almighty took her up and supported her, taught her, illumined her, and joined her to Adam in marriage; He made her his wife, and He made her his proof. He compensated Adam with her in place of Iblis. It is not what the common folk claim — that God cast Adam into sleep, took one of his ribs while he slept, and from that rib created Eve. They heard a fragment of the interpretation that they did not grasp and did not know truly: they heard that God exchanged for Adam one of his ribs and made that rib Eve, and they read it crudely. This is not so. God compensated Adam with Eve in the place of Iblis — who had been qualified to stand as Adam''s proof, as we have said — and He made her one of the twelve chiefs, the النُّقَبَاء. Their likeness, in the apparent creation of the human being, is the ribs of the body: a human being has twelve ribs on each side. Just as the right side resembles the inner knowledge and the left side the apparent knowledge, so the chiefs of the inner, subtle knowledge are twelve, and their counterparts for the knowledge of the outward are twelve as well.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the creation here is the creation of التاييد of support not a creation of body god almighty took her up and supported her taught her illumined her and joined her to adam in marriage he made her his wife and he made her his proof he compensated adam with her in place of iblis it is not what the common folk claim that god cast adam into sleep took one of his ribs while he slept and from that rib created eve they heard a fragment of the interpretation that they did not grasp and did not know truly they heard that god exchanged for adam one of his ribs and made that rib eve and they read it crudely this is not so god compensated adam with eve in the place of iblis who had been qualified to stand as adams proof as we have said and he made her one of the twelve chiefs the النقباء their likeness in the apparent creation of the human being is the ribs of the body a human being has twelve ribs on each side just as the right side resembles the inner knowledge and the left side the apparent knowledge so the chiefs of the inner subtle knowledge are twelve and their counterparts for the knowledge of the outward are twelve as well', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 61, NULL, 'Then God settled Adam and his wife in the Garden. The Garden, inwardly, is the ranks of the messengers of التَّأْيِيد, and beneath them the chiefs. When I say this, and the like of it about the subordinate ranks, I am not denying the outer reality — that the Garden is itself a created Garden. The Almighty has said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'then god settled adam and his wife in the garden the garden inwardly is the ranks of the messengers of التاييد and beneath them the chiefs when i say this and the like of it about the subordinate ranks i am not denying the outer reality that the garden is itself a created garden the almighty has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 62, NULL, 'وَمِن كُلِّ شَيْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ"And of every thing We created pairs, that perhaps you may remember."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'ومن كل شيء خلقنا زوجين لعلكم تذكرون and of every thing we created pairs that perhaps you may remember', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 63, NULL, 'Paradise is among the greatest of the things God has created and has prepared. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'paradise is among the greatest of the things god has created and has prepared the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 64, NULL, 'يَوْمَ لَا يُخْزِي اللَّهُ النَّبِيَّ وَالَّذِينَ آمَنُوا مَعَهُ ۖ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ"On the Day God will not disgrace the Prophet and those who believed with him: their light will proceed before them and on their right hands…"', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'يوم لا يخزي الله النبي والذين امنوا معه نورهم يسعي بين ايديهم وبايمانهم on the day god will not disgrace the prophet and those who believed with him their light will proceed before them and on their right hands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 65, NULL, '— and He gave glad tidings of gardens beneath which rivers flow, where they abide forever, calling it the great triumph. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'and he gave glad tidings of gardens beneath which rivers flow where they abide forever calling it the great triumph the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 66, NULL, 'وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ"And for him who fears the standing before his Lord, there are two gardens."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'ولمن خاف مقام ربه جنتان and for him who fears the standing before his lord there are two gardens', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 67, NULL, 'Then He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'then he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 68, NULL, 'وَبَشِّرِ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أَنَّ لَهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ۖ كُلَّمَا رُزِقُوا مِنْهَا مِن ثَمَرَةٍ رِّزْقًا ۙ قَالُوا هَٰذَا الَّذِي رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا بِهِ مُتَشَابِهًا"And give glad tidings to those who believe and do righteous deeds, that for them are gardens beneath which rivers flow. Whenever they are provided with fruit from them, they will say, This is what we were provided with before, and they will be given things in likeness."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'وبشر الذين امنوا وعملوا الصالحات ان لهم جنات تجري من تحتها الانهار كلما رزقوا منها من ثمره رزقا قالوا هذا الذي رزقنا من قبل واتوا به متشابها and give glad tidings to those who believe and do righteous deeds that for them are gardens beneath which rivers flow whenever they are provided with fruit from them they will say this is what we were provided with before and they will be given things in likeness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 69, NULL, 'He made Paradise a glad tiding for the believers, and He said elsewhere:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'he made paradise a glad tiding for the believers and he said elsewhere', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 70, NULL, 'جَزَاؤُهُمْ عِندَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ"Their reward is with their Lord — gardens of eternity beneath which rivers flow."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'جزاوهم عند ربهم جنات عدن تجري من تحتها الانهار their reward is with their lord gardens of eternity beneath which rivers flow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 71, NULL, 'He told them that for them is a Paradise in this world and a Paradise in the Hereafter. When He said, "Whenever they are provided with fruit from them, they will say, This is what we were provided with before," what He meant is exactly this: that what He grants in the Hereafter is the same kind of thing He has been supplying them with already — that is التَّأْيِيد, support, the inner thing they were already eating from in this life (الْحَيَاة).', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'he told them that for them is a paradise in this world and a paradise in the hereafter when he said whenever they are provided with fruit from them they will say this is what we were provided with before what he meant is exactly this that what he grants in the hereafter is the same kind of thing he has been supplying them with already that is التاييد support the inner thing they were already eating from in this life الحياه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 72, NULL, 'So let the listener not be misled into thinking that when we mention the inner meaning of Paradise we deny the eternal Paradise and the abode of bliss, or that when we mention the inner meaning of the Fire we deny that there is a real fire and a torment that has come to pass, or that when we read a subtle inner interpretation into a thing we cancel its outer reality. We seek refuge in God from any of that. He does nothing except that it has an inner aspect — and there is no inner without an outer. We do not see, in this world, a soul rising in a human being except within a body; we do not see any inner thing except inside an outer thing. If there were no outer, the very name inner would have nothing to attach to. Understand this, O company of believers, with full understanding. Let your hearts feel it. Many among the people of this knowledge have perished by exactly this point — letting one half eat the other. It was for the same reason that Adam fell into sin, as we shall mention when we come to it. So believe what God has revealed, outwardly and inwardly; believe it, and act upon it. God Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'so let the listener not be misled into thinking that when we mention the inner meaning of paradise we deny the eternal paradise and the abode of bliss or that when we mention the inner meaning of the fire we deny that there is a real fire and a torment that has come to pass or that when we read a subtle inner interpretation into a thing we cancel its outer reality we seek refuge in god from any of that he does nothing except that it has an inner aspect and there is no inner without an outer we do not see in this world a soul rising in a human being except within a body we do not see any inner thing except inside an outer thing if there were no outer the very name inner would have nothing to attach to understand this o company of believers with full understanding let your hearts feel it many among the people of this knowledge have perished by exactly this point letting one half eat the other it was for the same reason that adam fell into sin as we shall mention when we come to it so believe what god has revealed outwardly and inwardly believe it and act upon it god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 73, NULL, 'وَذَرُوا ظَاهِرَ الْإِثْمِ وَبَاطِنَهُ"And forsake the outwardness of sin and its inwardness."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'وذروا ظاهر الاثم وباطنه and forsake the outwardness of sin and its inwardness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 74, NULL, 'He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 75, NULL, 'وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظَاهِرَةً وَبَاطِنَةً"And He has lavished upon you His bounties, outward and inward."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'واسبغ عليكم نعمه ظاهره وباطنه and he has lavished upon you his bounties outward and inward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 76, NULL, 'The lawful outward is lawful, and the lawful inward is lawful; the forbidden outward is forbidden, and the forbidden inward is forbidden. Everything, as we have said, has an outer and an inner.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the lawful outward is lawful and the lawful inward is lawful the forbidden outward is forbidden and the forbidden inward is forbidden everything as we have said has an outer and an inner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 77, NULL, 'As for the parables God Almighty strikes for His servants — when He says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'as for the parables god almighty strikes for his servants when he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 78, NULL, 'وَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ ۖ وَمَا يَعْقِلُهَا إِلَّا الْعَالِمُونَ"And these parables We strike for the people, but none understand them except those who know"', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'وتلك الامثال نضربها للناس وما يعقلها الا العالمون and these parables we strike for the people but none understand them except those who know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 79, NULL, '— and when He says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'and when he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 80, NULL, 'Sayingإِنَّ اللَّهَ لَا يَسْتَحْيِي أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا ۚ فَأَمَّا الَّذِينَ آمَنُوا فَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا الَّذِينَ كَفَرُوا فَيَقُولُونَ مَاذَا أَرَادَ اللَّهُ بِهَٰذَا مَثَلًا ۘ يُضِلُّ بِهِ كَثِيرًا وَيَهْدِي بِهِ كَثِيرًا ۚ وَمَا يُضِلُّ بِهِ إِلَّا الْفَاسِقِينَ ۙ الَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَاقِهِ"God is not ashamed to strike a parable, even of a mosquito or what is above it. As for those who believe, they know it is the truth from their Lord; and as for those who disbelieve, they say, What did God intend by this parable? He misleads many by it and guides many by it — and He misleads not by it except the corrupters, those who break the covenant of God after its ratification."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'sayingان الله لا يستحيي ان يضرب مثلا ما بعوضه فما فوقها فاما الذين امنوا فيعلمون انه الحق من ربهم واما الذين كفروا فيقولون ماذا اراد الله بهذا مثلا يضل به كثيرا ويهدي به كثيرا وما يضل به الا الفاسقين الذين ينقضون عهد الله من بعد ميثاقه god is not ashamed to strike a parable even of a mosquito or what is above it as for those who believe they know it is the truth from their lord and as for those who disbelieve they say what did god intend by this parable he misleads many by it and guides many by it and he misleads not by it except the corrupters those who break the covenant of god after its ratification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 81, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 82, NULL, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَٰذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ"And We have struck for the people in this Quran from every parable."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'ولقد ضربنا للناس في هذا القران من كل مثل and we have struck for the people in this quran from every parable', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 83, NULL, 'The way these parables work is not the way of the outer-and-inner symbolism in which what symbolizes and what is symbolized are both real, established things standing side by side. In a parable, the established and obligatory thing represented by the figure is like His saying:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the way these parables work is not the way of the outer and inner symbolism in which what symbolizes and what is symbolized are both real established things standing side by side in a parable the established and obligatory thing represented by the figure is like his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 84, NULL, 'Sayingاهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۙ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ"Guide us to the straight path — the path of those upon whom You have bestowed favor, not of those who incurred wrath, nor of those who are astray."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'sayingاهدنا الصراط المستقيم صراط الذين انعمت عليهم غير المغضوب عليهم ولا الضالين guide us to the straight path the path of those upon whom you have bestowed favor not of those who incurred wrath nor of those who are astray', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 85, NULL, 'Path (الصِّرَاط), in the language, is a road (الطَّرِيق). The Imam stands here in the place of the road, because whoever is bound to follow the Imam will not stray, and whoever needs guidance through him will not be misled. What is meant by road here is the Imam — not a road taken on the ground.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'path الصراط in the language is a road الطريق the imam stands here in the place of the road because whoever is bound to follow the imam will not stray and whoever needs guidance through him will not be misled what is meant by road here is the imam not a road taken on the ground', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 86, NULL, 'Let us return to Adam (peace be upon him), and to the inner meaning of the Garden, which is التَّأْيِيد — supportive knowledge, in its true, pure, spiritual content. The bliss in it surpasses every other bliss, and the pleasure in it exceeds every other pleasure. For this reason, whoever attains it renounces every worldly attachment. Things shrivel in his eye. Everything in this world is diminished in his sight. He comes to make light (النُّور) of his attachment to anything other than that knowledge. His union with it he finds to be perfect bliss, and a glory that no humiliation can follow — as in the hadith of the Commander of the Believers to Kumayl ibn Ziyad (كُمَيْلُ بْنُ زِيَاد), when he said: "Knowledge is the ruler, and wealth is the ruled. Wealth runs out as it is spent; knowledge purifies as it is spent. Wealth''s store decays, but the scholars endure as long as time endures. Their persons are absent, yet their traces remain in the world." The hadith is long; I have taken from it only what is needed.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'let us return to adam peace be upon him and to the inner meaning of the garden which is التاييد supportive knowledge in its true pure spiritual content the bliss in it surpasses every other bliss and the pleasure in it exceeds every other pleasure for this reason whoever attains it renounces every worldly attachment things shrivel in his eye everything in this world is diminished in his sight he comes to make light النور of his attachment to anything other than that knowledge his union with it he finds to be perfect bliss and a glory that no humiliation can follow as in the hadith of the commander of the believers to kumayl ibn ziyad كميل بن زياد when he said knowledge is the ruler and wealth is the ruled wealth runs out as it is spent knowledge purifies as it is spent wealths store decays but the scholars endure as long as time endures their persons are absent yet their traces remain in the world the hadith is long i have taken from it only what is needed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 87, NULL, 'The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 88, NULL, 'يَا آدَمُ اسْكُنْ أَنتَ وَزَوْجُكَ الْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ"O Adam, dwell — you and your wife — in the Garden, and eat freely from it wherever you wish; but do not approach this tree, or you will be among the wrongdoers."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'يا ادم اسكن انت وزوجك الجنه وكلا منها رغدا حيث شيتما ولا تقربا هذه الشجره فتكونا من الظالمين o adam dwell you and your wife in the garden and eat freely from it wherever you wish but do not approach this tree or you will be among the wrongdoers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 89, NULL, 'He warned Adam against Iblis:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'he warned adam against iblis', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 90, NULL, 'فَإِنَّ هَٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ الْجَنَّةِ فَتَشْقَىٰ"Indeed, this is an enemy to you and to your wife, so let him not drive you both out of the Garden, lest you become miserable."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'فان هذا عدو لك ولزوجك فلا يخرجنكما من الجنه فتشقي indeed this is an enemy to you and to your wife so let him not drive you both out of the garden lest you become miserable', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 91, NULL, 'And He entrusted Adam with a charge:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'and he entrusted adam with a charge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 92, NULL, 'وَلَقَدْ عَهِدْنَا إِلَىٰ آدَمَ مِن قَبْلُ فَنَسِيَ وَلَمْ نَجِدْ لَهُ عَزْمًا"And We had already taken a covenant with Adam before, but he forgot, and We found no firm resolve in him."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'ولقد عهدنا الي ادم من قبل فنسي ولم نجد له عزما and we had already taken a covenant with adam before but he forgot and we found no firm resolve in him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 93, NULL, 'What He had permitted to Adam and his wife were the ranks of the messengers, opened to them according to their conditions and the duties He had laid upon them: to declare lawful what was lawful, to declare forbidden what was forbidden, to ward off the forbidden, to warn against it. And the tree — the tree He forbade Adam to approach, the tree He fenced off and made unlawful for him — that tree is a likeness for the Master of the Time, the صَاحِبُ الْقِيَامَة, the Possessor of the Resurrection. Within his limits lie the duties of charge; before his appearance they do not yet apply. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'what he had permitted to adam and his wife were the ranks of the messengers opened to them according to their conditions and the duties he had laid upon them to declare lawful what was lawful to declare forbidden what was forbidden to ward off the forbidden to warn against it and the tree the tree he forbade adam to approach the tree he fenced off and made unlawful for him that tree is a likeness for the master of the time the صاحب القيامه the possessor of the resurrection within his limits lie the duties of charge before his appearance they do not yet apply the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 94, NULL, 'لَا يَنفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ۗ قُلِ انتَظِرُوا إِنَّا مُنتَظِرُونَ"No soul will be benefited by its faith if it had not believed before, or earned good through its faith. Say, Wait — indeed, we too are waiting."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'لا ينفع نفسا ايمانها لم تكن امنت من قبل او كسبت في ايمانها خيرا قل انتظروا انا منتظرون no soul will be benefited by its faith if it had not believed before or earned good through its faith say wait indeed we too are waiting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 95, NULL, 'From such a soul no recompense will be accepted, no punishment exacted, no intercession received. Then the inner will be stripped away, the outer will fall off, and the inner will become apparent. The Master of the Resurrection stands beyond the bounds of the messengers who came before him, because the inner knowledge entrusted within their ranks has been paid out, in his absence, to their proofs — concealed in them, carried by them, handed from one to the next as a deposit and an illumination — until it reaches its rightful holder, who is the Master of the Day of Resurrection. He, when he comes, will make it openly manifest and strip away its outer covering. That open disclosure was forbidden, unlawful, before him. So God forbade Adam this tree at the outset of the matter — so that the unalterable custom of God might be carried out — and Iblis asked for respite until the appointed Day, meaning the Day of Resurrection, and he said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'from such a soul no recompense will be accepted no punishment exacted no intercession received then the inner will be stripped away the outer will fall off and the inner will become apparent the master of the resurrection stands beyond the bounds of the messengers who came before him because the inner knowledge entrusted within their ranks has been paid out in his absence to their proofs concealed in them carried by them handed from one to the next as a deposit and an illumination until it reaches its rightful holder who is the master of the day of resurrection he when he comes will make it openly manifest and strip away its outer covering that open disclosure was forbidden unlawful before him so god forbade adam this tree at the outset of the matter so that the unalterable custom of god might be carried out and iblis asked for respite until the appointed day meaning the day of resurrection and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 96, NULL, 'أَنظِرْنِي إِلَىٰ يَوْمِ يُبْعَثُونَ"Grant me respite until the Day they are resurrected"', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'انظرني الي يوم يبعثون grant me respite until the day they are resurrected', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 97, NULL, '— so that, in the meantime, he might have a little reach into Adam''s offspring. He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'so that in the meantime he might have a little reach into adams offspring he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 98, NULL, 'وَاسْتَفْزِزْ مَنِ اسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِي الْأَمْوَالِ وَالْأَوْلَادِ"And rouse with your voice whoever of them you can — meaning, stir them to remember you — and assault them with your cavalry and your foot — meaning, whoever follows you in your falsehood, press them into your command — and become a partner with them in wealth and offspring."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'واستفزز من استطعت منهم بصوتك واجلب عليهم بخيلك ورجلك وشاركهم في الاموال والاولاد and rouse with your voice whoever of them you can meaning stir them to remember you and assault them with your cavalry and your foot meaning whoever follows you in your falsehood press them into your command and become a partner with them in wealth and offspring', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 99, NULL, 'That is: become a partner in the knowledge of wealth, if your doubt and your falsehood enter them. He means here the children born through faith, because they are like the people of the call in the inner sense. Of His children in this way the Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'that is become a partner in the knowledge of wealth if your doubt and your falsehood enter them he means here the children born through faith because they are like the people of the call in the inner sense of his children in this way the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 100, NULL, 'مِّلَّةَ أَبِيكُمْ إِبْرَاهِيمَ ۚ هُوَ سَمَّاكُمُ الْمُسْلِمِينَ"It is the religion of your father Ibrahim. It is He who named you Muslims."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'مله ابيكم ابراهيم هو سماكم المسلمين it is the religion of your father ibrahim it is he who named you muslims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 101, NULL, 'The one who calls the believers is like a father to them, and the proof is like a mother, because she carries them, nurses them, and raises them in the knowledge. Therefore the Messenger of God (peace and blessings be upon him) said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'the one who calls the believers is like a father to them and the proof is like a mother because she carries them nurses them and raises them in the knowledge therefore the messenger of god peace and blessings be upon him said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 102, NULL, 'Sayingأَنَا وَأَنْتَ يَا عَلِيُّ أَبَوَا هَٰذِهِ الْأُمَّةِ"I and you, O Ali, are the two fathers of this nation."', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'sayingانا وانت يا علي ابوا هذه الامه i and you o ali are the two fathers of this nation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 103, NULL, 'So Iblis''s wish was to say: share with them in their sons who believe in your falsehood — those who, by your work, have become your sons by right — and whoever among them you have overcome with your falsehood, you have transferred from their birth (which is the birth of faith) into your birth (which is the birth of unbelief); share with them in this, having promised them your arrogance and your falsehood. And God made it a trial for them. Then He gave them notice of His servants who hold loyal to Him — that Iblis would not prevail over them, that He would return them to Himself in full, that they are of His party and His sons. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'so ibliss wish was to say share with them in their sons who believe in your falsehood those who by your work have become your sons by right and whoever among them you have overcome with your falsehood you have transferred from their birth which is the birth of faith into your birth which is the birth of unbelief share with them in this having promised them your arrogance and your falsehood and god made it a trial for them then he gave them notice of his servants who hold loyal to him that iblis would not prevail over them that he would return them to himself in full that they are of his party and his sons the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'adam, the tree, and the iblis pact', '3. Adam, the Tree, and the Iblis Pact', 104, NULL, 'إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ"Indeed, over My servants you will have no authority."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 3 adam the tree and the iblis pact', 'ان عبادي ليس لك عليهم سلطان indeed over my servants you will have no authority', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 0, NULL, 'He made for Himself a party out of His own creation, and He described the other party — the party of Satan — so that no one could mistake which side he stood on. Listen to how He names them:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'he made for himself a party out of his own creation and he described the other party the party of satan so that no one could mistake which side he stood on listen to how he names them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 1, NULL, 'Sayingأَلَمْ تَرَ إِلَى الَّذِينَ تَوَلَّوْا قَوْمًا غَضِبَ اللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى الْكَذِبِ وَهُمْ يَعْلَمُونَ ۚ أَعَدَّ اللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ إِنَّهُمْ سَاءَ مَا كَانُوا يَعْمَلُونَ ۚ اتَّخَذُوا أَيْمَانَهُمْ جُنَّةً فَصَدُّوا عَن سَبِيلِ اللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ ۚ لَّن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا ۚ أُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ ۚ يَوْمَ يَبْعَثُهُمُ اللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُ كَمَا يَحْلِفُونَ لَكُمْ ۖ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَيْءٍ ۚ أَلَا إِنَّهُمْ هُمُ الْكَاذِبُونَ ۚ اسْتَحْوَذَ عَلَيْهِمُ الشَّيْطَانُ فَأَنسَاهُمْ ذِكْرَ اللَّهِ ۚ أُولَٰئِكَ حِزْبُ الشَّيْطَانِ ۚ أَلَا إِنَّ حِزْبَ الشَّيْطَانِ هُمُ الْخَاسِرُونَ"Have you not considered those who make allies of a people upon whom God has placed His wrath" — meaning the nation of misguidance — "they are neither of you nor of them, and they swear to falsehood while they know. God has prepared for them a severe punishment; evil indeed is what they used to do. They took their oaths as a cover and averted people from the way of God, so for them is a humiliating punishment. Never will their wealth or their children avail them against God at all. Those are the companions of the Fire; they will abide therein eternally — on the Day when God will resurrect them all, and they will swear to Him as they swear to you, thinking that they are upon something. Unquestionably, it is they who are the liars. Satan has overcome them and made them forget the remembrance of God. Those are the party of Satan. Unquestionably, the party of Satan — they will be the losers." (Al-Mujadila: 14-19)', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'sayingالم تر الي الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون علي الكذب وهم يعلمون اعد الله لهم عذابا شديدا انهم ساء ما كانوا يعملون اتخذوا ايمانهم جنه فصدوا عن سبيل الله فلهم عذاب مهين لن تغني عنهم اموالهم ولا اولادهم من الله شييا اوليك اصحاب النار هم فيها خالدون يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم ويحسبون انهم علي شيء الا انهم هم الكاذبون استحوذ عليهم الشيطان فانساهم ذكر الله اوليك حزب الشيطان الا ان حزب الشيطان هم الخاسرون have you not considered those who make allies of a people upon whom god has placed his wrath meaning the nation of misguidance they are neither of you nor of them and they swear to falsehood while they know god has prepared for them a severe punishment evil indeed is what they used to do they took their oaths as a cover and averted people from the way of god so for them is a humiliating punishment never will their wealth or their children avail them against god at all those are the companions of the fire they will abide therein eternally on the day when god will resurrect them all and they will swear to him as they swear to you thinking that they are upon something unquestionably it is they who are the liars satan has overcome them and made them forget the remembrance of god those are the party of satan unquestionably the party of satan they will be the losers al mujadila 14 19', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 2, NULL, 'Then, in the same breath, He turned and described His own party — those who are His by claim and by love:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'then in the same breath he turned and described his own party those who are his by claim and by love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 3, NULL, 'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ يُوَادُّونَ مَنْ حَادَّ اللَّهَ وَرَسُولَهُ وَلَوْ كَانُوا آبَاءَهُمْ أَوْ أَبْنَاءَهُمْ أَوْ إِخْوَانَهُمْ أَوْ عَشِيرَتَهُمْ ۚ أُولَٰئِكَ كَتَبَ فِي قُلُوبِهِمُ الْإِيمَانَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ ۖ وَيُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ۚ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ۚ أُولَٰئِكَ حِزْبُ اللَّهِ ۚ أَلَا إِنَّ حِزْبَ اللَّهِ هُمُ الْمُفْلِحُونَ"You will not find a people who believe in God and the Last Day having affection for those who oppose God and His Messenger" — meaning the imams of injustice and their followers — "even if they were their fathers or their sons or their brothers or their kindred. Those — He has decreed faith within their hearts and supported them with a spirit from Himself. And He will admit them to gardens beneath which rivers flow, wherein they will abide eternally. God is pleased with them, and they are pleased with Him. Those are the party of God. Unquestionably, the party of God — they are the successful." (Al-Mujadila: 22)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'لا تجد قوما يومنون بالله واليوم الاخر يوادون من حاد الله ورسوله ولو كانوا اباءهم او ابناءهم او اخوانهم او عشيرتهم اوليك كتب في قلوبهم الايمان وايدهم بروح منه ويدخلهم جنات تجري من تحتها الانهار خالدين فيها رضي الله عنهم ورضوا عنه اوليك حزب الله الا ان حزب الله هم المفلحون you will not find a people who believe in god and the last day having affection for those who oppose god and his messenger meaning the imams of injustice and their followers even if they were their fathers or their sons or their brothers or their kindred those he has decreed faith within their hearts and supported them with a spirit from himself and he will admit them to gardens beneath which rivers flow wherein they will abide eternally god is pleased with them and they are pleased with him those are the party of god unquestionably the party of god they are the successful al mujadila 22', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 4, NULL, 'The line between the two parties is drawn by guardianship. God''s party are those who cling to Him and have taken His guardians as their own. The party of Satan are those whom Iblis has bought and severed for himself: he forced his way into their loyalties, and they took as their friends his enemies — who, though they do not see it, are their enemies too — and they walked away from God''s guardianship and the guardianship of God''s friends, and gave their hearts instead to Satan and to Satan''s allies.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'the line between the two parties is drawn by guardianship gods party are those who cling to him and have taken his guardians as their own the party of satan are those whom iblis has bought and severed for himself he forced his way into their loyalties and they took as their friends his enemies who though they do not see it are their enemies too and they walked away from gods guardianship and the guardianship of gods friends and gave their hearts instead to satan and to satans allies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 5, NULL, 'And yet — and this matters — whoever was once abased by Satan, then awoke to his abasement and was grieved by it, who pulled himself free from his stumbling and turned back to his Lord, that one is no longer Satan''s, and no longer of his party. The door is open. God Almighty says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'and yet and this matters whoever was once abased by satan then awoke to his abasement and was grieved by it who pulled himself free from his stumbling and turned back to his lord that one is no longer satans and no longer of his party the door is open god almighty says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'verse', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 6, NULL, 'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًۭا', '', 'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًۭا', NULL, 4, 110, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'ومن يعمل سوءا او يظلم نفسه ثم يستغفر الله يجد الله غفورا', 'ومن يعمل سوءا او يظلم نفسه ثم يستغفر الله يجد الله غفورا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 7, NULL, 'وَمَن يَعْمَلْ سُوءًا أَوْ يَظْلِمْ نَفْسَهُ ثُمَّ يَسْتَغْفِرِ اللَّهَ يَجِدِ اللَّهَ غَفُورًا رَّحِيمًا"And whoever does evil or wrongs himself but then seeks forgiveness of God will find God Forgiving and Merciful." (An-Nisa: 110)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'ومن يعمل سوءا او يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما and whoever does evil or wrongs himself but then seeks forgiveness of god will find god forgiving and merciful an nisa 110', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 8, NULL, 'Al-Sadiq, peace be upon him, said: "Do not consider as a guardian (وَلِيّ) one whom Satan has abased entirely; rather, consider as a guardian a man who turns back, relying on his Lord." The man who returns is the man fit to lead.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'al sadiq peace be upon him said do not consider as a guardian ولي one whom satan has abased entirely rather consider as a guardian a man who turns back relying on his lord the man who returns is the man fit to lead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 9, NULL, 'Look at the first abasement and you will understand every one that came after it. The cursed Satan abased Adam and Hawwa, peace be upon them, with a sentence. God Himself has reported what he whispered:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'look at the first abasement and you will understand every one that came after it the cursed satan abased adam and hawwa peace be upon them with a sentence god himself has reported what he whispered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 10, NULL, 'Sayingمَا نَهَاكُمَا رَبُّكُمَا عَنْ هَٰذِهِ الشَّجَرَةِ إِلَّا أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ الْخَالِدِينَ ۝ وَقَاسَمَهُمَا إِنِّي لَكُمَا لَمِنَ النَّاصِحِينَ"Your Lord did not forbid you this tree except that you might become kings, or that you might become among the immortals," and he swore to them: "Indeed I am to you among the sincere advisors." (Al-Araf: 20-21)', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'sayingما نهاكما ربكما عن هذه الشجره الا ان تكونا ملكين او تكونا من الخالدين وقاسمهما اني لكما لمن الناصحين your lord did not forbid you this tree except that you might become kings or that you might become among the immortals and he swore to them indeed i am to you among the sincere advisors al araf 20 21', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 11, NULL, 'Satan made plain to them what was permitted and what was forbidden, and where the limit lay. The limit of obligation, he said, was the limit of effort and aspiration: if only they would push past the boundary God had set, they would slough off the dense material world and rise among the gentle spiritual angels, two sovereigns living forever in whatever they wished. But the limit he was urging them across was not theirs to cross. The Almighty said: "But if they had not been beguiled, they would not have tasted of the tree, and it appeared evil to them." They transgressed the limits of speech that had been permitted to them, into the limit that belongs to the Lord of the Resurrection — the very thing God had warned them about — and they extended their hands to what was not theirs.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'satan made plain to them what was permitted and what was forbidden and where the limit lay the limit of obligation he said was the limit of effort and aspiration if only they would push past the boundary god had set they would slough off the dense material world and rise among the gentle spiritual angels two sovereigns living forever in whatever they wished but the limit he was urging them across was not theirs to cross the almighty said but if they had not been beguiled they would not have tasted of the tree and it appeared evil to them they transgressed the limits of speech that had been permitted to them into the limit that belongs to the lord of the resurrection the very thing god had warned them about and they extended their hands to what was not theirs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 12, NULL, 'So they ate. They ate from the tree and they fell into sin, and at the moment of the fall, the support that had been holding them up was cut. That support is what God names in His Book: the garment of piety. He said: "And that is from the signs (آيَات) of God." (Al-Araf: 26) They were stripped bare of it, and what was reprehensible became visible to them — the intensity of the natural image, all the rough density of the lower world — because the garment of piety, which is the word, had fallen away. By the light (النُّور) of that garment Hawwa had seen, until then, all the darkness (الظَّلَام) in which she was compounded. Support does not accompany sin; reaching for what is not yours is a hand that must, by ruling, be cut off. When the support ceased, as the Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'so they ate they ate from the tree and they fell into sin and at the moment of the fall the support that had been holding them up was cut that support is what god names in his book the garment of piety he said and that is from the signs ايات of god al araf 26 they were stripped bare of it and what was reprehensible became visible to them the intensity of the natural image all the rough density of the lower world because the garment of piety which is the word had fallen away by the light النور of that garment hawwa had seen until then all the darkness الظلام in which she was compounded support does not accompany sin reaching for what is not yours is a hand that must by ruling be cut off when the support ceased as the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 13, NULL, 'وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ"They began to stitch upon themselves leaves from Paradise." (Al-Araf: 22)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'وطفقا يخصفان عليهما من ورق الجنه they began to stitch upon themselves leaves from paradise al araf 22', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 14, NULL, 'They gathered what light of wisdom was still left to them and tried to cover the shame that had been laid bare. What was revealed in their condition was the loss of support; and through ignorance of this matter many who hold to it have perished, and the shame has been made into a permission.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'they gathered what light of wisdom was still left to them and tried to cover the shame that had been laid bare what was revealed in their condition was the loss of support and through ignorance of this matter many who hold to it have perished and the shame has been made into a permission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 15, NULL, 'Then they cried out to their Lord. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'then they cried out to their lord the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 16, NULL, 'Sayingأَلَمْ أَنْهَكُمَا عَن تِلْكُمَا الشَّجَرَةِ وَأَقُل لَّكُمَا إِنَّ الشَّيْطَانَ لَكُمَا عَدُوٌّ مُّبِينٌ ۝ قَالَا رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ"Did I not forbid you that tree and tell you that Satan is to you a clear enemy? They said: Our Lord, we have wronged ourselves; if You do not forgive us and have mercy on us, we will surely be among the losers." (Al-Araf: 22-23)', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'sayingالم انهكما عن تلكما الشجره واقل لكما ان الشيطان لكما عدو مبين قالا ربنا ظلمنا انفسنا وان لم تغفر لنا وترحمنا لنكونن من الخاسرين did i not forbid you that tree and tell you that satan is to you a clear enemy they said our lord we have wronged ourselves if you do not forgive us and have mercy on us we will surely be among the losers al araf 22 23', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 17, NULL, 'Adam did not turn away as Iblis had turned away. He turned back. He repented, and asked for mercy, and asked for forgiveness.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'adam did not turn away as iblis had turned away he turned back he repented and asked for mercy and asked for forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 18, NULL, 'فَتَلَقَّىٰ آدَمُ مِن رَّبِّهِ كَلِمَاتٍ فَتَابَ عَلَيْهِ ۚ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ"Then Adam received from his Lord words, so He turned to him in forgiveness; indeed He is the Accepter of Repentance, the Merciful." (Al-Baqarah: 37)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'فتلقي ادم من ربه كلمات فتاب عليه انه هو التواب الرحيم then adam received from his lord words so he turned to him in forgiveness indeed he is the accepter of repentance the merciful al baqarah 37', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 19, NULL, 'He drew close to Him, and found Him turning toward him from the side of the higher limits, and was met there with mercy. Satan never had the authority to drag him back into his own camp and take him as a possession; Adam remained of the Party of God. The Almighty turned to him, forgave him, received his words. And from then on, this became the pattern for his descendants. Whoever sinned and then repented from his sin, God turned to in forgiveness, and that one belonged to His party. Whoever persisted in sin and did not repent, whoever no words came from his Lord to receive — that one was of the party of Iblis and his soldiers. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'he drew close to him and found him turning toward him from the side of the higher limits and was met there with mercy satan never had the authority to drag him back into his own camp and take him as a possession adam remained of the party of god the almighty turned to him forgave him received his words and from then on this became the pattern for his descendants whoever sinned and then repented from his sin god turned to in forgiveness and that one belonged to his party whoever persisted in sin and did not repent whoever no words came from his lord to receive that one was of the party of iblis and his soldiers the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 20, NULL, 'وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوا أَنفُسَهُمْ جَاءُوكَ فَاسْتَغْفَرُوا اللَّهَ وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ لَوَجَدُوا اللَّهَ تَوَّابًا رَّحِيمًا"If, when they wronged themselves, they had come to you and asked forgiveness of God, and the Messenger had asked forgiveness for them, they would have found God Accepting of Repentance and Merciful." (An-Nisa: 64)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'ولو انهم اذ ظلموا انفسهم جاءوك فاستغفروا الله واستغفر لهم الرسول لوجدوا الله توابا رحيما if when they wronged themselves they had come to you and asked forgiveness of god and the messenger had asked forgiveness for them they would have found god accepting of repentance and merciful an nisa 64', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 21, NULL, 'Take that verse seriously. Repentance is not accepted except by God''s receiving His words for the repentant; the sinner is not forgiven until after forgiveness has been sought, and until the words have been spoken on his behalf. This is the parallel statement to the tree God forbade Adam — the tree of which, in the inner (نَار) sense I am unfolding for you in this book, he ate nothing literally, but to which he was exposed, and which was the beginning of his trouble. That is the esoteric meaning, the inner interpretation that belongs to the elaborate punishment treated here.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'take that verse seriously repentance is not accepted except by gods receiving his words for the repentant the sinner is not forgiven until after forgiveness has been sought and until the words have been spoken on his behalf this is the parallel statement to the tree god forbade adam the tree of which in the inner نار sense i am unfolding for you in this book he ate nothing literally but to which he was exposed and which was the beginning of his trouble that is the esoteric meaning the inner interpretation that belongs to the elaborate punishment treated here', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 22, NULL, 'It is not what the outward interpreters have said. They claimed the tree was a wheat tree; some said a fig tree; some said a grape vine. They claimed its clothing was a kind of nail-like material, forbidden to them; that when they repented, what was left of it stayed in their fingertips, and from there in their children, and that this is why most animals have nails and the like — hooves of cows and sheep, claws of predators and birds — and that Adam''s descendants are not inspired with what he received but bear the residue in their limbs as a wisdom in the composition that the Maker could recall when He pleased. Even if the garment had truly been of nail, the inner meaning would be the same. The literal claim is one the mind cannot accept and which does not survive examination.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'it is not what the outward interpreters have said they claimed the tree was a wheat tree some said a fig tree some said a grape vine they claimed its clothing was a kind of nail like material forbidden to them that when they repented what was left of it stayed in their fingertips and from there in their children and that this is why most animals have nails and the like hooves of cows and sheep claws of predators and birds and that adams descendants are not inspired with what he received but bear the residue in their limbs as a wisdom in the composition that the maker could recall when he pleased even if the garment had truly been of nail the inner meaning would be the same the literal claim is one the mind cannot accept and which does not survive examination', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 23, NULL, 'The same goes for what they have said about the figure of his disgrace — that Adam and Hawwa had their sins exposed and so sewed themselves a covering of fig leaves. That is not proven either, because it did not happen. God has named Adam in honor, and Adam is too noble for it: a prophet whom He has chosen and elevated. To imagine, even on the supposition that he was merely one of the followers, that God would look at him as a man looks at a slave who has angered him, then strip him naked and leave him there, beginning his humiliation with that act — they attribute this to their idol; God is exalted above it.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'the same goes for what they have said about the figure of his disgrace that adam and hawwa had their sins exposed and so sewed themselves a covering of fig leaves that is not proven either because it did not happen god has named adam in honor and adam is too noble for it a prophet whom he has chosen and elevated to imagine even on the supposition that he was merely one of the followers that god would look at him as a man looks at a slave who has angered him then strip him naked and leave him there beginning his humiliation with that act they attribute this to their idol god is exalted above it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 24, NULL, 'Most of those who held this interpretation took it from the Jewish converts among their ancestors — Kab al-Ahbar (كَعْبُ الْأَحْبَار), Abdullah ibn Salam (عبدالله بن سلام), and others — because they say it is in their tradition: that Adam and Eve remained naked in Paradise, that they sensed God walking among its trees, that they hid from Him among the trees, and that He called out to them, "Where are you?" They said: "We sensed You among the trees of Paradise while we were naked, and we were ashamed before You, so we hid." And He said: "Did you eat from the tree?" Adam said: "The woman fed me." The woman said: "The serpent commanded me." The serpent said: "Iblis. He entered me through the underground."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'most of those who held this interpretation took it from the jewish converts among their ancestors kab al ahbar كعب الاحبار abdullah ibn salam عبدالله بن سلام and others because they say it is in their tradition that adam and eve remained naked in paradise that they sensed god walking among its trees that they hid from him among the trees and that he called out to them where are you they said we sensed you among the trees of paradise while we were naked and we were ashamed before you so we hid and he said did you eat from the tree adam said the woman fed me the woman said the serpent commanded me the serpent said iblis he entered me through the underground', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 25, NULL, 'Whether God should interpret this so literally — that the lands hold such a thing, that it is seen with the eyes — no. In the Torah and the Gospel, as in the Quran, there are proverbs, signs, and symbols, and an outward face that requires interpretation, and that interpretation is the stored knowledge (الْعِلْم). God Almighty says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'whether god should interpret this so literally that the lands hold such a thing that it is seen with the eyes no in the torah and the gospel as in the quran there are proverbs signs and symbols and an outward face that requires interpretation and that interpretation is the stored knowledge العلم god almighty says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 26, NULL, 'قُلْ يَا أَهْلَ الْكِتَابِ لَسْتُمْ عَلَىٰ شَيْءٍ حَتَّىٰ تُقِيمُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ"Say: O People of the Book, you stand upon nothing until you uphold the Torah and the Gospel and what has been revealed to you from your Lord." (Al-Maidah: 68)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'قل يا اهل الكتاب لستم علي شيء حتي تقيموا التوراه والانجيل وما انزل اليكم من ربكم say o people of the book you stand upon nothing until you uphold the torah and the gospel and what has been revealed to you from your lord al maidah 68', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 27, NULL, 'From which it is known that they do not establish these scriptures except by interpretation. And so it has been said in interpretation that the Torah is like the outward and the Gospel is like the inward — and God has commanded, and the Almighty will establish them all, as we have said, by means of the knowledge He has sent down: the knowledge Adam deposited and transmitted in the word, carried forward by the foundations, the imams, and their successors among their descendants, upon them all be the prayers and peace of God.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'from which it is known that they do not establish these scriptures except by interpretation and so it has been said in interpretation that the torah is like the outward and the gospel is like the inward and god has commanded and the almighty will establish them all as we have said by means of the knowledge he has sent down the knowledge adam deposited and transmitted in the word carried forward by the foundations the imams and their successors among their descendants upon them all be the prayers and peace of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 28, NULL, 'As for the phrase "And their Lord called them" — His call is His own call, a call from Him to them, not the kind of call one hears from a man shouting across a courtyard. The same holds for everything we mention concerning His sayings, blessed be His name; we have explained this at length before. But servants engage with it the same way they engage with everything, attributing to Him what is contrary to Him and unfit for Him. What is customary among worshipers is that a voice only comes out of a voice, from a hollow and a passageway, and that speech is the same — only with lips and tongue. They project that custom upward, and the projection is in conflict with the very claim of divinity. God is exalted above it.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'as for the phrase and their lord called them his call is his own call a call from him to them not the kind of call one hears from a man shouting across a courtyard the same holds for everything we mention concerning his sayings blessed be his name we have explained this at length before but servants engage with it the same way they engage with everything attributing to him what is contrary to him and unfit for him what is customary among worshipers is that a voice only comes out of a voice from a hollow and a passageway and that speech is the same only with lips and tongue they project that custom upward and the projection is in conflict with the very claim of divinity god is exalted above it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 29, NULL, 'When God turned to Adam in repentance, He did not remove him from the rank of caliphate and imamate He had set up for him, nor strip him of his substance, his word, or his wisdom in general. He brought him down — and Hawwa with him — from the limits of interpretation without a veil. He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'when god turned to adam in repentance he did not remove him from the rank of caliphate and imamate he had set up for him nor strip him of his substance his word or his wisdom in general he brought him down and hawwa with him from the limits of interpretation without a veil he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 30, NULL, 'اهْبِطُوا مِنْهَا جَمِيعًا"Go down from it together" — from the light which was, on earth, the good for you — "and you will have therein dwelling and enjoyment for a time." (Al-Araf: 24)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'اهبطوا منها جميعا go down from it together from the light which was on earth the good for you and you will have therein dwelling and enjoyment for a time al araf 24', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 31, NULL, 'And:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'verse', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 32, NULL, 'فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', '', 'فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', NULL, 7, 25, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'فيها تحيون وفيها تموتون ومنها تخرجون', 'فيها تحيون وفيها تموتون ومنها تخرجون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 33, NULL, 'فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ"Therein you will live, and therein you will die, and from it you will be brought forth." (Al-Araf: 25)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'فيها تحيون وفيها تموتون ومنها تخرجون therein you will live and therein you will die and from it you will be brought forth al araf 25', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 34, NULL, 'And:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 35, NULL, 'Sayingيَا بَنِي آدَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَارِي سَوْآتِكُمْ وَرِيشًا ۖ وَلِبَاسُ التَّقْوَىٰ ذَٰلِكَ خَيْرٌ ۚ ذَٰلِكَ مِنْ آيَاتِ اللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ"O children of Adam, We have bestowed upon you clothing to conceal your private parts, and as adornment. But the clothing of righteousness — that is best. That is from the signs of God, that perhaps they will remember." (Al-Araf: 26)', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'sayingيا بني ادم قد انزلنا عليكم لباسا يواري سواتكم وريشا ولباس التقوي ذلك خير ذلك من ايات الله لعلهم يذكرون o children of adam we have bestowed upon you clothing to conceal your private parts and as adornment but the clothing of righteousness that is best that is from the signs of god that perhaps they will remember al araf 26', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 36, NULL, 'So God brought Adam down from the limit of interpretation without a veil; yet He did not strip him of his substance. What was connected to him by way of material descended with him from the upper celestial limits, and remained connected to the signs of God He has just named. And the same arrangement has been put in place in the word of his son.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'so god brought adam down from the limit of interpretation without a veil yet he did not strip him of his substance what was connected to him by way of material descended with him from the upper celestial limits and remained connected to the signs of god he has just named and the same arrangement has been put in place in the word of his son', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 37, NULL, 'The Messenger of God, peace and blessings be upon him, said: "I take the revelation from Jibril, and Jibril takes it from Mikail, and Mikail takes it from Israfil, and Israfil takes it from the Tablet (اَللَّوْح), and the Tablet takes it from the Pen (اَلْقَلَم)." The support is connected to the word of the Five Upper Limits, and these are connected, on the receiving side, to the Five Lower Limits. The Upper Limits are those we have named. The Lower Limits are the Foundation (الْأَسَاس), the Imams, the Proofs (اَلْحُجَج), the Captains (النُّقَبَاء), the Lords of the Islands (أَصْحَابُ الْجَزَائِر), and the Wings (الْأَجْنِحَة), who are the preachers (الدُّعَاة).', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'the messenger of god peace and blessings be upon him said i take the revelation from jibril and jibril takes it from mikail and mikail takes it from israfil and israfil takes it from the tablet اللوح and the tablet takes it from the pen القلم the support is connected to the word of the five upper limits and these are connected on the receiving side to the five lower limits the upper limits are those we have named the lower limits are the foundation الاساس the imams the proofs الحجج the captains النقباء the lords of the islands اصحاب الجزاير and the wings الاجنحه who are the preachers الدعاه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 38, NULL, 'The sixth of the two ranks of limits is the rebel. Satan became an enemy to Adam and against him, from God and against God — whether the Adam he opposed is a Speaker (اَلنَّاطِق), a Silent One (اَلصَّامِت), an imam, or a Proof (اَلْحُجَّة). Whoever takes them as guardians and is loyal to them is of Adam''s party, which is the party of God Almighty; and that includes everyone who is obedient to the guardianship of God and of the Prophet, peace and blessings be upon him. Whoever has dismissed their command or claimed their place is of the party of Iblis — whom Satan possessed and who forgot the remembrance (ذِكْر) of God, and forgot too that the matter is deferred by His own saying, that the last of them is the remembrance of God; and the remembrance of God here is, in the inner sense, His guardians who are remembered, and they are the ones who have remembered Him.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'the sixth of the two ranks of limits is the rebel satan became an enemy to adam and against him from god and against god whether the adam he opposed is a speaker الناطق a silent one الصامت an imam or a proof الحجه whoever takes them as guardians and is loyal to them is of adams party which is the party of god almighty and that includes everyone who is obedient to the guardianship of god and of the prophet peace and blessings be upon him whoever has dismissed their command or claimed their place is of the party of iblis whom satan possessed and who forgot the remembrance ذكر of god and forgot too that the matter is deferred by his own saying that the last of them is the remembrance of god and the remembrance of god here is in the inner sense his guardians who are remembered and they are the ones who have remembered him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 39, NULL, 'What happened to Adam and Hawwa happened, in turn, in their descendants. The descendants did not differ in their kinds, I mean male and female, just as Adam and Hawwa did not differ. So obedience and disobedience among them played out in the same way, on the same pattern. The beginning of Adam''s creation and what befell him parallels what happened to his son at the beginning of his command and his settling in this house. God Almighty''s settling of Adam and Hawwa in Paradise after what had befallen them parallels His settling, in faith, of those of their descendants who believed and were reconciled — the ones who are of their party. The repentance of those who repent corresponds to the words written for Adam, and the destruction of those of them who perished in disobedience and met the punishment of God by disbelief (الْكُفْر) and by doing what He forbade corresponds to Iblis''s hold on them, and to the fact that they were of his party. They cut themselves off from Adam, they left his lineage, they took the entrance of those who came from him without being him, and they became other than him — that is, other than Adam — because they were severed from him. God Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'what happened to adam and hawwa happened in turn in their descendants the descendants did not differ in their kinds i mean male and female just as adam and hawwa did not differ so obedience and disobedience among them played out in the same way on the same pattern the beginning of adams creation and what befell him parallels what happened to his son at the beginning of his command and his settling in this house god almightys settling of adam and hawwa in paradise after what had befallen them parallels his settling in faith of those of their descendants who believed and were reconciled the ones who are of their party the repentance of those who repent corresponds to the words written for adam and the destruction of those of them who perished in disobedience and met the punishment of god by disbelief الكفر and by doing what he forbade corresponds to ibliss hold on them and to the fact that they were of his party they cut themselves off from adam they left his lineage they took the entrance of those who came from him without being him and they became other than him that is other than adam because they were severed from him god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 40, NULL, 'وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُ مِنْهُمْ"And whoever takes them as allies among you, then indeed he is of them." (Al-Maidah: 51)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'ومن يتولهم منكم فانه منهم and whoever takes them as allies among you then indeed he is of them al maidah 51', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 41, NULL, 'Whoever takes Iblis as an ally is from him: they become his sons by calling, his family by calling, other than Adam. God Almighty said of the son of Noah when he disobeyed:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'whoever takes iblis as an ally is from him they become his sons by calling his family by calling other than adam god almighty said of the son of noah when he disobeyed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 42, NULL, 'إِنَّهُ لَيْسَ مِنْ أَهْلِكَ"He is not one of your family."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'انه ليس من اهلك he is not one of your family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 43, NULL, 'He named the disobedient as the party of Satan and called them by his name. He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'he named the disobedient as the party of satan and called them by his name he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 44, NULL, 'إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ مُّبِينٌ"Indeed, Satan is a clear enemy."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'ان الشيطان لكم عدو مبين indeed satan is a clear enemy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 45, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 46, NULL, 'إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ"Over My servants you shall have no authority."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'ان عبادي ليس لك عليهم سلطان over my servants you shall have no authority', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 47, NULL, 'These are those who follow Adam through his son.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'these are those who follow adam through his son', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 48, NULL, 'Sayingإِلَّا مَنِ اتَّبَعَكَ مِنَ الْغَاوِينَ ۝ وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ ۝ لَهَا سَبْعَةُ أَبْوَابٍ لِّكُلِّ بَابٍ مِّنْهُمْ جُزْءٌ مَّقْسُومٌ"Except for those of the deviators who follow you... It has seven gates; to each gate is an allotted portion." (Al-Hijr: 42-44)', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'sayingالا من اتبعك من الغاوين وان جهنم لموعدهم اجمعين لها سبعه ابواب لكل باب منهم جزء مقسوم except for those of the deviators who follow you it has seven gates to each gate is an allotted portion al hijr 42 44', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 49, NULL, 'By "the gates" I mean the messengers, the gates of the pure outward truth — and for each of them there is a known sacred law. Some of those who answered that law in the wrong way gave themselves over to the Fire. Of this the Prophet, God''s blessings upon him, said to Ali: "You are the Distributor of the Fire (قَيِّم النَّار)" — for he will say to it on the Day of Resurrection: "This one is yours, take him; and this one is mine, leave him."', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'by the gates i mean the messengers the gates of the pure outward truth and for each of them there is a known sacred law some of those who answered that law in the wrong way gave themselves over to the fire of this the prophet gods blessings upon him said to ali you are the distributor of the fire قيم النار for he will say to it on the day of resurrection this one is yours take him and this one is mine leave him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 50, NULL, 'Iblis''s opposition to Adam and his enmity toward him is exactly the opposition of the enemies of the messengers to the messengers, and the hostility their followers carry against them. God Almighty says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'ibliss opposition to adam and his enmity toward him is exactly the opposition of the enemies of the messengers to the messengers and the hostility their followers carry against them god almighty says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 51, NULL, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوًّا شَيَاطِينَ الْإِنسِ وَالْجِنِّ"And thus We have made for every prophet an enemy — devils from among humankind and the jinn." (Al-Anam: 112)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'وكذلك جعلنا لكل نبي عدوا شياطين الانس والجن and thus we have made for every prophet an enemy devils from among humankind and the jinn al anam 112', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 52, NULL, 'The sinner is the son of Adam who persists in his sin, who neither repents of it nor casts it off. He is Satan in his persistence; he has walked out of Adam''s party and into Satan''s. He has taken Satan''s entrance and arrived where Iblis is arriving, at the punishment of God. The one who turns back from what he has done, and the obedient born of Adam, are Adam''s party, which is the party of God:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'the sinner is the son of adam who persists in his sin who neither repents of it nor casts it off he is satan in his persistence he has walked out of adams party and into satans he has taken satans entrance and arrived where iblis is arriving at the punishment of god the one who turns back from what he has done and the obedient born of adam are adams party which is the party of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 53, NULL, 'Sayingوَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَن يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَىٰ مَا فَعَلُوا وَهُمْ يَعْلَمُونَ ۝ أُولَٰئِكَ جَزَاؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ الْعَامِلِينَ"And those who, when they commit an immorality or wrong themselves, remember God and seek forgiveness for their sins — and who can forgive sins except God? — and they do not persist in what they have done while they know. Their reward is forgiveness from their Lord, and gardens beneath which rivers flow, wherein they shall abide forever. How excellent is the reward of those who labor." (Ali Imran: 135-136)', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'sayingوالذين اذا فعلوا فاحشه او ظلموا انفسهم ذكروا الله فاستغفروا لذنوبهم ومن يغفر الذنوب الا الله ولم يصروا علي ما فعلوا وهم يعلمون اوليك جزاوهم مغفره من ربهم وجنات تجري من تحتها الانهار خالدين فيها ونعم اجر العاملين and those who when they commit an immorality or wrong themselves remember god and seek forgiveness for their sins and who can forgive sins except god and they do not persist in what they have done while they know their reward is forgiveness from their lord and gardens beneath which rivers flow wherein they shall abide forever how excellent is the reward of those who labor ali imran 135 136', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 54, NULL, 'God Almighty granted Adam the benefit of His will: He settled him on the earth, made him a successor over those He had placed there. Adam''s descendants multiplied, and the proof of God was established against them, and Adam was the one who carried the message to them. He entrusted (أَوْصَى) his son Habil — Abel; and his brother Qabil envied him and killed him, as God Almighty has described. The killing happened during Adam''s own lifetime, so that the meaning of the will (اَلْوَصِيَّة) and what it costs would be made plain to him in his own house. Whoever entertained evil thoughts after that, persisted in disobedience, and did not repent of his sin, was of Satan''s party.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'god almighty granted adam the benefit of his will he settled him on the earth made him a successor over those he had placed there adams descendants multiplied and the proof of god was established against them and adam was the one who carried the message to them he entrusted اوصي his son habil abel and his brother qabil envied him and killed him as god almighty has described the killing happened during adams own lifetime so that the meaning of the will الوصيه and what it costs would be made plain to him in his own house whoever entertained evil thoughts after that persisted in disobedience and did not repent of his sin was of satans party', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 55, NULL, 'Then God granted Adam, from among his descendants, a son whom Adam named Hibat Allah (هِبَةُ اللّٰه) — "the Gift of God." To him Adam entrusted the inner knowledge. He took him into confidence and commanded him to keep the secret, fearing that Qabil would kill him as he had killed Habil. From that fear, made into a discipline, the custom (سُنَّة) was established of guarding the secrets of the covenant and keeping them hidden.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'then god granted adam from among his descendants a son whom adam named hibat allah هبه الله the gift of god to him adam entrusted the inner knowledge he took him into confidence and commanded him to keep the secret fearing that qabil would kill him as he had killed habil from that fear made into a discipline the custom سنه was established of guarding the secrets of the covenant and keeping them hidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 56, NULL, 'God prepared Adam for the reward He had set aside for him in the Abode of Decision, and after him the matter of the imamate passed by will to Shith — to Seth. With Seth''s son it went on as we have said: remembrance after remembrance, station after station, imam after imam, until the matter reached the one God mentioned in His Book concerning Idris, peace be upon him. All of this was within the Cycle of Adam, God''s blessings upon him. Then the cycle came to its close with the era of Noah.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'god prepared adam for the reward he had set aside for him in the abode of decision and after him the matter of the imamate passed by will to shith to seth with seths son it went on as we have said remembrance after remembrance station after station imam after imam until the matter reached the one god mentioned in his book concerning idris peace be upon him all of this was within the cycle of adam gods blessings upon him then the cycle came to its close with the era of noah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 57, NULL, 'God sent Noah as a messenger speaking a sacred law different from the law of Adam. The Almighty says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'god sent noah as a messenger speaking a sacred law different from the law of adam the almighty says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 58, NULL, 'لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا"For each of you We have appointed a law and a way." (Al-Maidah: 48)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'لكل جعلنا منكم شرعه ومنهاجا for each of you we have appointed a law and a way al maidah 48', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 59, NULL, 'Adam''s cycle ended when Noah''s era came upon them. None of these messengers rose to messengership until he had first held fast to the law of those before him; the predecessor''s covenant was taken up, and he bound himself to it. The Almighty says:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'adams cycle ended when noahs era came upon them none of these messengers rose to messengership until he had first held fast to the law of those before him the predecessors covenant was taken up and he bound himself to it the almighty says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 60, NULL, 'Sayingوَإِذْ أَخَذْنَا مِنَ النَّبِيِّينَ مِيثَاقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَاهِيمَ وَمُوسَىٰ وَعِيسَى ابْنِ مَرْيَمَ ۖ وَأَخَذْنَا مِنْهُم مِّيثَاقًا غَلِيظًا"And when We took from the prophets their covenant — and from you, and from Noah, Abraham, Moses, and Jesus, son of Mary — We took from them a solemn covenant." (Al-Ahzab: 7)', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'sayingواذ اخذنا من النبيين ميثاقهم ومنك ومن نوح وابراهيم وموسي وعيسي ابن مريم واخذنا منهم ميثاقا غليظا and when we took from the prophets their covenant and from you and from noah abraham moses and jesus son of mary we took from them a solemn covenant al ahzab 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 61, NULL, 'We have spoken of this above. Hold to what I have recited to you of the interpretation of what God has revealed to you. Know the truth of what is in it, so that you may worship Him by it, and grasp the inner revelation — the inner unveiling — of which the Almighty has informed you in His Book: that none knows it but He and those firmly rooted in knowledge — His friends (أَوْلِيَاء), whose authority God has favored you with, whose following has placed you in His party. He has promised you His reward. Through that following He has lifted you out of the party of Satan — whose punishment you have learned to dread.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'we have spoken of this above hold to what i have recited to you of the interpretation of what god has revealed to you know the truth of what is in it so that you may worship him by it and grasp the inner revelation the inner unveiling of which the almighty has informed you in his book that none knows it but he and those firmly rooted in knowledge his friends اولياء whose authority god has favored you with whose following has placed you in his party he has promised you his reward through that following he has lifted you out of the party of satan whose punishment you have learned to dread', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 62, NULL, 'Carry out what God Almighty has prescribed. Be sincere before His face. Perform what He has made obligatory, outwardly and inwardly. Whoever of you has committed a sin, let him repent to God from it, and let him take refuge in the guardian (اَلْوَالِي) of his own time, so that God may forgive him and lift the sin from him. He becomes one of those God has promised — the repentant, who seek forgiveness for their own sins and for their guardians — that he may belong to the party of your father Adam, and to the party of the friends of God from his progeny, which is حِزْبُ اللّٰه.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'carry out what god almighty has prescribed be sincere before his face perform what he has made obligatory outwardly and inwardly whoever of you has committed a sin let him repent to god from it and let him take refuge in the guardian الوالي of his own time so that god may forgive him and lift the sin from him he becomes one of those god has promised the repentant who seek forgiveness for their own sins and for their guardians that he may belong to the party of your father adam and to the party of the friends of god from his progeny which is حزب الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 63, NULL, 'Leave the party of Satan: those who persisted in their sins as Satan persisted in his, and so became satanic like him. Just as Satan despaired of his Lord, do not despair of your Lord or of His mercy upon you. The Almighty said:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'leave the party of satan those who persisted in their sins as satan persisted in his and so became satanic like him just as satan despaired of his lord do not despair of your lord or of his mercy upon you the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 64, NULL, 'لَا تَيْأَسُوا مِن رَّوْحِ اللَّهِ ۖ إِنَّهُ لَا يَيْأَسُ مِن رَّوْحِ اللَّهِ إِلَّا الْقَوْمُ الْكَافِرُونَ"Do not despair of the mercy of God; surely none despair of God''s mercy except the disbelieving people." (Yusuf: 87)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'لا تياسوا من روح الله انه لا يياس من روح الله الا القوم الكافرون do not despair of the mercy of god surely none despair of gods mercy except the disbelieving people yusuf 87', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 65, NULL, 'And as I have cited from the words of the Almighty to His friend Ibrahim al-Khalil:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'and as i have cited from the words of the almighty to his friend ibrahim al khalil', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 66, NULL, 'وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِ إِلَّا الضَّالُّونَ"And who despairs of the mercy of his Lord but those who go astray?" (Al-Hijr: 56)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'ومن يقنط من رحمه ربه الا الضالون and who despairs of the mercy of his lord but those who go astray al hijr 56', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 67, NULL, 'May God guide you to what He loves and is pleased with, protect you from violating His prohibitions and disobeying Him, and open for you the gates of obedience to His friends. May God bless His servant Muhammad and the pure imams from his progeny (عِتْرَة), and peace be upon him.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'may god guide you to what he loves and is pleased with protect you from violating his prohibitions and disobeying him and open for you the gates of obedience to his friends may god bless his servant muhammad and the pure imams from his progeny عتره and peace be upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 68, NULL, 'A word here on the architecture of cycles, since I have just spoken of the close of Adam''s and the opening of Noah''s. In our tradition, cycles are of two kinds: the major and the minor. The major cycles open at Adam and close at the Resurrection. The minor cycles open with each Speaker-prophet (اَلنَّاطِق) — the one sent with a sacred law — and close with the next Speaker. The major cycle we are now inside is divided into seven minor cycles: Adam, Noah, Abraham, Moses, Jesus, Muhammad, and the awaited الْقَائِم, the Standing One. Each minor cycle contains a Resident Imam (الْإِمَامُ الْمُقِيم), a permanent Imam, a Foundation (أَسَاس), a Speaker (اَلنَّاطِق), and seven Imams. The Resident Imam is the one who instructs the Speaker in his mission. The Concluder is the one who closes the cycle. The Foundation is the Speaker''s proof in his lifetime and inherits his will after him; he is the master of the inner interpretation, corresponding to the Speaker, who holds the knowledge of the outward sacred law.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'a word here on the architecture of cycles since i have just spoken of the close of adams and the opening of noahs in our tradition cycles are of two kinds the major and the minor the major cycles open at adam and close at the resurrection the minor cycles open with each speaker prophet الناطق the one sent with a sacred law and close with the next speaker the major cycle we are now inside is divided into seven minor cycles adam noah abraham moses jesus muhammad and the awaited القايم the standing one each minor cycle contains a resident imam الامام المقيم a permanent imam a foundation اساس a speaker الناطق and seven imams the resident imam is the one who instructs the speaker in his mission the concluder is the one who closes the cycle the foundation is the speakers proof in his lifetime and inherits his will after him he is the master of the inner interpretation corresponding to the speaker who holds the knowledge of the outward sacred law', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 69, NULL, 'In Adam''s era, the Resident Imam was Hunayd, and his proofs (حُجَج) were twelve — among them Iblis, who refused to submit to Adam. Adam descended at Aden, perhaps the Aden of Yemen, then migrated to Mecca al-Mukarrama, whose name was then Faran (فَارَان), where he died at nine hundred and thirty years of age and was buried at the foot of Abu Qubays (أَبُو قُبَيْس). Before that, he bequeathed the matter to his son Shith, called Hibat Allah. Shith was born in the year 230 from Adam''s descent, died in 1142, lived 912 years, and bequeathed to his son Anush. Anush, born in 435 from Adam''s descent, died in 1385, lived 950 years, and bequeathed to his son Qaynan. Qaynan, born in 625, died in 1535, lived 910 years, and bequeathed to his son Mahlail. Mahlail, born in 795, died in 1690, lived 895 years, and bequeathed to his son Yard. Yard, born in 960, died in 1922, lived 962 years, and bequeathed to his son Akhnukh. Akhnukh — Enoch — born in 1122, was raised up in 1487, lived 365 years, and bequeathed to his son Mattu Shalih — whose name was also Idris, also called Hermes the Thrice-Blessed, the first to write with the pen. Methuselah was born in 1287 and died in 2242, the year of the flood; his death (الْمَوْت) came just before it. He lived 955 years and bequeathed to his son Lamak — Lamech. Lamak, born in 1454 from Adam''s descent, died in 2346, one hundred and four years after the flood, having lived 891 years. He completed the cycle of Adam and was the seventh of its imams. From him the matter passed to his son Noah, after the divine will had decreed the changing of the old law and its replacement by a new one: the law of Noah, the Second Speaker.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'in adams era the resident imam was hunayd and his proofs حجج were twelve among them iblis who refused to submit to adam adam descended at aden perhaps the aden of yemen then migrated to mecca al mukarrama whose name was then faran فاران where he died at nine hundred and thirty years of age and was buried at the foot of abu qubays ابو قبيس before that he bequeathed the matter to his son shith called hibat allah shith was born in the year 230 from adams descent died in 1142 lived 912 years and bequeathed to his son anush anush born in 435 from adams descent died in 1385 lived 950 years and bequeathed to his son qaynan qaynan born in 625 died in 1535 lived 910 years and bequeathed to his son mahlail mahlail born in 795 died in 1690 lived 895 years and bequeathed to his son yard yard born in 960 died in 1922 lived 962 years and bequeathed to his son akhnukh akhnukh enoch born in 1122 was raised up in 1487 lived 365 years and bequeathed to his son mattu shalih whose name was also idris also called hermes the thrice blessed the first to write with the pen methuselah was born in 1287 and died in 2242 the year of the flood his death الموت came just before it he lived 955 years and bequeathed to his son lamak lamech lamak born in 1454 from adams descent died in 2346 one hundred and four years after the flood having lived 891 years he completed the cycle of adam and was the seventh of its imams from him the matter passed to his son noah after the divine will had decreed the changing of the old law and its replacement by a new one the law of noah the second speaker', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 70, NULL, 'In the name of God, the Most Gracious, the Most Merciful. Praise be to God, Lord of the Worlds. May God bless Muhammad, the Seal of the Prophets, and his guardian (وَصِي) Ali ibn Abi Talib, the best of guardians, and the pure imams from his successive progeny, from his loins until the Day of Judgment, and beyond.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'in the name of god the most gracious the most merciful praise be to god lord of the worlds may god bless muhammad the seal of the prophets and his guardian وصي ali ibn abi talib the best of guardians and the pure imams from his successive progeny from his loins until the day of judgment and beyond', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 71, NULL, 'God Almighty sent Noah, God''s blessings upon him, as a prophet bearing a new sacred law, after the law of Adam had altered and corruption had increased among Adam''s descendants. Noah called the people to his law: to worship God Almighty and affirm His oneness outwardly. God informed him in His Book:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'god almighty sent noah gods blessings upon him as a prophet bearing a new sacred law after the law of adam had altered and corruption had increased among adams descendants noah called the people to his law to worship god almighty and affirm his oneness outwardly god informed him in his book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 72, NULL, 'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ فَقَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ"We sent Noah to his people, saying: O my people, worship God; you have no god other than Him. Will you not be conscious of Him?" (Al-Araf: 59)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'لقد ارسلنا نوحا الي قومه فقال يا قوم اعبدوا الله ما لكم من اله غيره افلا تتقون we sent noah to his people saying o my people worship god you have no god other than him will you not be conscious of him al araf 59', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 73, NULL, 'The weak among them responded; the arrogant turned him down. Those who were content with the law of Adam answered him with a line so familiar I want you to hear it carefully:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'the weak among them responded the arrogant turned him down those who were content with the law of adam answered him with a line so familiar i want you to hear it carefully', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 74, NULL, 'مَا أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا"You are nothing but a human being like us." — that is: you have come to us in the same outward form we already know. We hold in our hands what we inherited from those before you; you began with us with the same things they began with us. You are bashar, just as we are.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'ما انت الا بشر مثلنا you are nothing but a human being like us that is you have come to us in the same outward form we already know we hold in our hands what we inherited from those before you you began with us with the same things they began with us you are bashar just as we are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 75, NULL, 'The word الْبَشَر in our language names the visible skin, and the touch of skin to skin. So the meaning of their answer is this: what he has brought us we already have. He is like us, and has no merit over us. And they went on:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'the word البشر in our language names the visible skin and the touch of skin to skin so the meaning of their answer is this what he has brought us we already have he is like us and has no merit over us and they went on', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 76, NULL, 'وَمَا نَرَاكَ اتَّبَعَكَ إِلَّا الَّذِينَ هُمْ أَرَاذِلُنَا بَادِيَ الرَّأْيِ"None follows you but the lowliest among us, with no real thought." (Hud: 27)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'وما نراك اتبعك الا الذين هم اراذلنا بادي الراي none follows you but the lowliest among us with no real thought hud 27', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 77, NULL, 'By "lowliest" they meant — in knowledge. They had their own scholars, and they measured every newcomer against the standing of those scholars. We have already said that the Speaker (اَلنَّاطِق) is a caller to the outward; and those who pride themselves on the outward are precisely the ones who do not recognize a new outward when it arrives.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'by lowliest they meant in knowledge they had their own scholars and they measured every newcomer against the standing of those scholars we have already said that the speaker الناطق is a caller to the outward and those who pride themselves on the outward are precisely the ones who do not recognize a new outward when it arrives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 78, NULL, 'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِي وَاتَّبَعُوا مَن لَّمْ يَزِدْهُ مَالُهُ وَوَلَدُهُ إِلَّا خَسَارًا"Noah said: My Lord, they have disobeyed me and followed one whose wealth and child have only increased him in loss." (Nuh: 21)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'قال نوح رب انهم عصوني واتبعوا من لم يزده ماله وولده الا خسارا noah said my lord they have disobeyed me and followed one whose wealth and child have only increased him in loss nuh 21', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 79, NULL, 'He means: their outward scholars, whose knowledge added nothing, who called Noah''s hearers to nothing but loss. Wealth (اَلْمَال), in the inner sense, is like knowledge; the child (الْوَلَد) is like the responder — the one who answers a caller''s call and takes on what is preached to him, whether rightly or wrongly.', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'he means their outward scholars whose knowledge added nothing who called noahs hearers to nothing but loss wealth المال in the inner sense is like knowledge the child الولد is like the responder the one who answers a callers call and takes on what is preached to him whether rightly or wrongly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 80, NULL, 'Sayingوَمَكَرُوا۟ مَكْرًۭا كُبَّارًۭا وَقَالُوا۟ لَا تَذَرُنَّ آلِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّۭا وَلَا سُوَاعًۭا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًۭا', '', 'وَمَكَرُوا۟ مَكْرًۭا كُبَّارًۭا وَقَالُوا۟ لَا تَذَرُنَّ آلِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّۭا وَلَا سُوَاعًۭا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًۭا', 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'sayingومكروا مكرا كبارا وقالوا لا تذرن الهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا', 'ومكروا مكرا كبارا وقالوا لا تذرن الهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 81, NULL, 'Sayingوَمَكَرُوا مَكْرًا كُبَّارًا ۝ وَقَالُوا لَا تَذَرُنَّ آلِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا"And they devised a great plot, and they said: Do not forsake your gods, and do not forsake Wadd, Suwa, Yaghuth, Yauq, or Nasr." (Nuh: 22-23)', '', NULL, 'Saying', NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'sayingومكروا مكرا كبارا وقالوا لا تذرن الهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا and they devised a great plot and they said do not forsake your gods and do not forsake wadd suwa yaghuth yauq or nasr nuh 22 23', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 82, NULL, 'These named idols, in the inner sense, are the scholars from whom that people took their knowledge — the elders among their scholars whom they had come to revere, and who in turn misled a great many of God''s creation. Noah, peace be upon him, called them outwardly for a long time. And then God Almighty entrusted him with the verdict:', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'these named idols in the inner sense are the scholars from whom that people took their knowledge the elders among their scholars whom they had come to revere and who in turn misled a great many of gods creation noah peace be upon him called them outwardly for a long time and then god almighty entrusted him with the verdict', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'verse', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 83, NULL, 'إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ آمَنَ', '', 'إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ آمَنَ', NULL, 11, 36, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'الي نوح انه لن يومن من قومك الا من قد امن', 'الي نوح انه لن يومن من قومك الا من قد امن');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'chapter', 'two parties and the line to noah', '4. Two Parties and the Line to Noah', 84, NULL, 'أَنَّهُ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ آمَنَ"None of your people will believe except those who have already believed." (Hud: 36)', '', NULL, NULL, NULL, NULL, 'asas al taweel volume 1 adam 4 two parties and the line to noah', 'انه لن يومن من قومك الا من قد امن none of your people will believe except those who have already believed hud 36', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'episode', NULL, 'What Ismaili Interpretation Is', 0, 1, 'What Ismaili Interpretation Is The editor''s introduction to Asas al-Ta''wil — Arif Tamir''s 1960 Beirut framing of why this 10th-century Fatimid treatise on inner interpretation was kept in private custody for a thousand years, what the Ismailis mean by ta''wil (as distinct from tafsir), why the Speaker bears revelation and the Imam- Foundation bears its inner meaning, and how al-Nu''man''s two books — Da''a''im al-Islam and this one — together form the body and soul of the Fatimid intellectual project. Sets up the six Speaker-Prophet chapters that follow: Adam, Noah, Ibrahim, Moses, Jesus, Muhammad. The seventh chapter, on the Awaited Imam, is deliberately unwritten.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'episode', NULL, 'The Call to Inner Meaning', 0, 2, 'The Call to Inner Meaning Al-Nu''man''s own opening of Asas al-Ta''wil. He explains why he wrote a second book after his apparent-law volume Da''a''im al-Islam, why inner interpretation has to be taught by stages — milk before solid food, suckling for two years, symbols before subtleties — and why the testimony "There is no god but Allah," from the very first day the Prophet spoke it, already contained the whole sacred law, against the common opinion that says the easy creed came first and the heavy obligations later. Sets up the structural claim that the next chapter will unfold: that every created thing is paired, outward and inward, body and soul — and that the Creator is described by none of the pairs.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'episode', NULL, 'The Four Limits of the Shahada', 0, 3, 'The Four Limits of the Shahada Al-Nu''man opens the testimony itself and shows what is inside it. The shahada has four words; those four words stand for four limits, two above and two below. Above are the Pen and the Preserved Tablet — named in the prophetic hadith that says the first thing God created was the Pen. Below are the Speaker, the prophet who articulates the sacred law in his time, and the Silent One, the Imam-Foundation who is master of its interpretation. To recognize all four is to complete the shahada. The philosophers affirmed the upper two and called them intellect and soul, but denied the lower two and so left the testimony broken. The chapter then maps the seven Speaker-Prophets across history — Adam, Noah, Ibrahim, Moses, Jesus, Muhammad, and the awaited al-Qa''im — and the seven Imams in each cycle, the twelve successors arranged as proofs in every age, and the seven-plus-twelve nineteen that the Qur''an names. It closes on the second testimony to the Messenger as the branches of the first, and on al-Sadiq''s verdict that faith encompasses Islam but Islam does not encompass faith.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'episode', NULL, 'Adam, the Tree, and the Pact of Iblis', 0, 4, 'Adam, the Tree, and the Pact of Iblis Al-Nu''man opens his interpretation of the prophetic cycles at the origin of the lower hadd of Imamate itself — Adam, peace be upon him. The Qur''anic scene of the angels'' objection, the formation of Adam from clay, the long pause before the spirit, the teaching of the names, Iblis''s refusal to prostrate, the creation of Eve, the garden, the forbidden tree, the pact of respite, the fall, the repentance — every element is read on its inner side. The hadd that Iblis vacated is filled by Eve as Adam''s twelve-rank hujja. The garden is the rank of supportive knowledge, al-ta''yid. The tree is not wheat, fig, or grape, but a likeness for the Master of the Resurrection — the disclosure entrusted to him alone, seized prematurely. Adam''s stripping is the loss of the garment of piety, which is the word. His repentance restores him to the rank of caliph and Imam, and the Imamate begins from him as the architecture of the four limits requires.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('asaas-al-taveel-vol-01', 'episode', NULL, 'The Two Parties and the Line to Noah', 0, 5, 'The Two Parties and the Line to Noah Al-Nu''man closes the first prophetic cycle. He develops the two- parties doctrine at length, threading together the Qur''an''s own naming of Hizb Allah against the party of Satan. He refuses the popular literalism that froze the forbidden tree into wheat, fig, or grape and read human fingernails as its residue. He refuses, by name, the inherited Jewish-source tale of Adam and Eve hiding naked among the trees while God walked there asking "Where are you?" — calling out Ka''b al-Ahbar and Abdullah ibn Salam as the channels through which the material entered the tradition. He rehabilitates Adam to the rank of caliph and Imam. He gives the chain of five upper and five lower limits in the Prophet''s own voice. He walks the lineage from Adam through Seth, Idris/Enoch, and the seven Imams of the first cycle down to Lamech, who completes the cycle and hands the matter to Noah. Then he opens the chapter on Noah, Hud, and Salih, and the listener hears Noah''s people refuse him in the same shape Iblis had refused God — "you are nothing but a human being like us." The architecture''s claim on history begins to walk.
